/* ===== interview2.js ===== */
(function(W){"use strict";W.PBI_IV_BANK=W.PBI_IV_BANK||[],W.PBI_IV_STAR=W.PBI_IV_STAR||[],W.PBI_IV_ASK=W.PBI_IV_ASK||[],W.PBI_IV_TAKEHOME=W.PBI_IV_TAKEHOME||{},W.PBI_INTERVIEW=W.PBI_INTERVIEW||[],W.PBI_IV_BANK.push({id:"iv-b001",role:"analist",cat:"Senaryo",q:"Bir bölge müdürü, primleri hedef gerçekleşmesine bağlı olduğu için iadeleri hesaptan çıkarmanı istiyor. Finans ise iadelerin düşülmesini istiyor. Ne yaparsın?",weak:"Müdür ne istiyorsa onu yaparım, sonuçta raporu o kullanıyor. Finans kendi rakamını ayrıca hesaplayabilir.",strong:"Bu teknik değil, yönetişim sorusu; kararı ben vermem ama kararın görünür biçimde verilmesini sağlarım. Önce iki tanımın farkını sayıyla gösteririm: aynı dönemde `[Net Satış]` ile `[Net Satış] - [İade Tutarı]` yan yana, bölge kırılımında. Sonra prim tanımının sahibini (genellikle finans ya da İK) bulur, iki tarafı aynı toplantıya çağırırım. Karar çıkana kadar mevcut tanımı değiştirmem. Karar çıkınca ölçüyü açık adla yazarım (ör. “Prim Bazlı Satış”), açıklamasına tanımı ve kararın tarihini eklerim. Bir kullanıcının isteğiyle sessizce tanım değiştirmek, raporun tüm şirketteki güvenilirliğini bozar.",why:"Çıkar çatışmasını fark ediyor, kararı doğru sahibine götürüyor, farkı sayıyla görünür kılıyor ve sessiz tanım değişikliğinin riskini adlandırıyor.",follow:"Karar müdürün istediği yönde çıkarsa ama sen bunun yanıltıcı olduğunu düşünüyorsan ne yaparsın?"},{id:"iv-b002",role:"analist",cat:"Senaryo",q:"Üç ay önce yayımladığın bir rapor neredeyse hiç açılmıyor. Ne yaparsın?",weak:"Raporu daha güzel hâle getirir, tekrar duyururum. Belki kullanıcılar haberdar değildir.",strong:"Önce tahmin yerine veriye bakarım: çalışma alanındaki kullanım ölçümleri (usage metrics) raporu kimlerin, hangi sayfaları, ne sıklıkla açtığını gösterir. Sonra hedef kullanıcılardan üç dört kişiyle kısa görüşmeler yaparım ve “Bu kararı bugün nasıl veriyorsunuz?” diye sorarım. Genellikle sebeplerden biri çıkar: soru değişmiştir, rakamlar başka bir kaynakla tutmuyordur, rapor iş akışının dışında kalmıştır (e-postayla Excel gelmeye devam ediyordur) ya da sayfa çok yavaştır. Sebebe göre ya raporu küçültür ve bir uygulamaya (app) koyarım, ya abonelik ekleyip eski Excel’i kaldırma sözü alırım, ya da raporu emekliye ayırırım. Kullanılmayan raporu yaşatmak bakım yükü ve kafa karışıklığıdır.",why:"Ölçerek başlıyor, kullanıcıyla konuşarak kök nedeni arıyor ve raporu kapatmayı da meşru bir seçenek olarak görüyor.",follow:"Kullanım ölçümlerinde bir sayfanın hiç açılmadığını görürsen o sayfayı silmeden önce kime danışırsın?"},{id:"iv-b003",role:"analist",cat:"Senaryo",q:"Pazartesi sabahı genel müdür “Geçen hafta satışlar neden düştü?” diye soruyor ve bir saatin var. Nasıl ilerlersin?",weak:"Satış grafiğine bakar, düşüşün olduğu günleri bulur ve rapora eklerim.",strong:"Önce düşüşün gerçek olup olmadığını kontrol ederim: veri tam yenilenmiş mi, son günlerin siparişleri hâlâ “Kargoda” durumunda mı, karşılaştırılan iki hafta aynı gün sayısına ve aynı hafta sonu sayısına sahip mi? Sonra farkı parçalara ayırırım: kanal (`Satislar[Kanal]`), kategori, sipariş sayısı ve ortalama sepet. Düşüş `[Sipariş Sayısı]`ndan mı geliyor `[Ortalama Sepet]`ten mi, bunu ayırmak sebebi büyük ölçüde daraltır. İptal oranına da bakarım; `[İptal Oranı %]` sıçradıysa bu bir operasyon sorunudur. Bir saatin sonunda tek cümlelik bir cevap veririm: “Düşüşün çoğu Web kanalında, sipariş sayısında; sepet tutarı aynı.” Bilmediğim kısmı da açıkça söyler, ne zaman tamamlayacağımı belirtirim.",why:"Önce verinin güvenilirliğini sınıyor, farkı bilinen ölçülerle sistematik biçimde ayrıştırıyor ve zaman baskısında net, dürüst bir ara cevap veriyor.",follow:"Düşüş tek bir büyük kurumsal müşterinin sipariş vermemesinden kaynaklanıyorsa bunu nasıl fark edersin?"},{id:"iv-b004",role:"analist",cat:"Senaryo",q:"Pazarlama, son indirim kampanyasının satışları artırdığını söylüyor ve senden bunu “kanıtlamanı” istiyor. Nasıl yaklaşırsın?",weak:"Kampanya dönemindeki satışı önceki ayla karşılaştırırım. Artış varsa kampanya işe yaramıştır.",strong:"Kanıtlamak değil ölçmek isterim; sonucu baştan kabul etmem. Önce karşılaştırma tabanını konuşurum: önceki ay mevsimsellik yüzünden yanıltıcı olabilir, geçen yılın aynı dönemi ya da kampanyaya girmeyen kategoriler daha iyi bir kontrol grubudur. Sonra yalnızca ciroya değil kâra bakarım: `[İndirim Tutarı]`, `[Kâr Marjı %]` ve `[İndirimli Satış Payı %]` kampanya döneminde nasıl değişti? Ciro artıp brüt kâr düştüyse kampanya ciroyu satın almış olabilir. Kampanya sonrası haftalara da bakarım; müşteriler alışverişi yalnızca öne çekmiş olabilir. Son olarak bulguyu bir aralıkla ve varsayımlarıyla sunarım: “Kontrol grubuna göre şu kadar ek satış, marj etkisi şu.”",why:"Doğrulama yanlılığına direniyor, uygun kontrol grubu seçiyor, kârlılığı ve talebin öne çekilmesini hesaba katıyor.",follow:"Kampanyaya katılan müşterilerle katılmayanlar baştan farklıysa (ör. Premium segment) karşılaştırmayı nasıl adil yaparsın?"},{id:"iv-b005",role:"analist",cat:"Senaryo",q:"Bir kullanıcı “Bana bütün sütunları içeren büyük bir tablo yap, Excel’e aktarıp kendim çalışacağım” diyor. Ne cevap verirsin?",weak:"Tabloyu yapar ve dışa aktarmayı açarım. Kullanıcı ne isterse onu vermek gerekir.",strong:"Önce Excel’de ne yaptığını sorarım; çoğu zaman bir özet tablo (pivot) kurup iki üç soruya cevap arıyordur. O soruları raporda karşılayabiliyorsam bunu öneririm. Gerçekten satır düzeyinde veriye ihtiyacı varsa en iyi yol, paylaşılan anlam modeline Excel’den bağlanmasıdır (“Excel’de analiz et”): veri tek kaynakta kalır, yenilenir ve RLS uygulanır. Satır listesi gerekiyorsa ve çıktı yazdırılacak ya da düzenli gönderilecekse sayfalandırılmış rapor daha uygundur. Dışa aktarma her zaman kapatılmamalı ama modelde gizli tutulan alanların ve hassas verinin nereye gittiğini bilmek gerekir. Kopyalanan Excel dosyaları zamanla “ikinci doğruluk kaynağı” olur; bunu kullanıcıya da açıkça anlatırım.",why:"İhtiyacın arkasındaki soruyu arıyor, üç alternatifi doğru durumlara eşliyor ve veri dağılmasının riskini dile getiriyor.",follow:"Kullanıcı ısrar ederse ve dışa aktarma kiracı ayarlarında kapalıysa ne önerirsin?"},{id:"iv-b006",role:"analist",cat:"DAX",q:"Kategori kırılımlı bir tabloda `[Hedef]` her satırda aynı (toplam) değeri gösteriyor, `[Net Satış]` ise doğru. Sebep ne olabilir?",weak:"Hedef ölçüsü yanlış yazılmıştır, CALCULATE eklemek gerekir.",strong:"Ölçü büyük ihtimalle doğrudur; sorun hangi sütunla kırılım yapıldığıdır. Bu modelde `Hedefler` tablosu `Kategoriler`e bağlı, `Urunler`e değil. Tabloya `Urunler[Kategori]` konduysa bu filtre `Satislar`a ulaşır ama `Hedefler`e hiçbir ilişki yolu yoktur; hedef her satırda filtresiz, yani toplam hâlde hesaplanır. Çözüm kırılımı `Kategoriler[Kategori]` ile yapmaktır; bu sütun hem `Urunler` üzerinden satışları hem doğrudan hedefleri filtreler. Kalıcı önlem olarak `Urunler[Kategori]`yi rapor görünümünde gizlerim ki kimse yanlış sütunu seçmesin. Teşhis için tek bir kategori seçip iki ölçünün değişip değişmediğine bakmak yeterlidir.",why:"Sorunu ölçüde değil filtre yolunda arıyor, modeldeki somut ilişkiyle açıklıyor ve tekrarını önleyecek bir model hijyeni adımı ekliyor.",follow:"`Hedefler` tablosunda ürün düzeyi hiç yoksa, ürün kırılımında hedef satırının ne göstermesini istersin?"},{id:"iv-b007",role:"analist",cat:"DAX",q:"Dilimleyicide seçilen kanala göre değişen bir başlık yazdın, ama iki kanal seçilince başlık boş kalıyor. Neden ve nasıl düzeltirsin?",weak:"`SELECTEDVALUE` çoklu seçimi desteklemiyor, dilimleyiciyi tek seçimli yaparım.",strong:'`SELECTEDVALUE(Satislar[Kanal])` sütunda tam bir değer görünüyorsa onu, birden çok ya da hiç değer yoksa BLANK ya da verdiğim ikinci argümanı döndürür; iki kanal seçilince BLANK geldiği için başlık boş kalır. Çoklu seçimi göstermek istersem değerleri birleştiririm: `CONCATENATEX(VALUES(Satislar[Kanal]), Satislar[Kanal], ", ")`. Hiç filtre yokken “Tüm kanallar” yazmak için `ISFILTERED(Satislar[Kanal])` ile ayırırım. Çok sayıda değer seçilebiliyorsa (ör. 40 ürün) hepsini yazmak yerine `COUNTROWS(VALUES(...))` ile “12 ürün seçili” gibi bir özet gösteririm. Modeldeki `[Dinamik Başlık]` ölçüsü bu kalıpların bir arada kullanımına iyi bir örnektir.',why:"SELECTEDVALUE davranışını doğru açıklıyor, seçim sayısına göre üç durumu ayrı ele alıyor ve başlığın okunabilirliğini de düşünüyor.",follow:"Seçim başka bir görselden çapraz filtreyle geliyorsa `ISFILTERED` yerine hangi fonksiyonu kullanırdın?"},{id:"iv-b008",role:"analist",cat:"DAX",q:"Matristeki `[Müşteri Sayısı]` satırlarının toplamı, toplam satırındaki değerden büyük çıkıyor. Kullanıcı bunun bir hata olduğunu düşünüyor. Ne dersin?",weak:"Bu bir Power BI hatası olabilir. Toplamı kapatırsam sorun kalmaz.",strong:"Bu hata değil, tekil sayımın doğası. `[Müşteri Sayısı]` `DISTINCTCOUNT` kullanır; aynı müşteri hem Elektronik’ten hem Kitap’tan aldıysa iki kategori satırında da sayılır, ama şirket toplamında bir kez sayılır. Yani satırlar toplanabilir değildir. Kullanıcıya bunu kendi verisiyle gösteririm: iki kategoriden de alışveriş yapan müşteri sayısını ayrıca hesaplar, farkın tam olarak bu olduğunu gösteririm. Raporda da toplam satırının adını ya da bilgi ipucunu “tekil müşteri” olarak netleştiririm. Toplamı kapatmak yanıltıcıdır; çünkü asıl soru çoğu zaman “toplam kaç farklı müşterimiz var” sorusudur ve doğru cevap toplam satırındadır.",why:"Toplanamayan ölçü kavramını adlandırıyor, kullanıcıyı ikna edecek somut bir kanıt öneriyor ve toplamı gizlemenin yanlış olduğunu açıklıyor.",follow:"Kullanıcı yine de satırların toplamını görmek isterse bunu hangi kalıpla ve hangi adla verirsin?"},{id:"iv-b009",role:"analist",cat:"DAX",q:"Ürün sıralama ölçün dilimleyicide bir kategori seçildiğinde 1’den başlamıyor; ilk ürün 7. sırada görünüyor. Neden?",weak:"RANKX bazen yanlış sıralar. Sıralamayı görselin kendi sıralamasıyla yaparım.",strong:"Ölçü büyük ihtimalle `RANKX(ALL(Urunler[Urun]), [Net Satış])` gibi yazılmıştır; `ALL` dilimleyicinin kategori filtresini de kaldırır ve ürün tüm şirketteki 40 ürün arasında sıralanır. Bu modeldeki `[Ürün Sırası]` tam olarak böyledir ve bilerek “şirket geneli sıra” verir. Kullanıcı seçili ürünler içindeki sırayı istiyorsa `ALLSELECTED(Urunler[Urun])` kullanırım; `[Seçime Göre Sıra]` bunu yapar ve satırda yalnızca `ISINSCOPE` doğruysa sonuç döndürür. Hangisinin doğru olduğu iş sorusuna bağlıdır; ikisini aynı adla tutmam. Eşitlik durumunda sıra atlanmasını istemiyorsam `DENSE` argümanını da eklerim.",why:"ALL ve ALLSELECTED farkını filtre bağlamı üzerinden açıklıyor, modeldeki iki ölçüyü doğru eşliyor ve iki ihtiyacın ayrı adlarla tutulması gerektiğini söylüyor.",follow:"Satışı olmayan ürünler sıralamada en sonda aynı sırayı alıyor. Onları listeden nasıl çıkarırsın?"},{id:"iv-b010",role:"analist",cat:"DAX",q:"Yazdığın bir filtre ölçüsü hiçbir koşulda değişmiyor ve hep BLANK dönüyor. Nasıl hata ayıklarsın?",weak:"Ölçüyü silip baştan yazarım. Genelde ikinci seferde çalışır.",strong:"Adım adım daraltırım. Önce filtredeki değerin veride gerçekten var olup olmadığına bakarım; DAX sorgu görünümünde `EVALUATE VALUES(Satislar[Durum])` çalıştırınca değerlerin “İptal”, “İade”, “Kargoda”, “Teslim Edildi” olduğunu görürüm. “Iptal” (noktasız ı) ya da sonda boşluk gibi küçük bir fark sonucu BLANK yapar. Sonra ölçüyü parçalarına bölerim: koşulsuz `COUNTROWS(Satislar)` çalışıyor mu, koşul tek başına kaç satır döndürüyor? `VAR` ile ara sonuçları tek tek `RETURN` ederek hangi adımın boşaldığını bulurum. İlişki yönünü ve filtrelenen sütunun doğru tabloda olup olmadığını da kontrol ederim. Bulduğum sebebi ölçü açıklamasına ya da ekip notlarına yazarım.",why:"Tahmin yerine veriyi sorguluyor, ölçüyü parçalara bölerek hata yerini daraltıyor ve sık görülen yazım ve ilişki sorunlarını sayıyor.",follow:"Kaynakta değerler zaman zaman farklı yazılıyorsa (büyük/küçük harf, boşluk) bunu kalıcı olarak nerede çözersin?"},{id:"iv-b011",role:"analist",cat:"DAX",q:"Kategori ve ürün hiyerarşisi olan bir matriste, her ürünün kendi kategorisi içindeki payını göstermek istiyorsun. Nasıl yazarsın?",weak:"`DIVIDE([Net Satış], CALCULATE([Net Satış], ALL(Urunler)))` yazarım, pay olarak gösterir.",strong:"`ALL(Urunler)` ürün tablosundaki tüm filtreleri, kategori dahil, kaldırır; sonuç şirket içindeki pay olur. Kategori içindeki pay için yalnızca ürün sütunundaki filtreyi kaldırırım: `DIVIDE([Net Satış], CALCULATE([Net Satış], REMOVEFILTERS(Urunler[Urun])))`. Ürün satırında kategori filtresi korunur, payda kategorinin toplamı olur; kategori satırında da sonuç %100 çıkar. Kategori satırında %100 yerine kategorinin şirket içindeki payını göstermek istersem `ISINSCOPE(Urunler[Urun])` ile iki durumu ayırır, kategori düzeyinde `[Kategori Payı %]` döndürürüm. Dilimleyicide bazı ürünler seçiliyken payın seçime göre olmasını istersem `ALLSELECTED(Urunler[Urun])` kullanırım.",why:"Hangi filtrenin kaldırılması gerektiğini sütun düzeyinde seçiyor, hiyerarşinin her seviyesinde sonucun ne olacağını söylüyor ve seçime göre payı ayrı bir ihtiyaç olarak ele alıyor.",follow:"Hiyerarşide kategori yerine `Kategoriler[Kategori]` kullanılıyorsa `REMOVEFILTERS(Urunler[Urun])` yine yeterli olur mu?"},{id:"iv-b012",role:"analist",cat:"DAX",q:"“Aktif müşteri” sayısını göstermen isteniyor. Tanımı nasıl netleştirir, ölçüyü nasıl yazarsın?",weak:"`DISTINCTCOUNT(Satislar[MusteriNo])` aktif müşteri sayısını verir.",strong:"Önce tanımı yazılı hâle getiririm: “Dönemin son gününden geriye 90 gün içinde iptal olmayan en az bir siparişi olan müşteri” gibi. Seçilen dönemde alışveriş yapan müşteri (`[Müşteri Sayısı]`) bundan farklıdır; ay seçiliyse 90 günü değil yalnızca o ayı sayar. Ölçü: `CALCULATE([Müşteri Sayısı], DATESINPERIOD(Tarih[Tarih], MAX(Tarih[Tarih]), -90, DAY))`. `[Müşteri Sayısı]` iptalleri zaten dışarıda bıraktığı için koşulu tekrar yazmam. Toplam satırında “son 90 gün” verinin son tarihine göre hesaplanır, bunu da not ederim. Eşik (90 gün) iş tarafının kararıdır; satın alma sıklığı düşük kategorilerde 180 gün daha anlamlı olabilir, bunu ilgili ekiple konuşurum.",why:"Ölçüyü yazmadan önce tanımı netleştiriyor, dönem müşterisi ile aktif müşteri farkını gösteriyor ve eşiğin bir iş kararı olduğunu vurguluyor.",follow:"Bu ölçüyü bir çizgi grafikte ay ay gösterirken verinin son ayı yarımsa grafikte ne olur?"},{id:"iv-b013",role:"analist",cat:"DAX",q:"3 aylık hareketli ortalama grafiğinde verinin ilk iki ayı olağandışı düşük görünüyor. Sebebi ve çözümü ne?",weak:"İlk aylarda satış azdır, bu normal. Grafiği üçüncü aydan başlatırım.",strong:"Bu modeldeki `[3 Ay Hareketli Ort.]` son üç ayın satışını her zaman 3’e böler. Satışlar 2022 Haziran’da başladığı için Haziran’da bir, Temmuz’da iki aylık satış 3’e bölünür; ortalama yapay olarak düşük çıkar. Çözüm, paydayı verisi olan ay sayısı yapmaktır: `VAR Aylar = CALCULATETABLE(VALUES(Tarih[YilAy]), DATESINPERIOD(Tarih[Tarih], MAX(Tarih[Tarih]), -3, MONTH)) RETURN AVERAGEX(Aylar, [Net Satış])`. `AVERAGEX` satışı BLANK olan ayları saymaz. Yine de iki aylık ortalamayı “3 aylık” diye sunmak yanıltıcıdır; bu yüzden ay sayısı 3’ten azsa BLANK döndürmeyi de bir seçenek olarak kullanıcıya sunarım. Grafiği elle üçüncü aydan başlatmak, filtre değişince bozulacak bir yamadır.",why:"Sorunun kaynağını ölçü tanımında buluyor, BLANK’i atlayan doğru kalıbı yazıyor ve yanıltıcı ortalamayı göstermeme seçeneğini de değerlendiriyor.",follow:"Bir ayda gerçekten hiç satış olmadıysa (0) ve bu ayın ortalamaya girmesi gerekiyorsa ölçüyü nasıl değiştirirsin?"},{id:"iv-b014",role:"analist",cat:"Model",q:"Sana tek bir düz Excel tablosu geldi: her satırda sipariş, müşteri adı, şehir, ürün, kategori ve tutar var. Bunu olduğu gibi kullanır mısın?",weak:"Evet, tek tablo daha basit. İlişki kurmakla uğraşmam.",strong:"Küçük, tek seferlik bir analiz için kullanabilirim; ama uzun ömürlü bir rapor için yıldız şemaya ayırırım. Power Query’de tablodan müşteri, ürün ve tarih boyutlarını tekil satırlarla ayırır, olgu tablosunda yalnızca anahtarları ve sayısal sütunları bırakırım; bu uygulamanın modelindeki `Satislar`, `Musteriler`, `Urunler`, `Tarih` ayrımı budur. Kazancım şunlar olur: tekrar eden metinler bir kez saklandığı için model küçülür, zaman zekâsı için düzgün bir tarih tablosu kullanabilirim, yeni bir olgu (ör. hedefler) geldiğinde aynı boyutlara bağlayabilirim ve ölçüler daha öngörülebilir çalışır. Düz tabloda “Hedef” gibi farklı ayrıntı düzeyindeki bir veriyi eklemek neredeyse imkânsızdır.",why:"Bağlama göre karar veriyor, dönüşümün nasıl yapılacağını anlatıyor ve yıldız şemanın somut faydalarını gelecekteki ihtiyaçlarla bağlıyor.",follow:"Excel’de aynı müşterinin şehri iki farklı satırda farklı yazılmışsa müşteri boyutunu oluştururken ne yaparsın?"},{id:"iv-b015",role:"analist",cat:"Model",q:"Neden ayrı bir tarih tablosu kullanıyoruz? Satış tablosundaki tarih sütunu yetmez mi?",weak:"Power BI otomatik tarih hiyerarşisi oluşturuyor, ayrı tabloya gerek yok.",strong:"Satış tablosundaki tarihlerde boşluklar vardır: satış olmayan günler yoktur. Zaman zekâsı fonksiyonları (`SAMEPERIODLASTYEAR`, `DATESYTD`) kesintisiz bir tarih sütununa ihtiyaç duyar. Ayrı bir `Tarih` tablosu her günü bir kez içerir, “Tarih tablosu olarak işaretle” ile tanıtılır ve yıl, çeyrek, ay adı, hafta sonu gibi sütunları tek yerde tutar. En önemlisi, birden çok olgu tablosunu aynı tarih filtresiyle keser: bu modelde `Satislar`, `Hedefler`, `Giderler`, `Talepler` hepsi `Tarih`e bağlıdır, bu yüzden tek bir yıl dilimleyicisi hepsini birden filtreler. Otomatik tarih/saat seçeneği her tarih sütunu için gizli bir tablo üretir, modeli büyütür ve tablolar arasında ortak filtre sağlamaz; bu yüzden onu kapatırım.",why:"Teknik gerekçeyi (kesintisiz tarih), modelleme gerekçesini (ortak boyut) ve otomatik tarihin maliyetini birlikte açıklıyor.",follow:"Ay adlarının grafikte alfabetik sıralanmasını nasıl önlersin?"},{id:"iv-b016",role:"analist",cat:"Model",q:"Müşteri hizmetleri talepleri (`Talepler`) ile satışları (`Satislar`) aynı raporda göstermek istiyorsun. İkisini nasıl ilişkilendirirsin?",weak:"Talepler ile Satislar arasında MusteriNo üzerinden doğrudan ilişki kurarım.",strong:"İki olgu tablosunu doğrudan birbirine bağlamam; aynı müşteri birden çok sipariş ve birden çok talebe sahip olduğu için bu çoka çok bir ilişki olur ve filtreler öngörülemez hâle gelir. Bunun yerine ikisini ortak boyutlara bağlarım: `Musteriler` ve `Tarih`. Bu modelde böyle kurulu; bir segment ya da yıl filtresi iki tabloyu da aynı anda keser. Böylece `[Talep Sayısı]` ile `[Sipariş Sayısı]` aynı görselde yan yana durabilir ve `DIVIDE([Talep Sayısı], [Sipariş Sayısı])` gibi oranlar müşteri ya da dönem kırılımında anlamlı olur. Ürün ya da kanal gibi yalnızca bir tabloda olan boyutlar diğerini filtrelemez; bunu raporda kullanıcıya belli ederim, gerekirse o görsellerde talep ölçüsünü göstermem.",why:"İki olguyu ortak boyutlarla bağlama ilkesini uyguluyor, modeldeki somut yapıyla anlatıyor ve paylaşılmayan boyutların yan etkisini fark ediyor.",follow:"Ürün kırılımında `[Talep Sayısı]` her satırda aynı görünüyor. Kullanıcıya bunu nasıl açıklarsın ya da nasıl engellersin?"},{id:"iv-b017",role:"analist",cat:"Model",q:"Bir iş arkadaşın “filtreler her iki yönde de geçsin” diye tüm ilişkileri çift yönlü yapmış. Bunun nesi sorunlu olabilir?",weak:"Çift yönlü daha esnektir, sorun olmaz. Sadece biraz yavaşlatabilir.",strong:"Çift yönlü ilişki boyuttan olguya giden filtrenin olgudan boyuta da geri dönmesine izin verir. Birden çok olgu aynı boyutlara bağlıysa bu, belirsiz yollar oluşturur: örneğin `Satislar` üzerinden `Musteriler`e dönen bir filtre `Talepler`e de ulaşır ve kullanıcı bunu beklemez. Model bazen belirsizlik yüzünden bir ilişkiyi devre dışı bırakmak zorunda kalır. Performans da etkilenir, çünkü motor her sorguda daha çok tabloyu filtrelemek zorundadır. Ayrıca RLS ile birleştiğinde güvenlik filtresinin nereye yayılacağını anlamak zorlaşır. Benim kuralım ilişkileri tek yönlü tutmak, gerçekten gerekli olan bir hesapta `CROSSFILTER(..., Both)` ile ölçü içinde geçici olarak açmaktır; böylece etki yalnızca o ölçüyle sınırlı kalır.",why:"Belirsiz yol, beklenmedik filtre, performans ve RLS etkilerini sayıyor ve ölçü düzeyinde kontrollü bir alternatif sunuyor.",follow:"Bir dilimleyicide yalnızca satışı olan ürünlerin listelenmesini istiyorsan çift yönlü ilişki dışında ne yapabilirsin?"},{id:"iv-b018",role:"analist",cat:"Power Query",q:"Her ay bir klasöre o ayın satış dosyası (Excel) bırakılıyor. Raporun yeni dosyaları otomatik alması için ne yaparsın?",weak:"Her ay yeni dosyayı ayrı bir sorgu olarak ekler, sonra ekleme (append) yaparım.",strong:"Klasör bağlayıcısını kullanırım: Power Query klasördeki dosyaları listeler ve “Birleştir” ile her dosyaya aynı dönüşümü uygulayan bir örnek dosya fonksiyonu üretir. Yeni dosya klasöre düştüğünde ek bir işlem gerekmez. Dikkat ettiğim noktalar: dosya adından ya da dosya içindeki bir sütundan ay bilgisini alıp kaynak sütun olarak tutarım ki hangi satırın hangi dosyadan geldiği bilinsin; geçici dosyaları (`~$` ile başlayan) ve yanlış uzantıları filtrelerim; sütun adlarının aydan aya değişebileceğini düşünerek örnek dosyada sütunları adla seçer, eksik olanları boş geçecek şekilde ayarlarım. Klasör bir SharePoint kitaplığındaysa yenilemenin ağ geçidi gerektirmemesi için SharePoint klasör bağlayıcısını tercih ederim.",why:"Doğru bağlayıcıyı ve mekanizmayı biliyor, gerçek hayatta bozulmaya yol açan dosya ve şema sorunlarını önceden düşünüyor.",follow:"Klasörde üç yıllık dosya birikti ve yenileme yavaşladı. Ne yaparsın?"},{id:"iv-b019",role:"analist",cat:"Power Query",q:"Kaynak sistemde bir sütunun adı değişti ve rapor yenilemesi “sütun bulunamadı” hatasıyla durdu. Nasıl düzeltir, tekrarını nasıl önlersin?",weak:"Hata veren adımı silerim, rapor yeniden yenilenir.",strong:"Önce hangi adımın hata verdiğini bulurum; genellikle sütun adlarını sabit yazan “Değiştirilen Tür” ya da “Yeniden adlandırılan sütunlar” adımıdır. Adımı silmek türleri ve adları bozar, sonraki adımlar ve ölçüler de kırılır. Doğru düzeltme, eski adı yeni adla eşleyen bir yeniden adlandırmayı kaynağa en yakın adıma eklemek, modelde ise sütun adını aynı bırakmaktır; böylece ölçüler ve görseller etkilenmez. Tekrarını önlemek için kaynak ekibinden şema değişikliklerini önceden duyurmasını isterim, mümkünse veriyi bir görünüm (view) üzerinden alırım ki adlar sabit kalsın. `Table.SelectColumns` ile gereken sütunları açıkça seçmek ve kritik sütunlar için bir kontrol adımı eklemek de işe yarar.",why:"Kök nedeni buluyor, ölçüleri korumak için modeldeki adı sabit tutuyor ve kaynakla sözleşme kurarak sorunu kalıcı çözüyor.",follow:"Kaynakta bir sütun tamamen kaldırılırsa raporun hata vermek yerine boş değerle devam etmesini ister misin? Neden?"},{id:"iv-b020",role:"analist",cat:"Power Query",q:"Müşteri tablosunu satış tablosuna bağlamaya çalışınca Power BI ilişkiyi “çoka çok” olarak öneriyor. Ne anlarsın, ne yaparsın?",weak:"Çoka çok seçeneğini kabul ederim, Power BI zaten destekliyor.",strong:"Bu, müşteri tablosunda anahtarın (`MusteriNo`) tekil olmadığı anlamına gelir; boyut tablosunda her müşteri bir kez olmalıdır. Önce kopyaların neden oluştuğunu anlarım: Power Query’de `MusteriNo`ya göre gruplayıp sayısı 1’den büyük olanları listelerim. Sebep çoğunlukla şunlardan biridir: aynı müşterinin adres değişikliği yüzünden iki kaydı, birleştirilmiş iki kaynak, boşluklu ya da farklı biçimde yazılmış anahtarlar, boş anahtarlı satırlar. Sebebe göre ya en güncel kaydı seçer, ya anahtarı temizler, ya da kaynağa düzeltme talebi açarım. Körlemesine “Yinelenenleri kaldır” yapmak hangi kaydın kaldığını rastgele bırakır ve müşterinin segmenti ya da şehri yanlış çıkabilir. Çoka çok ilişkiyi kabul etmek ise sorunu gizler ve toplamları bozar.",why:"Uyarının ne anlama geldiğini doğru okuyor, kopyaların kaynağını araştırıyor ve kolay ama yanlış iki çözümün riskini açıklıyor.",follow:"Hangi kaydın “güncel” olduğunu belirleyen bir tarih sütunu yoksa ne yaparsın?"},{id:"iv-b021",role:"analist",cat:"Power Query",q:"Power Query’de bir sorguyu “Başvuru” (Reference) ile mi “Çoğalt” (Duplicate) ile mi kopyalarsın? Ara sorguları nasıl düzenlersin?",weak:"İkisi de aynı şeyi yapar, ben genelde çoğaltırım.",strong:"“Çoğalt”, sorgunun tüm adımlarını kopyalar ve bağımsız yeni bir sorgu oluşturur; ilk sorguda yapılan düzeltme kopyaya geçmez. “Başvuru” ise ilk sorgunun sonucunu kaynak olarak alan yeni bir sorgu açar; temizlik bir kez yapılır, ondan türeyen sorgular otomatik güncellenir. Ben ortak temizliği bir ara (staging) sorguda yapar, ondan başvuruyla boyut ve olgu sorgularını türetirim; örneğin ham satış dosyasından hem `Satislar` hem `Urunler` çıkar. Ara sorgunun “Yüklemeyi etkinleştir” seçeneğini kapatırım ki modele gereksiz tablo girmesin. Dikkat: başvurulan sorgu her türeyen sorgu için yeniden değerlendirilebilir; kaynak yavaşsa bu yenileme süresini uzatır, o durumda dönüşümü kaynağa ya da bir veri akışına (dataflow) taşımayı düşünürüm.",why:"İki işlemin farkını bakım açısından açıklıyor, ara sorgu düzenini somut örnekle anlatıyor ve yeniden değerlendirme maliyetini de biliyor.",follow:"Sorgu bağımlılıkları görünümünde bir döngü ya da çok uzun bir zincir görürsen ne düşünürsün?"},{id:"iv-b022",role:"analist",cat:"Rapor ve görselleştirme",q:"Aylık net satış ile hedefi aynı görselde göstermen isteniyor. Hangi görseli seçer, nasıl kurarsın?",weak:"Kümelenmiş sütun grafiği kullanırım; her ay için iki sütun olur.",strong:"Zaman ekseninde gerçekleşme ile hedefi karşılaştırmak için sütun ve çizgi birleşik grafiği iyi bir seçenektir: aylık `[Net Satış]` sütun, `[Hedef]` çizgi olur; göz hemen çizginin altında kalan sütunlara gider. On iki ayda yirmi dört sütun kalabalık görünür, bu yüzden kümelenmiş sütunu tercih etmem. Sapmayı vurgulamak istiyorsam ikinci bir küçük görselde `[Hedef Gerçekleşme %]` ya da hedef farkını gösteririm. Ekseni `Tarih[YilAy]` ile kurarım ki yıl dilimleyicisi olmadan da aylar karışmasın. Renk olarak gerçekleşmeyi nötr, hedefi ince ve koyu bir çizgiyle gösteririm; kırmızı-yeşil yerine konum ve etiketle anlam veririm. Başlıkta da soruyu yazarım: “2024’te hangi aylarda hedefin altında kaldık?”",why:"Görsel seçimini karşılaştırmanın türüne göre gerekçelendiriyor, kalabalığı ve rengi düşünüyor, başlığı bir soruya dönüştürüyor.",follow:"Hedef yalnızca çeyrek düzeyinde verilseydi aylık grafikte nasıl gösterirdin?"},{id:"iv-b023",role:"analist",cat:"Rapor ve görselleştirme",q:"Rapor sayfası çok kalabalık ama kullanıcılar ayrıntı istiyor. Araç ipucu sayfaları (report page tooltips) burada nasıl yardımcı olur?",weak:"Araç ipuçlarına daha çok alan eklerim, ayrıntı orada görünür.",strong:"Araç ipucu sayfası, bir veri noktasının üzerine gelindiğinde açılan küçük bir rapor sayfasıdır ve o noktanın filtresini otomatik alır. Ana sayfada yalnızca karar için gereken özet görsel kalır; örneğin kategori çubuk grafiği. Kullanıcı Elektronik çubuğunun üzerine gelince küçük sayfada o kategorinin aylık trendi, `[Kâr Marjı %]` ve en çok satan üç ürünü görünür. Kurarken sayfanın boyutunu “Araç ipucu” yapar, sayfayı gizler ve hangi alanlarda tetikleneceğini belirlerim. Dikkat ettiğim noktalar: ipucunu iki üç görselle sınırlı tutarım, çünkü fareyle her geçişte sorgu çalışır; mobil ve dokunmatik ekranda üzerine gelme olmadığı için kritik bilgiyi yalnızca ipucuna koymam. Daha derin analiz gerekiyorsa detaylandırma (drillthrough) sayfası daha doğru araçtır.",why:"Özelliğin mekanizmasını ve kurulumunu biliyor, somut bir örnek veriyor ve performans ile mobil sınırlamalarını hesaba katıyor.",follow:"Araç ipucu sayfasında gösterdiğin bir ölçünün ana sayfadaki dilimleyiciden etkilenmesini istemiyorsan ne yaparsın?"},{id:"iv-b024",role:"analist",cat:"Rapor ve görselleştirme",q:"Aynı satış verisini hem genel müdür hem bölge operasyon ekipleri kullanacak. Tek rapor mu yaparsın, ayrı raporlar mı?",weak:"Tek rapor yaparım, herkes ihtiyacı olan sayfaya bakar. Bakımı kolay olur.",strong:"Model tek olmalı, rapor deneyimi kitleye göre ayrılmalı. Paylaşılan bir anlam modeli üzerinde iki ince rapor kurarım: genel müdür için az sayıda karşılaştırmalı KPI ve trend içeren bir özet; operasyon için filtrelenebilir tablolar, detaylandırma sayfaları ve ürün düzeyinde listeler. İkisi aynı ölçüleri kullandığı için rakamlar tutarlı kalır. Dağıtımı bir Power BI uygulamasıyla yapar, uygulamanın kitle (audience) özelliğiyle her gruba yalnızca kendi raporlarını gösteririm. Bölge ekiplerinin yalnızca kendi bölgesini görmesi gerekiyorsa bunu sayfa filtresiyle değil RLS ile sağlarım. Tek bir dev rapor genellikle iki kitleyi de yarım memnun eder; ayrı modeller ise rakamların zamanla ayrışmasına yol açar.",why:"Model ile rapor katmanını ayırıyor, dağıtım ve güvenliği doğru araçlarla çözüyor ve iki uç seçeneğin riskini açıklıyor.",follow:"Genel müdür telefonundan bakıyorsa özet raporda neyi değiştirirsin?"},{id:"iv-b025",role:"analist",cat:"Rapor ve görselleştirme",q:"Kullanıcılar aynı grafikte bazen satışı, bazen kârı görmek istiyor. Yer işaretleri (bookmarks) mi, alan parametreleri (field parameters) mi kullanırsın?",weak:"Yer işaretleri her şeyi yapar. İki grafik koyar, düğmeyle birini gizlerim.",strong:"Yalnızca gösterilen ölçü değişiyorsa alan parametresi daha temizdir: tek bir grafik, tek bir dilimleyici, `[Net Satış]` ve `[Brüt Kâr]` arasında seçim; yeni bir ölçü eklemek bir satır eklemek kadar kolaydır ve ekseni de (kategori ya da kanal) aynı yöntemle değiştirebilirim. Yer işaretleri ise sayfanın durumunu kaydeder: görünür görseller, filtreler, sıralama. Görselin türü değişecekse (tablo ile grafik arasında geçiş) ya da bir panel açılıp kapanacaksa yer işareti doğru araçtır. Yer işaretlerinin bakımı zordur; yeni bir görsel eklediğinde her yer işaretini güncellemen gerekir ve kullanıcı filtresini istemeden sıfırlayabilir. Modelde ölçü seçimi için kullanılan `OlcuSecimi` tablosu ve `[Seçili Ölçü]` ise üçüncü bir yoldur; biçimi ölçüye göre değiştirmek gerektiğinde işe yarar.",why:"İki aracın ne sakladığını doğru ayırıyor, bakım maliyetini hesaba katıyor ve modeldeki üçüncü yöntemi de yerine koyuyor.",follow:"Alan parametresiyle seçilen ölçü yüzde olduğunda eksen biçimi neden bozulabilir, nasıl çözersin?"},{id:"iv-b026",role:"analist",cat:"Rapor ve görselleştirme",q:"Bir ekip arkadaşın yirmi görselin sığdırıldığı bir rapor sayfası hazırlamış ve senden geri bildirim istiyor. Nasıl değerlendirirsin?",weak:"Görsellerin çok olduğunu, sayfanın karmaşık göründüğünü söylerim.",strong:"Önce sayfanın hangi soruya cevap vermesi gerektiğini sorarım; geri bildirimi o amaca göre veririm, kişisel zevke göre değil. Sonra somut bir sırayla bakarım: bir yönetici sayfayı beş saniyede okuyunca ana mesajı görüyor mu; en önemli KPI sol üstte ve karşılaştırmalı mı (hedefe ya da geçen yıla göre); aynı bilgiyi tekrar eden görseller var mı; renkler anlam taşıyor mu yoksa süs mü; eksenler ve birimler tutarlı mı. Performans Analizi ile sayfanın açılış süresini de ölçerim; yirmi görsel çoğunlukla yavaşlık demektir. Önerilerimi öncelik sırasıyla iki üç maddeye indiririm ve her birine bir alternatif eklerim (ör. altı kart yerine tek çok satırlı kart, ayrıntı tablosunu detaylandırma sayfasına taşımak). İyi yapılan kısımları da açıkça söylerim.",why:"Geri bildirimi amaca bağlıyor, kontrol edilebilir ölçütler kullanıyor, performansı ölçüyor ve yapıcı, önceliklendirilmiş öneriler veriyor.",follow:"Ekip arkadaşın tüm önerilerine “ama kullanıcı böyle istedi” diye karşı çıkarsa ne yaparsın?"},{id:"iv-b027",role:"analist",cat:"Rapor ve görselleştirme",q:"Tabloda hedefin altındaki kategorilerin hücre rengini bir kural listesi yerine ölçüyle belirlemek istiyorsun. Nasıl yaparsın, neden?",weak:"Koşullu biçimlendirmede kurallar yazarım: 0,9’un altı kırmızı, üstü yeşil.",strong:'Koşullu biçimlendirmede “Alan değeri” (field value) seçeneğini kullanırım: renk kodunu döndüren bir ölçü yazarım, ör. `VAR O = [Hedef Gerçekleşme %] RETURN SWITCH(TRUE(), ISBLANK(O), BLANK(), O >= 1, "#2E7D32", O >= 0.95, "#F9A825", "#C62828")`. Avantajı, eşiklerin tek bir yerde durması ve her görselde aynı kuralın kullanılmasıdır; eşik değişince bir ölçüyü güncellerim, on görseli tek tek değil. Ölçü, hedefi olmayan satırlarda BLANK döndürür ve hücre renksiz kalır. Renk körlüğünü düşünerek yalnızca renge güvenmem; yanına bir simge ya da `[Hedef Durumu]` gibi bir metin etiketi eklerim. Renk kodlarını rapor temasındaki tonlarla uyumlu seçerim.',why:"Ölçüyle biçimlendirmenin bakım avantajını açıklıyor, BLANK durumunu ele alıyor ve erişilebilirliği de unutmuyor.",follow:"Eşikleri iş birimi sık sık değiştiriyorsa bunları ölçüye sabit yazmak yerine nerede tutarsın?"},{id:"iv-b028",role:"analist",cat:"SQL",q:"Satış tablosunu müşteri tablosuyla LEFT JOIN ile birleştirdin ve satır sayısı arttı. Bu nasıl olabilir?",weak:"LEFT JOIN sol tablonun tüm satırlarını getirir, sayının artması normaldir.",strong:"LEFT JOIN sol tablodaki her satırı korur ama sağ tarafta eşleşen birden çok satır varsa o satırı çoğaltır. Sayı arttıysa müşteri tablosunda aynı anahtar birden çok kez geçiyordur. Kontrol için `SELECT MusteriNo, COUNT(*) FROM Musteriler GROUP BY MusteriNo HAVING COUNT(*) > 1` çalıştırırım. Bu, satış tutarının toplamını da şişirir; raporda ciro olduğundan yüksek görünür. Çözüm kopyaların sebebine bağlıdır: geçmiş kayıtlar tutuluyorsa güncel olanı seçerim (ör. `ROW_NUMBER()` ile), hatalı kopyaysa kaynakta düzeltilmesini isterim. Birleştirme öncesi ve sonrası satır sayısını ve tutar toplamını karşılaştırmak benim standart kontrolümdür. Power Query’deki birleştirme (merge) de aynı şekilde davranır.",why:"JOIN mekanizmasını doğru açıklıyor, teşhis sorgusunu yazıyor, etkinin ciroya yansımasını gösteriyor ve kalıcı bir kontrol alışkanlığı tarif ediyor.",follow:"Bu çoğalma model içinde, ilişkiyle bağlanmış iki tabloda da yaşanır mı? Neden?"},{id:"iv-b029",role:"analist",cat:"SQL",q:"Her müşterinin ilk siparişini SQL’de nasıl bulursun? Aynı soruyu DAX’ta nasıl cevaplarsın?",weak:"SQL’de `MIN(Tarih)` ile GROUP BY yaparım. DAX’ta da MIN kullanırım.",strong:"Yalnızca ilk tarih gerekiyorsa `SELECT MusteriNo, MIN(Tarih) FROM Satislar WHERE Durum <> 'İptal' GROUP BY MusteriNo` yeterlidir. İlk siparişin tamamı (tutarı, kanalı) gerekiyorsa pencere fonksiyonu kullanırım: `ROW_NUMBER() OVER (PARTITION BY MusteriNo ORDER BY Tarih, SiparisNo)` ile numaralandırıp 1 olan satırları alırım; eşit tarihlerde sıralamayı belirlemek için ikinci bir sıralama sütunu şarttır. DAX’ta tarih bağlamından bağımsız ilk tarihi `CALCULATE(MIN(Satislar[Tarih]), ALL(Tarih), Satislar[Durum] <> \"İptal\")` verir; müşteri satırında hesaplanır. Bu bilgi sık kullanılıyorsa (kohort analizi gibi) müşteri tablosunda bir sütun olarak saklamak daha verimlidir; bu modeldeki `Musteriler[IlkSiparis]` böyle bir sütundur.",why:"İki farklı ihtiyacı (tarih ya da tüm satır) ayırıyor, eşitlik durumunu düşünüyor ve DAX karşılığını tarih filtresini kaldırarak doğru yazıyor.",follow:"İlk siparişi iptal edilmiş bir müşterinin ilk siparişi hangisidir? Tanımı kim belirler?"},{id:"iv-b030",role:"analist",cat:"SQL",q:"Bir dönüşümü kaynak veritabanında bir görünüm (view) olarak mı yazarsın, Power Query’de mi yaparsın?",weak:"Power Query’de yaparım, veritabanı ekibine iş açmak zaman alır.",strong:"Dönüşümü kullanacak birden çok rapor ya da araç varsa ve mantık iş kuralıysa (ör. iptal edilmiş siparişlerin nasıl işaretleneceği) kaynağa, yani bir görünüme koymayı tercih ederim; kural tek yerde durur ve herkes aynı sonucu alır. Görünüm ayrıca sütun adlarını sabitler ve şema değişikliklerine karşı bir tampon olur. Power Query’yi rapora özgü, hafif dönüşümler için kullanırım. İkinci ölçütüm performanstır: Power Query adımları katlanabiliyorsa zaten SQL’e çevrilir; katlanmayan karmaşık adımlar ise veriyi belleğe çekip yavaşlatır, bunlar SQL’de daha hızlıdır. Bir görünümün sahibi ve değişiklik süreci olmalı; yoksa kimin neyi değiştirdiği belirsizleşir. Kısa vadede Power Query’de başlayıp kural kesinleşince kaynağa taşımak da makul bir yoldur.",why:"Yeniden kullanılabilirlik, sahiplik ve performans ölçütleriyle karar veriyor ve aşamalı bir yol da öneriyor.",follow:"Veritabanı ekibi görünüm açmayı reddederse aynı mantığı birden çok rapor arasında nasıl paylaşırsın?"},{id:"iv-b031",role:"analist",cat:"Kavram",q:"Hesaplanmış sütun ile ölçü arasındaki farkı kendi cümlelerinle anlat. Birer örnek ver.",weak:"Hesaplanmış sütun tabloya eklenir, ölçü görselde hesaplanır. İkisi de DAX ile yazılır.",strong:"Hesaplanmış sütun, yenileme sırasında her satır için bir kez hesaplanır ve tabloda saklanır; satır bağlamında çalışır, dilimleyiciye tepki vermez. Ölçü ise her görsel hücresinde, o anki filtre bağlamına göre sorgu anında hesaplanır ve saklanmaz. Örnek: ürünü fiyatına göre “Ucuz/Orta/Pahalı” diye etiketlemek bir sütundur, çünkü değer satıra aittir ve dilimleyicide ya da eksende kullanılacaktır. `[Kâr Marjı %]` ise bir ölçüdür; satırların marjını toplamak anlamsızdır, oran her bağlamda toplamlardan yeniden hesaplanmalıdır. Sütunlar bellekte yer kaplar, ölçüler kaplamaz. Kuralım: değeri gruplamak ya da filtrelemek için kullanacaksam sütun, toplamak ya da oranlamak için kullanacaksam ölçü.",why:"Hesaplama zamanı, bağlam ve depolama farklarını açıklıyor, iki doğru örnek veriyor ve pratik bir karar kuralıyla bitiriyor.",follow:"Bu etiketi Power Query’de mi, DAX hesaplanmış sütunuyla mı oluşturursun?"},{id:"iv-b032",role:"analist",cat:"Kavram",q:"Bir analizde yalnızca toplam rakama değil dağılıma da bakmak neden önemlidir? Bir örnek ver.",weak:"Dağılım daha ayrıntılı bilgi verir. Grafikle göstermek daha güzel olur.",strong:"Toplam ya da ortalama, farklı hikâyeleri aynı sayıda gizleyebilir. Örneğin müşteri başı satış artmış olabilir, ama bu artış birkaç büyük kurumsal müşteriden geliyor ve geri kalanında düşüş varsa strateji bambaşka olur. Bu yüzden ortalamanın yanında medyana, yüzdeliklere ve uç değerlere bakarım. Dağılımı görmek için müşterileri satış dilimlerine ayırırım; bu modelde `MusteriDilimleri` ve `[Dilimdeki Müşteri]` ölçüsü bunu yapar. Bir histogram ya da kutu grafiği ile en büyük on müşterinin toplam içindeki payı da hızlı bir kontrol sağlar. Yoğunlaşma yüksekse ortalamayı başlığa koymam; “müşterilerin yarısı şu tutarın altında” gibi bir medyan cümlesi daha dürüst olur.",why:"Ortalamanın neyi gizleyebileceğini somut bir iş örneğiyle gösteriyor, uygun araçları ve modeldeki karşılığını sayıyor.",follow:"Uç bir değerin veri hatası mı yoksa gerçek bir büyük sipariş mi olduğunu nasıl ayırt edersin?"},{id:"iv-b033",role:"analist",cat:"Performans",q:"Kullanıcılar bir rapor sayfasının yavaş açıldığını söylüyor. Analist olarak ilk adımların neler olur?",weak:"Veri çok büyük, kapasiteyi artırmak gerekir. BT ekibine bildiririm.",strong:"Önce ölçerim: Power BI Desktop’ta Performans Analizi (Performance analyzer) panelini açıp sayfayı yeniler, her görselin DAX sorgusu, görsel çizimi ve diğer sürelerini görürüm. Çoğu zaman bir iki görsel sürenin büyük kısmını alır. Analist olarak yapabileceklerim: sayfadaki görsel sayısını azaltmak (çok sayıda kart yerine tek bir çok satırlı kart), çok satırlı tablolarda varsayılan filtre koymak, ayrıntı tablolarını detaylandırma sayfasına taşımak, gereksiz etkileşimleri kapatmak. Yavaş görselin sorgusunu kopyalayıp DAX sorgu görünümünde çalıştırarak sorunun ölçüde mi olduğunu anlarım. Ölçü ya da model kaynaklıysa bulgumu sürelerle birlikte model sahibine iletirim. Değişiklik öncesi ve sonrası süreyi kaydederim ki iyileşmeyi gösterebileyim.",why:"Tahmin yerine ölçümle başlıyor, analistin kendi yapabileceklerini somut sıralıyor ve gerektiğinde veriyle doğru kişiye yönlendiriyor.",follow:"Performans Analizi’nde “Diğer” süresi çok yüksekse bu neyi gösterir?"},{id:"iv-b034",role:"analist",cat:"Güvenlik ve yönetişim",q:"Raporu bir müdüre “Paylaş” ile gönderdin; açıyor ama hata alıyor ya da veri göremiyor. Olası sebepler neler?",weak:"Muhtemelen bağlantı bozuktur, raporu tekrar paylaşırım.",strong:"Birkaç katmanı sırayla kontrol ederim. Lisans: rapor Pro ya da kullanıcı başı Premium gerektiren bir çalışma alanındaysa ve kapasite yoksa müdürün de uygun lisansı olmalıdır. Model izni: rapor başka bir çalışma alanındaki paylaşılan anlam modeline bağlıysa raporu paylaşmak yetmez, kişinin modele de okuma izni olması gerekir. RLS: modelde RLS varsa ve müdür hiçbir role eklenmemişse rapor açılır ama veri boş gelir. Veri kaynağı: DirectQuery ya da çoklu oturum açma (SSO) kullanan bir kaynaksa müdürün kaynakta da yetkisi olmalıdır. Kontrolü “Erişimi yönet” ekranından ve modelde “Farklı görüntüle” ile yaparım. Kalıcı çözüm olarak kişilere tek tek paylaşmak yerine bir uygulama ve güvenlik grupları kullanırım.",why:"Lisans, model izni, RLS ve kaynak yetkisi katmanlarını sistematik biçimde ayırıyor ve tekil paylaşım yerine yönetilebilir bir yöntem öneriyor.",follow:"Müdür raporu açabiliyor ama “Excel’de analiz et” seçeneğini göremiyor. Hangi izin eksik olabilir?"},{id:"iv-b035",role:"analist",cat:"Güvenlik ve yönetişim",q:"Çalışan maaşlarını içeren bir İK raporu hazırlıyorsun. Verinin rapor dışına sızmasını önlemek için neler yaparsın?",weak:"Raporu yalnızca İK ekibiyle paylaşırım, bu yeterli olur.",strong:"Erişimi sınırlamak ilk adım ama veri rapordan çıkabilir: dışa aktarma, Excel’de analiz, ekran görüntüsü, abonelik e-postaları. Önce hassasiyet etiketi (sensitivity label) uygularım, örneğin “Gizli”; etiket modelden rapora ve dışa aktarılan Excel ya da PDF dosyasına taşınır ve kuruluşun koruma ilkeleri onları da kapsar. Raporu bir güvenlik grubuna, bir uygulama üzerinden dağıtırım. Kişisel maaş satırı gerekmeyen kullanıcılar için ayrı bir özet görünüm sunar, ayrıntıyı yalnızca yetkili role açarım; bu modelde `Calisanlar[Maas]` yerine `[Ortalama Maaş]` ve `[Medyan Maaş]` çoğu soru için yeter. Küçük gruplarda ortalama bile kişiyi ele verebilir, bu yüzden çok küçük kırılımları gizlerim. Son olarak denetim günlüklerinde dışa aktarmaların izlenebildiğini İK ile konuşurum.",why:"Sızıntı yollarını sayıyor, etiket ve dağıtım gibi platform özelliklerini doğru kullanıyor ve küçük grup üzerinden kimlik açığa çıkması riskini fark ediyor.",follow:"Departman yöneticisinin yalnızca kendi ekibinin maaş ortalamasını görmesini istiyorlar. Bunu nasıl kurarsın?"},{id:"iv-b036",role:"gelistirici",cat:"DAX",q:"`Musteriler` tablosuna `Toplam = SUM(Satislar[Tutar])` diye bir hesaplanmış sütun ekleyince her satırda aynı değer çıkıyor; `Toplam = [Net Satış]` yazınca her müşteri farklı. Neden?",weak:"İkinci yazımda ölçü kullanıldığı için daha doğru çalışıyor. SUM hesaplanmış sütunda çalışmaz.",strong:"Hesaplanmış sütun satır bağlamında çalışır ama satır bağlamı kendiliğinden filtre değildir. `SUM(Satislar[Tutar])` filtre bağlamı boş olduğu için tüm satış tablosunu toplar; her müşteride aynı şirket toplamı çıkar. Bir ölçüye başvurmak ise onu örtük olarak `CALCULATE` ile sarar; `CALCULATE` bağlam geçişi (context transition) yapar, yani o anki müşteri satırını bir filtreye çevirir ve bu filtre ilişki üzerinden `Satislar`a yayılır. Aynı sonucu `CALCULATE(SUM(Satislar[Tutar]))` ile de alırım. Dikkat: `[Net Satış]` iptalleri dışarıda bırakır, `SUM(Tutar)` bırakmaz; iki sonuç toplamda da farklıdır. Ayrıca bağlam geçişi büyük tablolarda pahalıdır ve sütun yalnızca yenilemede hesaplanır, dilimleyiciye tepki vermez.",why:"Satır bağlamı ile filtre bağlamı farkını ve ölçü başvurusundaki örtük CALCULATE’i doğru açıklıyor, tanım farkını ve maliyeti de ekliyor.",follow:"Bu sütun `Satislar` gibi çok satırlı bir olgu tablosunda olsaydı bağlam geçişinin hangi beklenmedik etkisi olabilirdi?"},{id:"iv-b037",role:"gelistirici",cat:"DAX",q:'Bir ölçüde `VAR S = [Net Satış] RETURN CALCULATE(S, Satislar[Kanal] = "Web")` yazılmış ve sonuç Web satışını değil toplam satışı veriyor. Neden?',weak:"CALCULATE içinde değişken kullanılamaz, ölçüyü doğrudan yazmak gerekir.",strong:'Değişkenler tanımlandıkları yerde ve o anki filtre bağlamında bir kez hesaplanır, sonra sabit bir değer gibi davranır. `S`, CALCULATE’ten önce, Web filtresi yokken hesaplandı; CALCULATE bir sabitin bağlamını değiştiremez, bu yüzden sonuç değişmez. Doğrusu ifadeyi CALCULATE’in içine koymaktır: `CALCULATE([Net Satış], Satislar[Kanal] = "Web")`. Bu davranış aslında çoğu zaman işimize yarar: `VAR Toplam = [Net Satış]` ile şirket toplamını bir kez hesaplayıp `FILTER` içindeki her satırda tekrar hesaplanmasını önleriz. Kural şudur: bir değerin farklı bağlamlarda yeniden hesaplanmasını istiyorsam değişkene ölçünün sonucunu değil, tabloyu ya da filtreyi koyarım; örneğin `VAR WebFiltre = TREATAS({"Web"}, Satislar[Kanal])` ve sonra `CALCULATE([Net Satış], WebFiltre)`.',why:"Değişkenin değerlendirilme anını doğru açıklıyor, aynı davranışın faydalı kullanımını gösteriyor ve tablo değişkeniyle doğru alternatifi veriyor.",follow:"İç içe bir `FILTER` içinde dış satırın değerine erişmek için `EARLIER` yerine değişkeni nasıl kullanırsın?"},{id:"iv-b038",role:"gelistirici",cat:"DAX",q:"`ALL`, `REMOVEFILTERS`, `ALLEXCEPT` ve `ALLSELECTED` arasındaki farkları ve hangisini ne zaman kullandığını anlat.",weak:"Hepsi filtreleri kaldırır. ALLSELECTED dilimleyiciyi korur, diğerleri korumaz.",strong:"`REMOVEFILTERS` yalnızca CALCULATE değiştiricisidir ve niyeti açıkça söyler: verilen tablo ya da sütunlardaki filtreleri kaldır. `ALL` aynı işi değiştirici olarak yapar ama bir tablo da döndürebilir; `FILTER(ALL(Urunler[Urun]), ...)` gibi yineleme için kullanırım. `ALLEXCEPT(Tablo, Sütun)` tablodaki tüm filtreleri kaldırıp belirtilen sütunlarınkini korur; ama başka bir tablodan gelen filtreyi korumaz, bu yüzden sonradan eklenen sütunlarda sürpriz yaratabilir; çoğu durumda `REMOVEFILTERS(Urunler[Urun])` gibi hedefli kaldırmayı tercih ederim. `ALLSELECTED` görselin kendi satır ve sütun filtrelerini kaldırır ama dilimleyici ve dış filtreleri korur; “görünenler içindeki pay” ya da “seçim içindeki sıra” için uygundur, örneğin `[Seçime Göre Pay %]`. ALLSELECTED’ın sonucu sorgunun yapısına bağlıdır, bu yüzden iç içe yineleyicilerde dikkatli kullanırım.",why:"Dört fonksiyonun davranış farkını, tablo döndürme yeteneğini ve ALLEXCEPT ile ALLSELECTED’ın tuzaklarını doğru kullanım örnekleriyle veriyor.",follow:"`CALCULATE([Net Satış], ALL(Satislar))` yazmak ile `REMOVEFILTERS(Satislar)` yazmak arasında, model performansı açısından bir fark var mı?"},{id:"iv-b039",role:"gelistirici",cat:"DAX",q:"Zaman zekâsı için bir hesaplama grubu kurdun. “YoY %” öğesi `[Net Satış]`ta doğru ama `[Kâr Marjı %]`ta anlamsız sonuç veriyor. Ne yaparsın?",weak:"Kâr marjı için hesaplama grubunu kullanmam, ayrı bir YoY ölçüsü yazarım.",strong:"Hesaplama grubu öğesi `SELECTEDMEASURE()` ile hangi ölçüye uygulanırsa ona aynı formülü uygular. Oran ölçülerinde yıllık değişim çoğu zaman yüzde değil puan farkı olarak istenir: marj %31,9’dan %38,6’ya çıktıysa doğru ifade “+6,7 puan”dır, “+%21” değil. Bunun için öğenin içinde ölçüye göre dallanırım: `IF(ISSELECTEDMEASURE([Kâr Marjı %], [Kategori Payı %]), Bu - GY, DIVIDE(Bu - GY, GY))`. Biçim dizesini de öğe düzeyinde dinamik yaparım ki puan farkı “+0,0 puan”, büyüme “+0,0%” görünsün. Hangi ölçülerin oran olduğunu ölçü adına bakarak değil açık bir listeyle belirlerim. Ayrıca hesaplama gruplarının modeldeki örtük ölçüleri devre dışı bıraktığını ekibe hatırlatırım; kullanıcılar sütunu sürükleyip toplam alamaz.",why:"Oranlarda yüzde ile puan farkını ayırt ediyor, ISSELECTEDMEASURE ile kontrollü dallanma ve dinamik biçim kuruyor, örtük ölçü etkisini de biliyor.",follow:"Aynı modelde iki hesaplama grubu (zaman ve para birimi) varsa uygulanma sırasını neyle belirlersin?"},{id:"iv-b040",role:"gelistirici",cat:"DAX",q:'`SUMMARIZE(Satislar, Urunler[Kategori], "Toplam", [Net Satış])` gibi bir kalıp kod incelemesinde neden eleştirilir? Yerine ne yazarsın?',weak:"SUMMARIZE eski bir fonksiyondur. SUMMARIZECOLUMNS her zaman daha iyidir.",strong:'`SUMMARIZE` içinde hesaplanmış sütun eklemek, motorun satır bağlamı ve filtre bağlamını aynı anda kullanmasına yol açar; bazı durumlarda beklenmeyen sonuçlar ve yavaş planlar üretir. Önerilen kalıp, gruplamayı `SUMMARIZE` ile ya da doğrudan boyut sütunuyla yapıp hesaplamayı `ADDCOLUMNS` ile eklemektir: `ADDCOLUMNS(VALUES(Kategoriler[Kategori]), "Toplam", [Net Satış])`. Burada bağlam geçişi açıkça her kategori satırında gerçekleşir. Sorgu yazıyorsam (EVALUATE) `SUMMARIZECOLUMNS` en verimlisidir ve boş satırları otomatik atar. Ölçü içinde `SUMMARIZECOLUMNS` kullanımı ise bağlama göre kısıtlıydı ve sürümlere göre değişti; ölçüde ADDCOLUMNS ile VALUES ya da SUMMARIZE kombinasyonunu güvenli tercih olarak görürüm. Ayrıca kategori için `Urunler[Kategori]` değil `Kategoriler[Kategori]` kullanırım ki hedefle tutarlı olsun.',why:"Eleştirinin teknik gerekçesini veriyor, ölçü ve sorgu için ayrı doğru kalıpları öneriyor ve modelin boyut kuralını da gözetiyor.",follow:"`ADDCOLUMNS(VALUES(...))` ile oluşturduğun tabloda satışı olmayan kategoriler de görünür mü? İstemiyorsan ne yaparsın?"},{id:"iv-b041",role:"gelistirici",cat:"DAX",q:"Stok bakiyesi gibi yarı toplanabilir (semi-additive) bir ölçüyü nasıl yazarsın? Ay ve yıl düzeyinde ne göstermeli?",weak:"`SUM(StokGorunum[StokAdet])` yazarım, ay ve yılda toplamı verir.",strong:"Stok, ürün ve depo boyunca toplanabilir ama zaman boyunca toplanamaz; Ocak’taki 100 adet ile Şubat’taki 100 adet 200 adet stok demek değildir. Ay ya da yıl düzeyinde dönemin son bakiyesini göstermek gerekir. Bu modelde iki yaklaşım var: `[Stok Adedi]` dönem içindeki son anlık görüntü tarihini `MAX(StokGorunum[Tarih])` ile bulup o günü filtreler; `[Stok Değeri]` ise `LASTNONBLANK(Tarih[Tarih], CALCULATE(COUNTROWS(StokGorunum)))` ile verisi olan son günü seçer. `LASTDATE(Tarih[Tarih])` kullanmak tehlikelidir: ayın son günü için anlık görüntü yoksa BLANK döner. Ürün bazında farklı tarihlerde görüntü varsa her ürünün kendi son tarihini almak için `SUMX(VALUES(Urunler[UrunNo]), ...)` ile ürün başına hesaplamayı düşünürüm. Ortalama stok gerekiyorsa da ayrı bir ölçü olarak `AVERAGEX(VALUES(Tarih[YilAy]), [Stok Adedi])` yazarım.",why:"Hangi boyutta toplanamadığını açıklıyor, modeldeki iki kalıbı ve LASTDATE tuzağını karşılaştırıyor, ürün bazında farklı tarih kenar durumunu ele alıyor.",follow:"Toplam satırında (tüm yıllar) kullanıcı son stok yerine yıllık ortalamayı görmek isterse ne yaparsın?"},{id:"iv-b042",role:"gelistirici",cat:"DAX",q:"Çalışanlar tablosunda her çalışanın yöneticisi var. Bir yöneticinin kendisi ve altındaki tüm ekip üyelerinin satışını nasıl hesaplarsın?",weak:"Yönetici sütununa göre filtreler, yöneticinin doğrudan bağlı çalışanlarının satışını toplarım.",strong:"Doğrudan bağlılar yetmez; hiyerarşi birkaç kat derin olabilir. Ebeveyn-çocuk yapısını düzleştirmek için `PATH(Calisanlar[CalisanNo], Calisanlar[YoneticiNo])` ile bir yol sütunu oluştururum; bu modelde `Calisanlar[Yol]` “1|2|7” gibi değerler taşır. Bir kişinin ekibi, yolunda o kişinin numarası geçen herkestir: `[Ekip Satışı]` ölçüsü `FILTER(ALL(Calisanlar), PATHCONTAINS(Calisanlar[Yol], Kisi))` ile bu kümeyi kurar ve `CALCULATE([Net Satış], Ekip)` ile satışı toplar. Matriste hiyerarşi göstermek istersem `PATHITEM(Calisanlar[Yol], 1)`, `PATHITEM(..., 2)` gibi seviye sütunları üretirim; boş seviyelerde üst seviyenin adını tekrarlamak ya da `ISINSCOPE` ile gizlemek gerekir. Aynı yol sütunu dinamik RLS için de kullanılır: yönetici kendi ekibinin tamamını görür.",why:"Çok katlı hiyerarşi sorununu doğru tanımlıyor, PATH ailesiyle modeldeki somut çözümü veriyor ve aynı yapının RLS’te yeniden kullanımını gösteriyor.",follow:"Bir çalışan yıl ortasında başka bir yöneticiye bağlanırsa geçmiş satışlar hangi ekipte görünmeli? Bunu nasıl modellersin?"},{id:"iv-b043",role:"gelistirici",cat:"DAX",q:"Müşterileri seçilen dönemdeki harcamalarına göre “0–1.000”, “1.000–5.000” gibi dilimlere ayırıp her dilimdeki müşteri sayısını göstermek istiyorsun. Hesaplanmış sütun neden yetmez?",weak:"Müşteri tablosuna harcama dilimi sütunu eklerim, sonra dilimdeki müşterileri sayarım.",strong:'Hesaplanmış sütun yenilemede bir kez, tüm zamanların satışına göre hesaplanır; kullanıcı 2024’ü seçtiğinde müşterinin 2024 harcaması başka dilime düşse bile sütun değişmez. Dilimin dönem seçimine göre değişmesi gerekiyorsa dinamik segmentasyon kullanırım: dilim sınırları ayrı, ilişkisiz bir tabloda durur (bu modelde `MusteriDilimleri`: Dilim, Min, Max) ve ölçü her dilim satırında müşterileri o anki bağlamda yeniden değerlendirir. `[Dilimdeki Müşteri]` önce `ADDCOLUMNS(VALUES(Musteriler[MusteriNo]), "S", [Net Satış])` ile müşteri başı satışı hesaplar, sonra her dilim için sınırlar arasındakileri sayar. Sınırların bir uçta açık, diğer uçta kapalı olması (`>` ve `<=`) bir müşterinin iki dilime birden düşmesini önler. Bu ölçü müşteri sayısı arttıkça pahalılaşır; çok büyük modellerde sınırlı bir dönem için ön hesaplama düşünürüm.',why:"Statik ve dinamik segmentasyon farkını dönem seçimiyle açıklıyor, ilişkisiz tablo kalıbını ve sınır kenar durumunu doğru anlatıyor, maliyeti de belirtiyor.",follow:"Bu dilimlerin satış toplamını gösteren ölçünün toplam satırı, `[Net Satış]` toplamına eşit olur mu? Hangi durumda olmaz?"},{id:"iv-b044",role:"gelistirici",cat:"DAX",q:"“Tek bir değer beklenirken birden çok değer içeren bir tablo sağlandı” hatasını aldın. Bu ne anlama gelir, nasıl düzeltirsin?",weak:"Formülde bir hata var. IFERROR ile sararım, hata görünmez.",strong:'Bir skaler ifadenin beklendiği yerde birden çok satırlı bir tablo dönüyor demektir. En sık sebep `VALUES(Satislar[Kanal])` ya da `RELATEDTABLE` gibi bir tablonun karşılaştırma, `IF` ya da aritmetik işlemde kullanılmasıdır; tek kanal seçiliyken çalışır, filtre kalkınca hata verir. Düzeltme niyete bağlıdır: tek değer bekliyorsam `SELECTEDVALUE(Satislar[Kanal], "Birden çok")` kullanır ve diğer durumu açıkça ele alırım; bir değerin kümede olup olmadığını soruyorsam `"Web" IN VALUES(Satislar[Kanal])` yazarım; bir toplam istiyorsam `SUMX` ya da `MAXX` gibi bir toplayıcıyla tabloyu tek değere indiririm. `IFERROR` ile hatayı gizlemek yanlış sonucu görünmez kılar ve performansı da düşürür. Hatayı yeniden üretmek için ölçüyü filtre olmadan, toplam satırında test ederim; sorun çoğunlukla orada çıkar.',why:"Hatanın mekanizmasını ve en sık sebebini açıklıyor, niyete göre üç doğru düzeltme veriyor ve hatayı gizlemenin neden yanlış olduğunu söylüyor.",follow:"`LOOKUPVALUE` aynı türden bir hatayı hangi durumda verir?"},{id:"iv-b045",role:"gelistirici",cat:"Model",q:"Giderler departman ve gider türü düzeyinde, gider bütçesi ise yalnızca gider türü ve ay düzeyinde geliyor. Departman kırılımında bütçe karşılaştırmasını nasıl kurarsın?",weak:"GiderButce ile Departmanlar arasında bir ilişki kurarım, sorun çözülür.",strong:"Bütçede departman sütunu olmadığı için doğrudan ilişki kurulamaz; bu modelde `[Gider Bütçe]` departman kırılımında her satırda toplam bütçeyi gösterir. Seçenekleri iş kuralına göre değerlendiririm. Her gider türünün tek bir sorumlu departmanı varsa (bu modelde `GiderTurleri[DepartmanNo]`), departman filtresini o sütuna aktarırım: `CALCULATE([Gider Bütçe], TREATAS(VALUES(Departmanlar[DepartmanNo]), GiderTurleri[DepartmanNo]))`. Bir türün bütçesi birden çok departmana paylaştırılıyorsa paylaştırma anahtarlarını içeren bir tablo gerekir ve bu artık finansın kararıdır. En temiz uzun vadeli çözüm, bütçenin kaynağında departman düzeyinde hazırlanmasıdır. Hangisini seçersem seçeyim, raporda bütçesi olmayan departmanlarda bütçe satırının boş kalmasını ve bu durumun bir notla açıklanmasını sağlarım.",why:"Ayrıntı düzeyi uyumsuzluğunu doğru teşhis ediyor, modeldeki somut alanla sanal ilişki kuruyor ve paylaştırmanın bir iş kararı olduğunu vurguluyor.",follow:"TREATAS çözümünde, Departmanlar ile GiderTurleri arasında fiziksel bir ilişki kurmak neden sorun yaratabilir?"},{id:"iv-b046",role:"gelistirici",cat:"Model",q:"Modelde `Urunler` → `Kategoriler` şeklinde bir kartopu (snowflake) yapı var. Bunu düzleştirir misin?",weak:"Kartopu her zaman kötüdür, Kategoriler’i Urunler’e birleştirir ve tabloyu silerim.",strong:"Genel kural boyutları düzleştirmektir; daha az ilişki, daha basit bir alan listesi ve biraz daha hızlı sorgular sağlar. Ama bu modelde `Kategoriler` tablosunun bir görevi var: `Hedefler` kategori düzeyinde ve doğrudan `Kategoriler`e bağlı. Kategoriyi `Urunler`e gömüp tabloyu silersem hedefi ürün tablosuna bağlayamam, çünkü hedefin ürün düzeyi yok. Bu yüzden `Kategoriler`i farklı ayrıntı düzeyindeki olguları birleştiren ortak bir boyut olarak tutarım. Kullanıcı karışıklığını önlemek için `Urunler[Kategori]` sütununu gizler, kategori kırılımlarının hep `Kategoriler[Kategori]` ile yapılmasını sağlarım. Kartopu yalnızca hiçbir olgu doğrudan bağlanmıyorsa ve dal tablosu küçükse düzleştirme adayıdır.",why:"Genel kuralı biliyor ama modeldeki somut gerekçeyle istisnayı tanıyor ve kullanıcı tarafındaki riski gizleme ile yönetiyor.",follow:"Hedefler ileride ürün düzeyinde gelmeye başlarsa modelde neyi değiştirirsin?"},{id:"iv-b047",role:"gelistirici",cat:"Model",q:"Bir müşterinin segmenti yıl içinde Bireysel’den Premium’a değişti. Geçmiş satışları hangi segmentte göstermelisin, nasıl modellersin?",weak:"Müşteri tablosunu güncellerim, yeni segment geçerli olur. Geçmiş de öyle görünür.",strong:"Bu bir yavaş değişen boyut (slowly changing dimension) sorusu ve cevabı iş sorusuna bağlıdır. Mevcut yapı (tip 1) yalnızca güncel segmenti tutar; tüm geçmiş satışlar Premium görünür, bu “bugünkü Premium müşterilerimiz geçmişte ne aldı” sorusu için doğrudur. “Premium segmentin o dönemdeki satışı” isteniyorsa tip 2 gerekir: müşteri tablosunda her değişiklik için yeni bir satır, `GecerliBaslangic` ve `GecerliBitis` sütunları ve satır başına benzersiz bir vekil anahtar. Satış tablosu da satış tarihinde geçerli olan vekil anahtarı taşır; bu eşleme yükleme sırasında (SQL ya da Power Query’de) yapılır. Müşteri sayımı artık iş anahtarı `MusteriNo` üzerinden `DISTINCTCOUNT` ile yapılmalıdır, yoksa aynı müşteri iki kez sayılır. Sık ihtiyaç ikisi birden olduğu için tip 2 tabloya “Güncel Segment” sütunu da eklerim.",why:"Sorunun bir iş kararı olduğunu söylüyor, tip 1 ve tip 2 farkını doğru anlatıyor, vekil anahtar ve sayım tuzağını ele alıyor.",follow:"Tip 2 yapıda RLS’i müşteri temsilcisine göre kurarsan temsilci değişikliği geçmiş görünürlüğü nasıl etkiler?"},{id:"iv-b048",role:"gelistirici",cat:"Model",q:"Kompozit modelde “Çift” (Dual) depolama modu ne işe yarar? Toplama tablolarıyla (aggregations) birlikte nasıl kullanılır?",weak:"Dual hem Import hem DirectQuery demek. Her tabloyu Dual yaparsam en iyisini alırım.",strong:"Kompozit modelde büyük olgu tablosu DirectQuery’de kalırken boyutlar Import edilebilir. Ancak bir Import boyut ile DirectQuery olgu arasındaki sorgular iki kaynağı birleştirmek zorunda kalır ve yavaşlar. Dual modundaki bir boyut, sorguya göre ya bellekten ya da kaynaktan okunur: yalnızca boyutla ilgili bir dilimleyici bellekten gelir, olguyla birleşen sorguda ise kaynağa gönderilip SQL içinde birleşir. Toplama tablosu ise olgunun daha kaba düzeyde (ör. gün × kategori × kanal) özetlenmiş Import kopyasıdır; motor sorgu bu düzeyde cevaplanabiliyorsa onu kullanır, ayrıntıya inilince DirectQuery’ye gider. Toplama tablosunun eşleştiği boyutlar Dual olmalıdır ki eşleşme bozulmasın. Her tabloyu Dual yapmak yenileme yükünü artırır ve fayda sağlamaz; yalnızca iki tarafla da birleşen boyutları seçerim. Toplamanın gerçekten kullanıldığını DAX Studio’da sorgu olaylarıyla doğrularım.",why:"Dual’ın neden gerektiğini mekanizmayla açıklıyor, toplama tablolarıyla ilişkisini kuruyor ve gereksiz kullanımın maliyetini ve doğrulama yolunu biliyor.",follow:"Bir ölçü `DISTINCTCOUNT(Satislar[MusteriNo])` kullanıyorsa toplama tablosu bu sorguyu cevaplayabilir mi?"},{id:"iv-b049",role:"gelistirici",cat:"Model",q:"Bir anlam modelini self-servis kullanıcılara açmadan önce hangi “model hijyeni” adımlarını uygularsın?",weak:"Tabloları ve sütunları güzel adlandırırım, kullanıcılar gerisini bulur.",strong:"Amacım kullanıcının yanlış bir şey seçmesini zorlaştırmaktır. Anahtar sütunları (`MusteriNo`, `UrunNo`) ve olgu tablosundaki ham sütunları gizlerim; kullanıcı `Satislar[Tutar]`ı sürükleyip iptalleri de toplayan bir rakam üretmesin, `[Net Satış]`ı kullansın. Sayısal kodların varsayılan özetini “Özetleme” yaparım ki yıl ya da numara toplanmasın. Ölçüleri görüntüleme klasörlerine (display folders) koyar, her birine açıklama yazarım; açıklama alan listesinde ipucu olarak görünür. Ay adı gibi metin sütunlarına sıralama sütunu atarım. Kategori gibi iki tabloda bulunan alanların yalnızca doğru olanını görünür bırakırım. Biçim dizelerini (para birimi, yüzde) ölçü düzeyinde tanımlarım. Son olarak modeli sertifikalı ya da terfi edilmiş olarak işaretler, kısa bir “nasıl kullanılır” sayfası eklerim.",why:"Hijyen adımlarını kullanıcı hatası önleme amacına bağlıyor, modeldeki somut örneklerle anlatıyor ve belgelendirmeyle bitiriyor.",follow:"Modelde 150 ölçü varsa kullanıcıların doğru ölçüyü bulmasını başka nasıl kolaylaştırırsın?"},{id:"iv-b050",role:"gelistirici",cat:"Model",q:"Tarih tablosunu kaynakta mı, Power Query’de mi, DAX hesaplanmış tablosuyla mı oluşturursun?",weak:"`CALENDARAUTO()` en kolayı, her zaman onu kullanırım.",strong:"Kuruluşta bir veri ambarı varsa tarih boyutunun orada olmasını tercih ederim: mali yıl, resmî tatiller, iş günü gibi kurallar tek yerde durur ve tüm araçlar aynı takvimi kullanır. Yoksa Power Query’de bir parametreyle (başlangıç ve bitiş yılı) üretirim; aynı sorguyu bir veri akışına taşıyarak başka modellerle de paylaşabilirim. DAX hesaplanmış tablosu (`CALENDAR` ile) hızlı bir prototip için uygundur ve model içinde kalır; ama yalnızca o modelde yaşar ve tatil gibi dış verilerle zenginleştirmek zordur. `CALENDARAUTO()`dan kaçınırım: modeldeki tüm tarih sütunlarını tarar ve doğum tarihi gibi ilgisiz bir sütun aralığı 1950’ye kadar uzatabilir; bu modelde `Calisanlar[IseGiris]` ve `Musteriler[DogumYili]` gibi alanlar buna örnektir. Hangi yolu seçersem seçeyim tabloyu tarih tablosu olarak işaretler, tam yılları kapsamasını sağlarım.",why:"Üç seçeneği yeniden kullanılabilirlik ve bakım açısından karşılaştırıyor ve CALENDARAUTO’nun somut tuzağını modelle açıklıyor.",follow:"Tarih tablosu verinin son tarihinden sonraki günleri de içeriyorsa YTD ve “geçen yılın aynı dönemi” ölçüleri nasıl etkilenir?"},{id:"iv-b051",role:"gelistirici",cat:"Performans",q:"VertiPaq Analyzer çıktısında bir sütunun model boyutunun yarısını kapladığını gördün. Bu sütun hangi türden olabilir, ne yaparsın?",weak:"Sütunu silerim. Model küçülür ve sorun çözülür.",strong:"Bellek maliyetini en çok kardinalite, yani farklı değer sayısı belirler; her farklı değer sözlükte saklanır. Tipik şüpheliler: saniyeli tarih-saat sütunları, satır numaraları ya da GUID’ler (`Satislar[SatirNo]` gibi), serbest metin açıklamaları ve çok ondalıklı ondalık sayılar. Önce sütunun kullanılıp kullanılmadığını kontrol ederim; hiçbir ölçü, ilişki ya da görselde yoksa kaldırırım. Gerekliyse kardinaliteyi düşürürüm: tarih-saati ayrı tarih ve saat sütunlarına bölmek, saati dakikaya yuvarlamak, ondalık hassasiyeti işin gerektirdiği düzeye indirmek, metin kodları sayısal anahtarla değiştirmek. Satır düzeyi bir kimlik yalnızca ayrıntı tablosunda gösteriliyorsa onu DirectQuery’de kalan bir ayrıntı tablosuna taşımak da seçenektir. Her değişiklikten sonra VertiPaq Analyzer’ı tekrar çalıştırıp kazancı ölçerim.",why:"Boyutun kardinaliteyle ilişkisini açıklıyor, somut şüphelileri modelden örnekliyor, silmeden önce kullanım kontrolü yapıyor ve kazancı ölçüyor.",follow:"Sipariş numarası sütunu `DISTINCTCOUNT` için gerekli ve kardinalitesi çok yüksek. Ne yapabilirsin?"},{id:"iv-b052",role:"gelistirici",cat:"Performans",q:'`CALCULATE([Net Satış], FILTER(Satislar, Satislar[Kanal] = "Web"))` ile `CALCULATE([Net Satış], Satislar[Kanal] = "Web")` arasında performans farkı var mı? Motor açısından açıkla.',weak:"İkisi de aynı sonucu verir, performans farkı önemsizdir.",strong:"Sonuç çoğu zaman aynıdır, yol farklıdır. İkinci yazım bir sütun filtresidir; motor bunu yalnızca `Kanal` sütununun değerlerinden oluşan küçük bir filtre tablosuna çevirir ve depolama motoru (storage engine) sıkıştırılmış sütun üzerinde hızla tarar. `FILTER(Satislar, ...)` ise tüm olgu tablosunu, mevcut filtreleriyle birlikte satır satır döndüren bir tablo filtresidir; sonuç tablosu tüm sütunları ve genişletilmiş ilişkileri taşır, daha çok bellek ve bazen formül motoru (formula engine) işi gerektirir. Anlam da farklıdır: tablo filtresi mevcut filtreleri korur, sütun filtresi `Kanal` filtresinin üzerine yazar. Ben sütun koşulunu tercih ederim; birden çok sütunu birlikte değerlendiren bir koşul gerekiyorsa da yalnızca o sütunları içeren küçük bir tablo üzerinde `FILTER` kullanırım: `FILTER(ALL(Satislar[Adet], Satislar[BirimFiyat]), ...)`. Farkı DAX Studio’da Server Timings ile ölçerim.",why:"Sütun ve tablo filtresinin motorda nasıl işlendiğini, anlam farkını ve doğru alternatif kalıbı açıklıyor ve ölçerek doğrulamayı öneriyor.",follow:"Hangi durumda `FILTER(Satislar, ...)` kullanmak zorunlu olur?"},{id:"iv-b053",role:"gelistirici",cat:"Performans",q:"DirectQuery ile çalışan bir rapor çok yavaş ve veritabanı ekibi Power BI’ın kaynağı “bombaladığından” şikâyetçi. Ne yaparsın?",weak:"Veritabanı sunucusunun güçlendirilmesini isterim. DirectQuery zaten yavaştır.",strong:"DirectQuery’de her görsel, her etkileşimde kaynağa en az bir sorgu gönderir; yirmi görselli bir sayfa ve elli eş zamanlı kullanıcı binlerce sorgu demektir. Önce Performans Analizi ve kaynağın sorgu izleme araçlarıyla hangi sorguların yavaş ve sık olduğunu bulurum. Rapor tarafında: görsel sayısını azaltır, dilimleyicilere “Uygula” düğmesi eklerim (sorgu azaltma seçenekleri), çapraz vurgulamayı gereksiz yerlerde kapatırım. Model tarafında: boyutları Dual yapar, sık kullanılan özetler için Import toplama tabloları eklerim, ölçüleri SQL’e iyi çevrilecek basit kalıplarla yazarım. Kaynak tarafında: birleşim ve filtre sütunlarına uygun dizinler (ör. sütun deposu dizini), istatistikler ve gerekirse özet tablolar için veritabanı ekibiyle çalışırım. Gerçek zamanlılık şart değilse en büyük kazanç çoğu zaman Import’a ya da Fabric’te Direct Lake’e geçmektir.",why:"DirectQuery yükünün kaynağını doğru açıklıyor, rapor, model ve kaynak katmanlarında somut önlemler sayıyor ve depolama modunu sorgulamayı unutmuyor.",follow:"Kullanıcılar “veri en fazla 15 dakika gecikmeli olabilir” diyorsa hangi alternatifleri önerirsin?"},{id:"iv-b054",role:"gelistirici",cat:"Performans",q:"Bir ölçü kartta anında hesaplanıyor ama 5.000 satırlık bir tablo görselinde 40 saniye sürüyor. Neden olabilir, nasıl iyileştirirsin?",weak:"Tabloda çok satır var. Satırları azaltırsam hızlanır.",strong:"Kart ölçüyü bir kez hesaplar; tablo ise her satır için ayrı bir bağlamda hesaplar. Ölçü içinde satır başına pahalı bir iş varsa (ör. her satırda `ALL(Musteriler)` üzerinde bir `FILTER`, iç içe `SUMX`, ya da satır başına bağlam geçişi) maliyet satır sayısıyla çarpılır. DAX Studio’da görselin sorgusunu çalıştırıp Server Timings’e bakarım: çok sayıda depolama motoru sorgusu ve yüksek formül motoru süresi, motorun satır satır döndüğünü gösterir. İyileştirme yolları: tekrar eden ifadeleri `VAR` ile bir kez hesaplamak; yineleyiciyi en küçük tabloya (ör. `VALUES(Urunler[UrunNo])`) indirmek; satır düzeyinde `IF` yerine `CALCULATE` filtreleri kullanmak; satır bazında sabit olan bir değeri hesaplanmış sütuna taşımak. Bunun yanında görselde makul bir varsayılan filtre ve sayfalama da düşünürüm, ama önce ölçüyü düzeltirim.",why:"Maliyetin satır sayısıyla neden çarpıldığını açıklıyor, teşhis aracını ve okunacak sinyali biliyor, somut yeniden yazım kalıpları öneriyor.",follow:"Server Timings’te tek bir depolama motoru sorgusunun milyonlarca satır döndürdüğünü görürsen bu neyi gösterir?"},{id:"iv-b055",role:"gelistirici",cat:"Performans",q:"Kod incelemesinde `SUMX(Satislar, [Net Satış])` gördün. Sorun ne?",weak:"SUMX yerine SUM kullanmak gerekir, o kadar.",strong:"Her `Satislar` satırı için `[Net Satış]` ölçüsü çağrılıyor; ölçü başvurusu örtük CALCULATE olduğu için her satırda bağlam geçişi gerçekleşir, yani satırın tüm sütunları filtreye dönüşür. Bu, olgu tablosu kadar bağlam geçişi demektir ve büyük tablolarda çok pahalıdır. Daha da kötüsü sonuç yanlış olabilir: olgu tablosunda birebir aynı iki satır varsa (ör. aynı sipariş, ürün, adet ve fiyat), bağlam geçişi ikisini birden filtreler ve tutar iki kez sayılır. Amaç zaten toplam net satışsa doğrudan `[Net Satış]` yeterlidir. Satır düzeyinde bir hesaplama gerekiyorsa sütunlarla yazarım: `SUMX(Satislar, Satislar[Adet] * Satislar[BirimFiyat])`. Bir boyut üzerinde yineleme gerekiyorsa (ör. müşteri başına bir eşik), yineleyiciyi olgu tablosu yerine `VALUES(Musteriler[MusteriNo])` gibi küçük bir tablo üzerinde kurarım.",why:"Hem performans hem doğruluk sorununu (yinelenen satırlar) bağlam geçişi üzerinden açıklıyor ve duruma göre doğru alternatifi veriyor.",follow:"Olgu tablosunda benzersiz bir satır anahtarı varsa yinelenen satır sorunu ortadan kalkar mı? Performans sorunu kalkar mı?"},{id:"iv-b056",role:"gelistirici",cat:"Performans",q:"Kapasitede çalışan büyük bir modelin zamanlanmış yenilemesi bellek hatasıyla başarısız olmaya başladı. Nasıl ele alırsın?",weak:"Kapasiteyi bir üst SKU’ya yükseltmeyi öneririm.",strong:"Tam yenileme sırasında model, eski kopyası sorgulara hizmet ederken yenisi bellekte kurulduğu için kabaca iki katı belleğe ihtiyaç duyabilir. Önce boyutu ve büyümeyi ölçerim: VertiPaq Analyzer ile en büyük tablo ve sütunlar, kapasite ölçümleri uygulamasıyla yenileme anındaki bellek. Sonra yükü azaltırım: kullanılmayan sütunları kaldırmak, yüksek kardinaliteli sütunları düzeltmek, hesaplanmış sütunları kaynağa taşımak. Büyük olgu tablosu için artımlı yenileme (incremental refresh) kurar, yalnızca son bölümleri yenilerim; XMLA uç noktası üzerinden tablo ya da bölüm bazında yenileme de belleği tek seferde harcamayı önler. Büyük model depolama biçiminin açık olduğunu kontrol ederim. Aynı saatte çalışan başka ağır yenilemeleri de kaydırırım. SKU yükseltme, bu adımlardan sonra hâlâ gerekiyorsa veriyle desteklenen bir karardır.",why:"Yenilemenin neden iki kat bellek istediğini biliyor, ölçerek başlıyor, model ve yenileme stratejisinde somut adımlar sayıyor ve SKU yükseltmeyi son seçenek yapıyor.",follow:"Artımlı yenilemede geçmiş bir aya ait bir düzeltme kaynağa geldiyse o bölümü nasıl yenilersin?"},{id:"iv-b057",role:"gelistirici",cat:"Güvenlik ve yönetişim",q:"Her satış temsilcisinin yalnızca kendi müşterilerinin satışlarını görmesini istiyorlar. Dinamik RLS’i bu modelde nasıl kurar ve test edersin?",weak:"Her temsilci için ayrı bir rol açar, filtresine adını yazarım.",strong:"Kişi başına rol bakımı imkânsız hâle gelir; tek bir rol ve kullanıcının kimliğine göre çalışan bir filtre kurarım. Bu modelde `Calisanlar[Eposta]` var; rolün `Calisanlar` tablosundaki filtresi `[Eposta] = USERPRINCIPALNAME()` olur. Filtre `Calisanlar`tan `Satislar[TemsilciNo]` ilişkisiyle satışlara yayılır. Ama müşterinin temsilcisi `Musteriler[TemsilciNo]` üzerinden tanımlıysa ve “müşterilerinin tüm satışlarını” görmek isteniyorsa filtreyi `Musteriler` tablosuna koymam gerekir: `Musteriler[TemsilciNo] = LOOKUPVALUE(Calisanlar[CalisanNo], Calisanlar[Eposta], USERPRINCIPALNAME())`. Bu iki tanım farklı sonuç verir; hangisinin istendiğini netleştiririm. Test için Desktop’ta ve Service’te “Farklı görüntüle” (View as) ile birkaç gerçek e-postayla denerim. Kimliğin büyük-küçük harf ya da takma ad farkıyla eşleşmemesi en sık hatadır. Rol üyeliğini kişilere değil bir güvenlik grubuna veririm.",why:"Tek rollü dinamik kalıbı modeldeki sütunlarla kuruyor, iki farklı iş tanımını ayırıyor, test yöntemini ve en sık hatayı biliyor.",follow:"Yöneticilerin kendi ekiplerindeki tüm temsilcilerin verisini görmesi gerekirse filtreyi nasıl genişletirsin?"},{id:"iv-b058",role:"gelistirici",cat:"Güvenlik ve yönetişim",q:"RLS ile yalnızca kendi bölgesini gören bir bölge müdürü, “şirket toplamı içindeki payımı” görmek istiyor. `ALL` ile payda yazınca neden kendi toplamını görüyor? Ne yaparsın?",weak:"Paydaya `ALL(Musteriler)` yazarım, RLS’i aşar ve şirket toplamını getirir.",strong:"RLS bir filtre bağlamı değildir; kullanıcı için modelin kendisini daraltır. `ALL` ya da `REMOVEFILTERS` yalnızca sorgu filtrelerini kaldırır, güvenlik filtresini kaldıramaz; payda yine yalnızca o bölgenin satışıdır ve pay %100 çıkar. Bu tasarım gereğidir, yoksa RLS bir ölçüyle delinebilirdi. Çözüm, şirket toplamını güvenlik filtresinin etkilemediği ayrı bir yerde tutmaktır: örneğin ay ve kategori düzeyinde şirket toplamlarını içeren küçük bir özet tablo, `Musteriler`e bağlı olmadığı için RLS ondan etkilenmez. Pay ölçüsü bu tablodan paydayı okur. Önce bu toplamın müdürle paylaşılmasının uygun olduğunu veri sahibiyle teyit ederim, çünkü bu bilinçli bir bilgi açılımıdır. Bu yaklaşımı belgeleyip test senaryolarına “Farklı görüntüle” ile payın doğru çıktığını eklerim.",why:"RLS’in neden ALL ile aşılamadığını doğru açıklıyor, güvenli bir model tasarımı öneriyor ve bilgi açılımı kararını veri sahibine götürüyor.",follow:"Bu özet tablonun ayrıntı düzeyini nasıl seçersin ki başka bir bölgenin rakamı dolaylı olarak hesaplanamasın?"},{id:"iv-b059",role:"gelistirici",cat:"Güvenlik ve yönetişim",q:"Raporu kuran çalışan şirketten ayrıldı ve ertesi gün modelin yenilemesi durdu. Neden oldu, bundan sonra nasıl önlersin?",weak:"Yenilemeyi kendi hesabımla yeniden kurarım, sorun çözülür.",strong:"Model ve veri kaynağı bağlantısı büyük ihtimalle ayrılan kişinin hesabına bağlıydı; hesap kapatılınca kimlik bilgileri geçersiz oldu. Kısa vadede modelin sahipliğini (“Devral”) alır, bağlantı kimlik bilgilerini yeniden girerim. Ama kendi kişisel hesabımla kurmak aynı riski bana taşır. Kalıcı çözüm şunlardır: üretim modellerinin sahibi ve veri kaynağı bağlantıları kişi değil hizmet hesabı ya da hizmet sorumlusu (service principal) olur; ağ geçidi bağlantılarının yöneticileri bir grup olur; çalışma alanlarında en az iki yönetici bulunur. Ayrıca modellerin sahiplerini ve bağlantılarını listeleyen düzenli bir envanter (yönetici API’leri ya da tarayıcı) tutarım; işten ayrılma sürecine “BI varlıklarının devri” adımı eklenmesini öneririm.",why:"Kök nedeni kimlik bağımlılığında buluyor, kısa vadeli düzeltmenin riskini görüyor ve kurumsal düzeyde kalıcı önlemler öneriyor.",follow:"Hizmet sorumlusuyla yenilenen bir modelde RLS’i test ederken neye dikkat edersin?"},{id:"iv-b060",role:"gelistirici",cat:"Güvenlik ve yönetişim",q:"Paylaşılan satış modelinin kişisel çalışma alanlarında onlarca kopyası oluştuğunu fark ettin. Bunun riski ne, nasıl yönetirsin?",weak:"Kopyaları silerim ve kullanıcılara bir daha yapmamalarını söylerim.",strong:"Her kopya kendi tanımlarıyla zamanla ayrışır; birkaç ay sonra aynı “net satış” için beş farklı rakam dolaşır, güvenlik ayarları da kopyalarda unutulmuş olabilir. Önce neden kopyaladıklarını anlarım: genellikle bir ölçü eklemek ya da kendi Excel verisini birleştirmek isterler. Bu ihtiyaçları karşılayan yolları açarım: kullanıcılara paylaşılan modelde Yapı (Build) izni vermek, böylece kendi ince raporlarını modelin üstüne kurabilirler; kendi verilerini eklemeleri gerekiyorsa paylaşılan modele DirectQuery ile bağlanan bir kompozit model kurmalarını öğretmek; sık istenen ölçüleri merkezi modele eklemek. Merkezi modeli onaylanmış (endorsed) olarak işaretlerim ki aramada öne çıksın. Kiracı ayarlarıyla yayımlamayı tamamen kapatmak yerine kullanım ve envanter raporlarıyla kopyaları izler, sahipleriyle konuşarak emekliye ayırırım.",why:"Ayrışma ve güvenlik riskini adlandırıyor, kopyalamanın arkasındaki ihtiyacı çözüyor ve yasaklamak yerine yönlendiren bir yönetişim yolu öneriyor.",follow:"Kompozit model kuran bir kullanıcının raporu, merkezi modeldeki RLS’e tabi olur mu?"},{id:"iv-b061",role:"gelistirici",cat:"Power Query",q:"Bir SQL kaynağından gelen sorgunun yenilemesi yavaş. Sorgu katlamanın hangi adımda bozulduğunu nasıl bulursun?",weak:"Adımları tek tek silip yenileme süresine bakarım.",strong:"Power Query’de adıma sağ tıklayıp “Yerel sorguyu görüntüle” (View native query) seçeneğinin etkin olup olmadığına bakarım; etkinse o adıma kadar katlama sürüyordur ve oluşan SQL’i görebilirim. Seçeneğin gri olduğu ilk adım katlamanın bozulduğu yerdir. Power Query Online’da ve veri akışlarında adım başına katlama göstergeleri bunu daha net gösterir. Katlamayı genellikle şu adımlar bozar: dizin sütunu eklemek, bazı metin fonksiyonları, kaynak dışı bir tabloyla birleştirme, yapılandırılmış sütunları açma ya da `Table.Buffer`. Çözüm, katlanan adımları (filtre, sütun seçimi, gruplama) başa almak, katlanmayan adımı sona ya da kaynağa (bir görünüm) taşımaktır. Artımlı yenileme kullanıyorsam `RangeStart` ve `RangeEnd` filtresinin mutlaka katlandığını doğrularım; aksi hâlde her bölüm için tüm tablo okunur.",why:"Katlamayı teşhis etmenin doğru aracını, tipik bozucu adımları ve adım sıralamasıyla çözümü biliyor, artımlı yenilemedeki kritik etkiyi de ekliyor.",follow:"Katlamanın sürdüğünü gördün ama yine de yavaş. Bir sonraki adımın ne olur?"},{id:"iv-b062",role:"gelistirici",cat:"Power Query",q:"Kaynak dosyada bazı satırlarda tarih ve tutar alanları hatalı geliyor ve yenileme ara sıra hatayla bitiyor. Bunu nasıl ele alırsın?",weak:"Hataları kaldır adımını eklerim, hatalı satırlar gider ve yenileme çalışır.",strong:'Hatalı satırları sessizce silmek ciroyu eksik gösterir ve kimse fark etmez. Ben iki yolu birlikte kurarım. Ana sorguda dönüşümü `try ... otherwise` ile güvenli yaparım: örneğin `try Number.FromText([Tutar], "tr-TR") otherwise null`; böylece yenileme durmaz, hatalı değer boş kalır. Ayrıca aynı ara sorgudan başvuruyla bir “hatalı satırlar” sorgusu türetirim: dönüşümü başarısız olan satırları, kaynak dosya adı ve satır numarasıyla birlikte tutar. Bu tabloyu modelde küçük bir veri kalitesi sayfasında gösteririm (“bu ay 12 satır okunamadı, toplam tutarı şu kadar”). Hatanın ana kaynağı biçimse (ondalık ayırıcı, tarih biçimi) dönüşümü kültür parametresiyle düzeltirim. Hatalı satır sayısı belirli bir eşiği geçerse kaynak sahibine bildirim gidecek bir süreç öneririm.',why:"Sessiz veri kaybının riskini fark ediyor, yenilemeyi kırmayan güvenli dönüşümle birlikte hataları görünür kılan bir kontrol kuruyor.",follow:"Hatalı satırları ayrı sorguda tutmak yenileme süresini nasıl etkiler? Bunu nasıl sınırlarsın?"},{id:"iv-b063",role:"gelistirici",cat:"Power Query",q:"Sayfalı (pagination) çalışan bir REST API’den tüm kayıtları almak gerekiyor. Power Query’de nasıl kurarsın, Service’te nelere dikkat edersin?",weak:"Web bağlayıcısıyla adresi girerim, gelen veriyi tabloya çeviririm.",strong:"Tek bir istek yalnızca ilk sayfayı getirir. Önce bir sayfayı getiren özel bir fonksiyon yazarım (ör. sayfa numarası ya da “sonraki” bağlantısı parametre olur). Sonra `List.Generate` ile sayfa boş gelene ya da “sonraki” bağlantısı bitene kadar istek atar, sonuçları birleştiririm. Toplam kayıt sayısı biliniyorsa sayfa listesini önceden üretip her sayfaya fonksiyonu uygulamak daha öngörülebilirdir. Service’te yenilenebilmesi için `Web.Contents` çağrısında taban adresi sabit tutar, değişen kısımları `RelativePath` ve `Query` seçenekleriyle veririm; aksi hâlde Service veri kaynağını doğrulayamaz ve zamanlanmış yenileme kurulamaz. API anahtarını kodun içine yazmam, bağlantı kimlik bilgisi ya da parametre olarak yönetirim. İstek sınırlarına (rate limit) takılmamak için gerekirse bekleme ekler, büyük geçmiş veriyi bir kez alıp sonra yalnızca yeni kayıtları çekerim.",why:"Sayfalama mantığını doğru fonksiyonlarla kuruyor, Service’te yenilemeyi bozan dinamik adres tuzağını ve güvenlik ile istek sınırlarını biliyor.",follow:"Bu tür bir API kaynağını her rapor için ayrı ayrı mı çekersin, yoksa nerede merkezileştirirsin?"},{id:"iv-b064",role:"gelistirici",cat:"Senaryo",q:"200 ölçülü, belgesiz ve önceki geliştiricinin ayrıldığı bir modeli devraldın. İlk bir ayda ne yaparsın?",weak:"Modeli baştan, kendi standartlarımla yeniden yazarım.",strong:"İlk hafta hiçbir şeyi değiştirmeden envanter çıkarırım: modeli PBIP/TMDL biçiminde sürüm kontrolüne alır, ölçü listesini, bağımlılıkları ve hangi raporların hangi ölçüleri kullandığını çıkarırım. Kullanım ölçümleriyle en çok açılan raporları ve en kritik beş ölçüyü belirlerim. İkinci hafta bu kritik ölçüleri kaynakla karşılaştırarak doğrular, iş birimleriyle tanımlarını teyit eder ve açıklamalarını yazarım. Üçüncü hafta Best Practice Analyzer gibi bir kural setiyle sorunları listeler, risk ve etkiye göre sıralarım: kullanılmayan ölçü ve sütunlar, çift yönlü ilişkiler, yavaş kalıplar. Dördüncü hafta küçük, geri alınabilir ilk iyileştirmeleri bir test çalışma alanında yapar ve paydaşlara bir yol haritası sunarım. Baştan yazmak, çalışan ve kullanıcıların güvendiği rakamları bozma riskini taşır; ancak envanter bunu haklı çıkarırsa aşamalı bir yeniden yapılandırma öneririm.",why:"Değişiklikten önce görünürlük ve doğrulama kuruyor, kritik olana öncelik veriyor ve büyük yeniden yazımın riskini bilerek aşamalı ilerliyor.",follow:"Hiçbir raporda kullanılmayan bir ölçüyü silmeden önce başka nerede kullanılıyor olabileceğini nasıl kontrol edersin?"},{id:"iv-b065",role:"gelistirici",cat:"Senaryo",q:"Üretime aldığın bir ölçü değişikliği, ertesi sabah yönetim raporunda yanlış rakamlara yol açtı. İlk bir saatte ve sonrasında ne yaparsın?",weak:"Hatayı bulana kadar raporu düzeltmeye çalışırım, sonra herkese haber veririm.",strong:"İlk hedefim hatanın yayılmasını durdurmaktır, kök neden sonra gelir. Önce rapor sahibine ve etkilenen kullanıcılara kısa bir not geçerim: “Bugünkü rakamlar kontrol ediliyor, karar için kullanmayın.” Sonra son çalışan sürüme dönerim: sürüm kontrolündeki önceki TMDL tanımını ya da dağıtım hattındaki test aşamasından önceki sürümü yeniden dağıtırım. Rakamların eski hâline döndüğünü kontrol edip kullanıcılara bildiririm. Ardından kök nedeni sakin ortamda incelerim: değişikliği hangi senaryo test etmedi (toplam satırı, belirli bir filtre, ilk yıl)? Düzeltmeyi test çalışma alanında, eski ve yeni sonuçları aynı DAX sorgusuyla karşılaştırarak doğrularım. Son olarak süreci güncellerim: kritik ölçüler için karşılaştırma sorgusu, ikinci kişi incelemesi ve dağıtımdan önce kısa bir kontrol listesi.",why:"Önce etkiyi sınırlayıp geri alıyor, iletişimi şeffaf tutuyor, kök nedeni ayrı ele alıyor ve süreci kalıcı olarak iyileştiriyor.",follow:"Ekipte sürüm kontrolü yoksa geri dönmek için hangi seçeneklerin olur?"},{id:"iv-b066",role:"gelistirici",cat:"Senaryo",q:"Bir iş birimi BI ekibini beklemeden kendi Excel ve Power BI dosyalarıyla raporlama yapıyor (“gölge BI”). Buna nasıl yaklaşırsın?",weak:"Bu dosyaları kapattırırım. Tüm raporlar BI ekibinden geçmeli.",strong:"Gölge BI genellikle karşılanmayan bir ihtiyacın belirtisidir; yasaklamak ihtiyacı yok etmez, yeraltına iter. Önce birimin ne yaptığını ve neden beklemediğini anlarım: hız mı, esneklik mi, eksik veri mi? Sonra onları merkezi yapıya bağlarım: kullandıkları veriler paylaşılan modelde varsa Build izniyle kendi raporlarını o modelin üzerine kurmalarını sağlarım; yoksa sık kullandıkları kaynağı modele ekleme önceliğini yükseltirim. Birimden bir “yetkin kullanıcı” (champion) seçip ona eğitim ve destek veririm. Kritik kararlarda kullanılan rakamlar için onaylanmış (sertifikalı) içerik ile kişisel analiz arasındaki farkı açıkça işaretlerim. Böylece birim hızını korur, şirket de tanımların ayrışmasını önler.",why:"Gölge BI’ı bir ihtiyaç sinyali olarak okuyor, yasaklamak yerine birlikte çalışan bir model kuruyor ve onaylı içerik ile kişisel analizi ayırıyor.",follow:"Birimin Excel’deki hesap mantığı merkezi tanımla çelişiyorsa hangisinin doğru olduğuna kim karar verir?"},{id:"iv-b067",role:"gelistirici",cat:"Kavram",q:"Power BI Proje (PBIP) biçimi ve TMDL nedir? Ekip çalışmasına ne kazandırır?",weak:"PBIX dosyasının yeni adı. Dosya daha küçük oluyor.",strong:"PBIP, raporu ve anlam modelini tek bir ikili PBIX dosyası yerine okunabilir metin dosyalarından oluşan bir klasör olarak kaydeder. Model tanımı TMDL (Tabular Model Definition Language) ile tablo ya da nesne başına ayrı dosyalarda tutulur; rapor tanımı da PBIR biçiminde sayfa ve görsel başına ayrı dosyalara ayrılır. Kazancı şunlardır: Git ile satır satır fark (diff) görülebilir, “bu ölçünün formülü kim tarafından, ne zaman değişti” sorusunun cevabı vardır; iki kişi aynı modelin farklı tablolarında çalışıp birleştirebilir; çekme isteğinde (pull request) kod incelemesi yapılabilir; betiklerle toplu değişiklik (ör. tüm ölçülere açıklama eklemek) kolaylaşır. Veri dosyaya dahil edilmez, yerel önbellek ayrıca tutulur ve sürüm kontrolüne konmaz. Fabric’te çalışma alanını Git deposuna bağlamak da aynı metin biçimini kullanır.",why:"Biçimlerin ne olduğunu doğru anlatıyor, ekip çalışmasındaki somut kazançları sayıyor ve verinin depoya girmediğini biliyor.",follow:"İki geliştirici aynı ölçüyü farklı biçimde değiştirip birleştirmede çakışma çıkarsa nasıl çözersin?"},{id:"iv-b068",role:"gelistirici",cat:"Kavram",q:"“İnce rapor” (thin report) yaklaşımı nedir? Neden modeli ve raporu ayrı yayımlamayı önerirsin?",weak:"Raporu daha az sayfayla yapmak demek. Böylece daha hızlı açılır.",strong:"İnce rapor, kendi içinde model barındırmayan, yayımlanmış paylaşılan bir anlam modeline canlı bağlantıyla bağlanan rapordur. Model ayrı bir PBIX ya da PBIP olarak yayımlanır; raporlar onun üzerine kurulur. Faydaları: tek bir modelde tanımlanan `[Net Satış]` tüm raporlarda aynı sonucu verir; model bir kez yenilenir, her rapor için ayrı ayrı değil; model geliştiricisi ile rapor tasarımcısı aynı dosya üzerinde çakışmadan çalışır; RLS tek yerde yönetilir; model değişikliği sürüm kontrolünde rapordan bağımsız izlenir. Dikkat edilecek nokta, modeldeki bir değişikliğin (ör. ölçü adını değiştirmek) bağlı tüm raporları etkilemesidir; bu yüzden değişiklikten önce soy (lineage) görünümüyle etkilenen raporlara bakar, ad değişikliklerinden kaçınırım. Rapora özgü küçük hesaplar için rapor düzeyi ölçüler kullanılabilir.",why:"Kavramı mekanizmasıyla tanımlıyor, tutarlılık, yenileme, iş bölümü ve güvenlik faydalarını sayıyor ve etki analizi riskini de biliyor.",follow:"Rapor düzeyi ölçüler zamanla çoğalırsa ne zaman merkezi modele taşırsın?"},{id:"iv-b069",role:"gelistirici",cat:"Rapor ve görselleştirme",q:"Görsel hesaplamalar (visual calculations) nedir? Ne zaman modeldeki bir ölçü yerine görsel hesaplama kullanırsın?",weak:"Görsel hesaplamalar ölçülerin daha kolay hâlidir, artık her şeyi onlarla yaparım.",strong:"Görsel hesaplama, yalnızca bir görselin içinde tanımlanan ve o görselin satır ve sütunlarından oluşan sanal tablo üzerinde çalışan bir DAX hesabıdır. `RUNNINGSUM`, `MOVINGAVERAGE`, `PREVIOUS` gibi fonksiyonlarla görselin düzenine göre kümülatif toplam, önceki satıra göre fark ya da ebeveyne göre pay kolayca yazılır; filtre bağlamı ve `ALLSELECTED` karmaşası gerekmez. Rapora özgü, tek bir görselde gereken ve başka yerde yeniden kullanılmayacak hesaplar için uygundur; örneğin bir tablodaki aylık satırların kümülatif toplamı. Modelde ölçü kullanmaya devam ettiğim durumlar: hesap birden çok raporda kullanılacaksa, iş tanımıysa (net satış, marj), RLS ya da başka araçlar (Excel, sayfalandırılmış rapor) tarafından da görülmesi gerekiyorsa. Görsel hesaplama görselin sıralamasına ve alanlarına bağlıdır; görsel değişince sonuç da değişebilir, bunu ekibe belirtirim.",why:"Özelliğin kapsamını doğru tanımlıyor, uygun ve uygun olmayan kullanım durumlarını ayırıyor ve görsel düzenine bağımlılık riskini biliyor.",follow:"Görsel hesaplamalar sürüm kontrolünde nerede durur? Kod incelemesinde nasıl görürsün?"},{id:"iv-b070",role:"gelistirici",cat:"SQL",q:"Power Query’de bir SQL kaynağına kendi yazdığın SQL sorgusuyla bağlanmak ile tabloyu seçip adımlarla dönüştürmek arasında nasıl seçim yaparsın?",weak:"SQL yazmak her zaman daha hızlıdır, ben sorguyu doğrudan yazarım.",strong:"Bağlantı penceresine elle yazılan bir SQL sorgusu genellikle katlamanın sonu olur: Power Query sonraki adımları bu sorgunun üzerine katlayamaz ve veriyi belleğe çeker. Artımlı yenilemede `RangeStart` filtresi de katlanmaz, her bölüm için tüm sorgu çalışır. Bu yüzden tercihim tabloyu ya da bir görünümü seçip filtreleri Power Query adımlarıyla eklemektir; Power Query bunları kendisi SQL’e çevirir. Karmaşık bir birleşim gerçekten gerekiyorsa en iyi yer bir veritabanı görünümüdür. Elle sorgu kaçınılmazsa `Value.NativeQuery` ile ve `EnableFolding = true` seçeneğiyle yazarak sonraki adımların katlanmasına izin veririm; sorgunun bunun için uygun yapıda olması gerekir. Ayrıca elle yazılan sorgu güvenlik açısından da yönetilmelidir; Desktop yerel veritabanı sorgusunu çalıştırmadan önce ayrıca onay ister.",why:"Elle SQL’in katlamaya ve artımlı yenilemeye etkisini biliyor, görünüm ve EnableFolding gibi doğru alternatifleri sıralıyor.",follow:"Bir saklı yordamdan (stored procedure) veri almak zorundaysan artımlı yenilemeyi nasıl kurarsın?"},{id:"iv-b071",role:"fabric",cat:"Fabric",q:"Gece çalışan bir not defteri lakehouse’taki satış tablosuna hatalı veri yazdı ve tablo bozuldu. Delta Lake’in hangi özellikleriyle geri dönersin?",weak:"Kaynaktan tüm veriyi yeniden yüklerim. Başka bir yolu yok.",strong:"Delta tabloları her yazma işlemini bir sürüm olarak işlem günlüğüne (transaction log) kaydeder. Önce `DESCRIBE HISTORY` ile tablonun geçmişini görür, hatalı yazmanın hangi sürümde olduğunu bulurum. Zaman yolculuğu (time travel) ile önceki sürümü sorgulayarak (`VERSION AS OF` ya da `TIMESTAMP AS OF`) doğru veriyi kontrol ederim. Doğruysa `RESTORE TABLE ... TO VERSION AS OF` ile tabloyu o sürüme döndürürüm; bu, kaynağı yeniden okumaktan çok daha hızlıdır. Önemli sınır: `VACUUM` eski dosyaları siler; saklama süresi kısa tutulduysa geri dönülecek sürümün dosyaları gitmiş olabilir. Bu yüzden saklama süresini kurtarma ihtiyacına göre belirlerim. Geri döndükten sonra Direct Lake modelini yeniden çerçeveler (reframe), raporların doğru sürümü gösterdiğini kontrol ederim. Kalıcı önlem olarak yazma öncesine satır sayısı ve toplam kontrolü ekler, hatalıysa işi durdururum.",why:"İşlem günlüğü, geçmiş, zaman yolculuğu ve geri yükleme adımlarını doğru sırayla anlatıyor, VACUUM sınırını ve Direct Lake etkisini biliyor.",follow:"Hatalı yazma sonrası başka işler de tabloya yeni veri eklediyse geri yükleme neden tek başına yetmez?"},{id:"iv-b072",role:"fabric",cat:"Fabric",q:"Operasyonel bir Azure SQL veritabanındaki tabloları analitik için Fabric’e almak istiyorsun. Aynalama (mirroring) ne zaman doğru seçimdir, ne zaman değildir?",weak:"Aynalama her zaman en iyisidir, çünkü işlem hattı kurmak gerekmez.",strong:"Aynalama, desteklenen bir kaynaktaki tabloları neredeyse gerçek zamanlı olarak OneLake’e Delta biçiminde çoğaltır; ben bir veri işlem hattı ya da artımlı yükleme mantığı yazmam, değişiklikler sürekli akar. Tabloları olduğu gibi ve düşük gecikmeyle almak istediğimde doğru seçimdir; sonuç SQL analiz uç noktasıyla hemen sorgulanır. Uygun olmadığı durumlar: kaynak desteklenen listede değilse; veriyi yolda ciddi biçimde dönüştürmem, birleştirmem ya da filtrelemem gerekiyorsa (aynalama tabloları olduğu gibi kopyalar, dönüşüm sonraki katmanda yapılır); kaynakta yalnızca küçük bir alt küme gerekiyorsa ve günlük bir kopya yetiyorsa. Aynalanan veri bronz katman gibi düşünülmelidir; iş kurallarını gümüş ve altın katmanlarda uygularım. Kaynağa binecek ek yükü veritabanı ekibiyle önceden konuşurum.",why:"Aynalamanın mekanizmasını ve gücünü doğru tanımlıyor, uygun olmadığı durumları sayıyor ve madalyon mimarisinde yerini belirliyor.",follow:"Aynalanan tablo üzerine doğrudan bir Direct Lake modeli kurmak yerine neden bir altın katman eklemek isteyebilirsin?"},{id:"iv-b073",role:"fabric",cat:"Fabric",q:"Web sitesindeki tıklama olaylarını (`WebOlaylari` gibi) saniyeler içinde izlemek istiyorlar. Fabric’te hangi bileşenleri kullanırsın?",weak:"Lakehouse’a yazar, Direct Lake raporunu her dakika yenilerim.",strong:"Bu bir akış (streaming) senaryosu; Gerçek Zamanlı Zekâ (Real-Time Intelligence) bileşenleri buna göre tasarlanmıştır. Olayları bir olay akışıyla (Eventstream) alır, yolda basit filtre ve dönüşümler uygular ve bir Eventhouse içindeki KQL veritabanına yazarım. KQL, zaman serisi ve çok sayıda küçük olay üzerinde hızlı toplama için uygundur: son beş dakikadaki adım bazında ziyaretçi sayısı, dönüşüm hunisindeki düşüş gibi. Görselleştirme için gerçek zamanlı panoyu (Real-Time Dashboard) ya da KQL veritabanına bağlanan bir Power BI raporunu kullanırım. Uzun dönem analiz ve diğer verilerle birleştirme için KQL verisinin OneLake’te Delta olarak erişilebilir olmasını açarım; böylece günlük özetler altın katmana ve Direct Lake modeline akar. Lakehouse’a her saniye yazmak çok sayıda küçük dosya üretir; sık çerçeveleme de Direct Lake’i gerçek zamanlı yapmaz.",why:"Senaryoyu akış problemi olarak tanıyor, bileşenleri doğru sırayla eşliyor ve uzun dönem analizle bağlantıyı ve yanlış yaklaşımın sorununu açıklıyor.",follow:"Bu olaylarda belirli bir adımda düşüş olduğunda ekibe otomatik bildirim gitmesini nasıl sağlarsın?"},{id:"iv-b074",role:"fabric",cat:"Fabric",q:"Satış müdürü “Bir ürünün stoğu kritik seviyenin altına inince bana haber verilsin” diyor. Fabric’te bunu nasıl kurarsın?",weak:"Raporu her sabah kontrol etmesini öneririm. Uyarı kurmak karmaşıktır.",strong:"Fabric’teki Activator bu iş içindir: bir veri kaynağını izler, tanımladığım koşul gerçekleştiğinde bir eylem tetikler. Kaynak bir Power BI görseli olabilir; örneğin ürün bazında `[Stok Adedi]` gösteren bir tablodan doğrudan uyarı kuralı oluşturabilirim. Ya da daha sık güncellenen veri için bir olay akışı ya da Eventhouse tablosu kullanırım. Kuralı nesne bazında tanımlarım: her ürün için `StokAdet` eşiğin altına düştüğünde, yalnızca durum değiştiğinde (sürekli tekrar etmesin) e-posta ya da Teams mesajı gönderilsin; daha ileri bir adımda bir Power Automate akışıyla satın alma talebi taslağı açılabilir. Eşiği ürün bazında farklı tutmam gerekiyorsa bunu bir tabloda saklar, sabit sayı yazmam. Uyarının ne sıklıkla değerlendirileceğinin, kaynağın yenilenme sıklığıyla sınırlı olduğunu müdüre açıkça söylerim: veri günde bir yenileniyorsa uyarı da günde bir gelir.",why:"Doğru bileşeni ve kaynak seçeneklerini biliyor, kuralı nesne bazında ve tekrarsız tanımlıyor ve gecikmenin veri tazeliğine bağlı olduğunu dürüstçe belirtiyor.",follow:"Uyarı çok sık gelmeye başlar ve müdür e-postaları okumayı bırakırsa ne yaparsın?"},{id:"iv-b075",role:"fabric",cat:"Fabric",q:"Fabric’te Git entegrasyonunu ve dağıtım işlem hatlarını birlikte nasıl kullanırsın? Ekip için bir dal (branch) stratejisi öner.",weak:"Herkes doğrudan ana dala kaydeder, dağıtım hattı da üretime taşır.",strong:"Git entegrasyonu çalışma alanını bir depo dalına bağlar; anlam modelleri, raporlar, not defterleri ve işlem hatları metin olarak sürümlenir. Dağıtım işlem hattı ise içeriği geliştirme, test ve üretim çalışma alanları arasında taşır ve aşamaya özgü kurallarla (bağlantı, parametre) ortam farklarını yönetir. Önerdiğim düzen: her geliştirici kendi özellik dalında ve o dala bağlı kişisel bir çalışma alanında çalışır; işi bitince ana dala çekme isteği açar, bir başkası inceler. Ana dal, ortak geliştirme çalışma alanına bağlıdır ve birleşme sonrası oraya senkronize edilir. Geliştirmeden teste ve üretime geçiş dağıtım hattıyla, onaylı ve kayıtlı biçimde yapılır; üretim çalışma alanında kimse doğrudan düzenleme yapmaz. Veri kaynağı adresleri ve lakehouse bağlantıları dağıtım kurallarıyla ya da değişken kitaplıklarıyla ortama göre değişir. Böylece hem kod incelemesi hem geri alma imkânı olur.",why:"İki aracın farklı görevlerini doğru ayırıyor, uygulanabilir bir dal ve çalışma alanı düzeni öneriyor ve ortam farklarının nasıl yönetileceğini biliyor.",follow:"Bir lakehouse’un içindeki veri Git’e girmez. Bu, ortamlar arasında taşırken hangi işi sana bırakır?"},{id:"iv-b076",role:"fabric",cat:"Fabric",q:"Lakehouse’taki “Tablolar” (Tables) ve “Dosyalar” (Files) bölümlerinin farkı nedir? Bir ham CSV dosyasını nereye koyar, nasıl işlersin?",weak:"İkisi de aynı yer. Dosyayı nereye koyarsam koyayım Power BI okur.",strong:"“Dosyalar” bölümü ham dosyalar için serbest bir alandır: CSV, JSON, resim ya da her türlü biçim burada durabilir ama SQL analiz uç noktası ve Direct Lake bunları tablo olarak görmez. “Tablolar” bölümü ise Delta biçimindeki yönetilen tablolar içindir; bunlar uç noktada SQL ile sorgulanır, Direct Lake modeline kaynak olur ve otomatik olarak keşfedilir. Ham CSV’yi önce “Dosyalar” altında tarihli bir klasöre (ör. `ham/satislar/2024/12/`) bırakırım; bu bronz kopyadır ve gerektiğinde yeniden işlenebilir. Sonra bir not defteri ya da Dataflow Gen2 ile okur, şemayı ve türleri belirler, temizler ve “Tablolar” altına Delta tablosu olarak yazarım. Küçük ve tek seferlik bir dosya için arayüzdeki “Tabloya yükle” seçeneği de yeterlidir. Ham dosyaları silmem; yeniden işleme ve denetim için kaynak kanıtıdır.",why:"İki bölümün hangi motorlar tarafından nasıl görüldüğünü doğru açıklıyor, ham ve işlenmiş veriyi madalyon mantığıyla ayırıyor ve ham dosyayı saklamanın gerekçesini veriyor.",follow:"Başka bir depolama hesabındaki dosyaları kopyalamadan “Dosyalar” altında görmek istersen ne kullanırsın?"},{id:"iv-b077",role:"fabric",cat:"Fabric",q:"Her gece çalışan bir veri işlem hattı (pipeline) ara sıra bir adımda zaman aşımıyla başarısız oluyor ve sabah raporlar eski veriyle açılıyor. Hattı nasıl sağlamlaştırırsın?",weak:"Hata olunca sabah elle yeniden çalıştırırım.",strong:"Önce hatanın deseni: hangi etkinlik, hangi saatte, ne sıklıkla? Kaynağın o saatte başka bir yükle meşgul olduğu sık görülür. Hatta şunları kurarım: geçici hatalara açık etkinliklerde yeniden deneme sayısı ve bekleme süresi; zaman aşımını gerçekçi bir değere ayarlamak; başarısızlık yolunda (on failure) ekibe Teams ya da e-posta bildirimi gönderen bir etkinlik. Adımları yeniden çalıştırılabilir (idempotent) yaparım: bir adım iki kez çalışsa da aynı sonucu üretmeli, yani “ekle” yerine “birleştir” (merge) ya da bölümü silip yeniden yazma. Hat bağımlılıklarını açık tutarım: yükleme başarısızsa anlam modelinin yenilenmesi ya da çerçevelenmesi tetiklenmesin ki rapor yarım veri göstermesin. Son olarak raporda “veri tarihi” gösteren küçük bir kart eklerim; kullanıcı eski veriye baktığını fark eder.",why:"Desen analiziyle başlıyor, yeniden deneme, bildirim, idempotent tasarım ve bağımlılık kontrolünü birlikte kuruyor ve kullanıcıya şeffaflık sağlıyor.",follow:"Hat başarılı bitti ama kaynakta o gece hiç yeni kayıt yoktu. Bunu bir hata olarak yakalamak ister misin? Nasıl?"},{id:"iv-b078",role:"fabric",cat:"Fabric",q:"Direct Lake’in “OneLake üzerinde” ve “SQL uç noktası üzerinde” çalışan iki türü arasındaki farkları ve seçimini anlat.",weak:"İkisi aynı, yalnızca bağlantı adresi farklı.",strong:"İkisi de Delta tablolarını doğrudan okur ama davranışları farklıdır. SQL uç noktası üzerinde Direct Lake tek bir Fabric öğesinin uç noktasına bağlıdır; SQL görünümü ya da SQL tarafında satır düzeyi güvenlik gibi durumlarda DirectQuery’ye geri düşebilir (model ayarıyla yönetilir). OneLake üzerinde Direct Lake ise birden çok Fabric öğesindeki Delta tablolarını (kısayollar dahil) aynı modelde kullanabilir ve DirectQuery’ye geri düşmez; bir sınır aşılırsa sorgu düşmek yerine hata verir. Bu türde SQL görünümleri desteklenmez, SQL tarafındaki satır düzeyi güvenlik de uygulanmaz; güvenlik OneLake güvenliği ve modelin kendi RLS’i ile kurulur. Seçimim: verinin birden çok öğeden geldiği, öngörülebilir performans istenen yeni modellerde OneLake türü; mevcut SQL görünümlerine ve SQL güvenliğine dayanan modellerde SQL uç noktası türü.",why:"İki türün kaynak, geri düşme, görünüm ve güvenlik farklarını doğru açıklıyor ve bunlara dayalı gerekçeli bir seçim kuralı veriyor.",follow:"OneLake türünde bir görünüme ihtiyaç duyarsan görünüm yerine ne kullanırsın?"},{id:"iv-b079",role:"fabric",cat:"Fabric",q:"Şirkette satış, finans ve İK ekipleri Fabric kullanmaya başlayacak. Çalışma alanlarını ve kapasiteleri nasıl tasarlarsın?",weak:"Herkes için tek bir büyük çalışma alanı açarım, yönetimi kolay olur.",strong:"Çalışma alanını hem güvenlik hem yaşam döngüsü sınırı olarak düşünürüm. Her alan için katmanlara göre ayrı çalışma alanları kurarım: örneğin ortak veri mühendisliği (bronz ve gümüş lakehouse’lar), alan bazında altın katman ve anlam modelleri, rapor ve uygulama çalışma alanları. Her biri geliştirme, test ve üretim aşamalarına ayrılır. İK verisi gibi hassas alanlar ayrı çalışma alanında, daha dar yetkiyle durur. Çalışma alanlarını Fabric etki alanlarına (domains) gruplayarak yönetim yetkisini alan sahiplerine devrederim. Kapasite tarafında ağır veri mühendisliği işleri ile kullanıcıların rapor sorgularını mümkünse ayrı kapasitelere koyarım; gece çalışan bir Spark işinin sabah raporlarını yavaşlatmasını istemem. Kapasite ölçümleri uygulamasıyla ilk aylarda tüketimi izleyip boyutu veriyle ayarlarım. Tek dev bir çalışma alanı yetkiyi ve hatayı yayar.",why:"Çalışma alanını güvenlik ve yaşam döngüsü sınırı olarak ele alıyor, hassas veriyi ayırıyor, etki alanlarıyla yetki devri yapıyor ve iş yükü ayrımını kapasiteye yansıtıyor.",follow:"Finans ekibi satış lakehouse’undaki bir tabloyu kendi modelinde kullanmak isterse veriyi kopyalamadan nasıl paylaşırsın?"},{id:"iv-b080",role:"fabric",cat:"Fabric",q:"Gümüş katmana yükleme yapan bir not defteri yeniden çalıştırıldığında satırlar iki kez ekleniyor. Yüklemeyi nasıl tasarlarsın?",weak:"Not defterini iki kez çalıştırmamaya dikkat ederim.",strong:"Yükleme yeniden çalıştırılabilir (idempotent) olmalı; arıza sonrası yeniden deneme normal bir durumdur. Ekleme (append) yerine iş anahtarına göre birleştirme yaparım: Delta’da `MERGE INTO gumus.satislar AS h USING yeni AS y ON h.SatirNo = y.SatirNo WHEN MATCHED THEN UPDATE SET * WHEN NOT MATCHED THEN INSERT *`. Böylece aynı kayıt ikinci kez gelirse güncellenir, kopyalanmaz. Gelen partinin kendi içinde de kopya olabilir; birleştirmeden önce anahtara göre tekilleştirir, en güncel kaydı seçerim. Tarih bazlı yüklemelerde alternatif, ilgili günün bölümünü silip yeniden yazmaktır. Ek olarak her çalıştırmada bir kalite kontrolü yaparım: anahtar boş mu, anahtar tekil mi, tutar negatif mi; kural ihlali varsa satırları bir karantina tablosuna yazar ve gümüşü kirletmem. Yükleme kimliğini ve zamanını bir sütunda tutarım ki hangi satırın hangi çalıştırmadan geldiği bilinsin.",why:"Idempotent tasarımı MERGE ile somutlaştırıyor, parti içi kopyayı ve alternatif bölüm yazımını biliyor, kalite kontrolü ve izlenebilirlik ekliyor.",follow:"Kaynakta silinen kayıtların gümüş katmandan da silinmesi gerekiyorsa MERGE ifadesini nasıl genişletirsin?"},{id:"iv-b081",role:"fabric",cat:"Fabric",q:"Direct Lake modeline bir tarih tablosu ve birkaç yardımcı tablo (ör. ölçü seçimi tablosu) eklemek istiyorsun. Bunları nerede ve nasıl oluşturursun?",weak:"Import modelde yaptığım gibi DAX ile hesaplanmış tablo olarak eklerim.",strong:"Direct Lake tabloları Delta tablolarından okunur; model içindeki hesaplanmış tablo ve sütun desteği türe göre sınırlıdır ve bazı seçenekler önizleme durumundadır. En sağlam yol, tarih tablosunu altın katmanda bir Delta tablosu olarak üretmektir: bir not defteri ya da SQL ile her günü bir kez içeren, yıl, ay, mali yıl ve tatil sütunlarına sahip bir tablo. Böylece hem modelde hem SQL sorgularında aynı takvim kullanılır ve tablo diğer modellerle paylaşılır. Ölçü seçimi gibi küçük, statik yardımcı tablolar için de aynı yöntemi kullanabilirim; alan parametreleri ve hesaplama grupları ise model nesneleri olarak tanımlanabilir. OneLake üzerinde Direct Lake türü Import tablolarla birleşik (kompozit) modele izin verdiği için küçük bir yardımcı tabloyu Import olarak eklemek de bir seçenektir, ama onun ayrıca yenilenmesi gerekir. Kararı vermeden güncel belgelerdeki destek durumuna bakarım.",why:"Direct Lake’in sınırını biliyor, tarih tablosunu yeniden kullanılabilir biçimde altın katmana koyuyor ve küçük tablolar için seçenekleri bedelleriyle sıralıyor.",follow:"Tarih tablosu her gün yeni günler eklenerek büyüyorsa modelin bunu görmesi için ne gerekir?"},{id:"iv-b082",role:"fabric",cat:"Fabric",q:"Bir veri bilimcinin keşif için yazdığı not defterini her gece çalışan bir üretim işine dönüştürmen gerekiyor. Neleri değiştirirsin?",weak:"Not defterini olduğu gibi bir zamanlamaya bağlarım.",strong:"Keşif not defterleri genellikle sabit yollar, elle çalıştırılan hücreler ve ara çıktılarla doludur. Önce sabit değerleri parametre hücresine taşırım (tarih aralığı, lakehouse adı); böylece işlem hattından parametreyle çağrılabilir ve geliştirme ile üretimde farklı değerler kullanılır. Keşif hücrelerini kaldırır, mantığı fonksiyonlara bölerim. Kütüphane sürümlerini bir Fabric ortamında (environment) sabitlerim ki bir güncelleme işi bozmasın. Yazma adımlarını idempotent yapar, her çalıştırmanın satır sayısını ve süresini bir günlük tablosuna yazarım. Hata olduğunda işin sessizce bitmemesi için kritik kontrollerde açıkça hata fırlatırım; işlem hattı bu hatayı yakalayıp bildirim gönderir. Not defterini Git’e alır, değişiklikleri inceleme ile birleştiririm. Son olarak birkaç gün test ortamında, üretim verisinin bir kopyasıyla çalıştırıp sonuçları karşılaştırırım.",why:"Keşif kodunun üretimdeki risklerini tanıyor ve parametre, ortam, idempotent yazma, günlükleme, hata yönetimi ve sürüm kontrolüyle somut bir dönüşüm planı veriyor.",follow:"İş her gece aynı Spark oturumu başlatma süresini bekliyor ve bu toplam sürenin büyük kısmı. Ne yapabilirsin?"},{id:"iv-b083",role:"fabric",cat:"Performans",q:"Direct Lake raporu çerçevelemeden sonraki ilk açılışta yavaş, sonraki açılışlarda hızlı. Neden ve ne yapabilirsin?",weak:"İlk açılışta internet yavaştır. Kullanıcılara biraz beklemelerini söylerim.",strong:"Direct Lake sütunları ihtiyaç duyuldukça Delta dosyalarından belleğe yükler (transcoding). Çerçeveleme ya da bellekten çıkarma (eviction) sonrası bellek soğuktur; ilk sorgu kullandığı sütunları dosyadan okuyup bellek biçimine çevirmek zorundadır, sonraki sorgular bellekten cevaplanır. İyileştirme yolları: çerçevelemeden hemen sonra en kritik sayfaların sorgularını çalıştıran bir ısıtma adımı (ör. işlem hattında not defterinden birkaç DAX sorgusu) eklemek; modelde yalnızca gereken sütunları tutmak, çünkü her sütun ayrı yüklenir; Delta tablolarının V-Order ile yazılmış ve küçük dosyalarının birleştirilmiş (`OPTIMIZE`) olmasını sağlamak; yüksek kardinaliteli sütunları azaltmak. Kapasitenin bellek sınırına yakın çalışılıyorsa sütunlar sık sık bellekten çıkarılır ve soğuk başlangıç tekrar eder; bunu kapasite ölçümleriyle izler, gerekirse model boyutunu küçültürüm.",why:"Soğuk bellek ve transcoding mekanizmasını doğru açıklıyor, ısıtma, sütun budama, dosya düzeni ve bellek baskısı gibi somut önlemler sıralıyor.",follow:"Çerçeveleme her saat yapılıyorsa ısıtma maliyeti ile veri tazeliği arasındaki dengeyi nasıl kurarsın?"},{id:"iv-b084",role:"fabric",cat:"Performans",q:"Spark ile yazdığın bir dönüşüm işi her ay daha da yavaşlıyor. Nereden başlarsın?",weak:"Daha büyük bir Spark havuzu seçerim, iş hızlanır.",strong:"Önce Spark arayüzünde işin aşamalarına bakar, zamanın nerede geçtiğini bulurum: okuma mı, karıştırma (shuffle) mı, yazma mı? Aylık yavaşlama genellikle büyüyen veriyle doğrusal olmayan bir adımın birleştiğini gösterir. Sık sebepler: her çalıştırmada tüm geçmişi okumak (yalnızca yeni bölümleri okumak yerine); çok küçük dosyalar ya da aşırı ince bölümleme (ör. gün ve ürün bazında bölümlemek, binlerce küçük klasör); büyük iki tablonun birleşiminde dengesiz anahtar dağılımı (skew); gereksiz `collect` ya da pandas’a dönüşüm. Çözümler: artımlı işleme ve bölüm budama (partition pruning), bölümlemeyi daha kaba bir sütunla (ör. ay) yapmak, düzenli `OPTIMIZE` ile dosyaları birleştirmek, küçük boyut tablosunu yayınlayarak (broadcast) birleştirmek. Havuzu büyütmek tasarım sorununu yalnızca erteler ve kapasite tüketimini artırır.",why:"Ölçerek başlıyor, büyüyen veride yavaşlamanın tipik sebeplerini sayıyor ve kaynak artırmak yerine tasarım düzeltmeleri öneriyor.",follow:"Bölüm budamanın gerçekten çalıştığını nasıl doğrularsın?"},{id:"iv-b085",role:"fabric",cat:"Güvenlik ve yönetişim",q:"Ambarın SQL tarafında satır düzeyi güvenlik tanımladın. Aynı veriye dayanan Direct Lake raporunda bir kullanıcı tüm satırları görüyor ya da rapor beklenmedik biçimde yavaşlıyor. Ne olmuş olabilir?",weak:"Güvenlik yenilemeden sonra devreye girer, raporu yenilerim.",strong:"İki olası durum var ve ikisi de Direct Lake türüne bağlı. Model SQL uç noktası üzerinde Direct Lake ise SQL tarafındaki satır düzeyi güvenlik uygulanabilmek için sorguyu DirectQuery’ye düşürür; güvenlik çalışır ama rapor yavaşlar. Model OneLake üzerinde Direct Lake ise SQL tarafındaki güvenliği hiç kullanmaz; Delta dosyalarını doğrudan okur. Bu durumda kullanıcı OneLake’te dosyaya erişebiliyorsa tüm satırları görür. Ayrıca modelin bağlantısı sabit bir kimlikle kurulduysa sorgular kullanıcının değil o kimliğin yetkisiyle çalışır. Çözüm, güvenliği tüketildiği katmanda yeniden düşünmektir: Direct Lake raporları için satır düzeyi güvenliği anlam modelinin RLS’i ile tanımlar, sabit kimlikli bulut bağlantısı kullanırım; doğrudan veri erişimi olan kullanıcılar için OneLake güvenliği rollerini kurarım. Her katmanda “Farklı görüntüle” ya da test kullanıcısıyla doğrularım.",why:"Direct Lake türüne göre farklı güvenlik davranışını, geri düşmenin performans etkisini ve kimlik modelini doğru açıklıyor ve katmana uygun çözüm veriyor.",follow:"Aynı kuralı hem SQL tarafında hem modelde ayrı ayrı tanımlamanın bakım riskini nasıl azaltırsın?"},{id:"iv-b086",role:"fabric",cat:"Güvenlik ve yönetişim",q:"Lakehouse’ta müşterilerin T.C. kimlik numarası ve telefon gibi kişisel verileri var. Kişisel verilerin korunması mevzuatı açısından nasıl bir yaklaşım kurarsın?",weak:"Çalışma alanına yalnızca yetkili kişileri eklerim, bu yeterli olur.",strong:"İlk ilke veri en aza indirmedir: analiz için kimlik numarasına gerçekten ihtiyaç var mı? Çoğu zaman yoktur; gümüş katmanda kimliği tek yönlü bir özetle (hash) ya da vekil anahtarla değiştirir, açık değeri yalnızca bronzda ve dar yetkili bir çalışma alanında tutarım. Telefon gibi alanlar altın katmana ve anlam modeline hiç taşınmaz. Erişimi katmanlarda kurarım: çalışma alanı rolleri, OneLake güvenliği rolleriyle tablo ve sütun düzeyinde kısıtlama, ambar tarafında gerekiyorsa dinamik veri maskeleme. Hassasiyet etiketleriyle verinin sınıfını işaretler, etiketlerin aşağı akış öğelerine taşınmasını sağlarım. Microsoft Purview ile hangi tabloda kişisel veri olduğunu kataloglar, saklama süresini ve silme taleplerinin nasıl uygulanacağını hukuk ekibiyle belirlerim. Delta’daki eski sürümlerin de silinen veriyi içerebileceğini unutmam; silme sonrası saklama süresine uygun `VACUUM` gerekir.",why:"En aza indirme ilkesiyle başlıyor, katmanlı erişim ve maskelemeyi doğru araçlarla kuruyor ve Delta geçmişinde kalan veri gibi ince bir riski de biliyor.",follow:"Bir müşteri verilerinin silinmesini isterse bunu tüm katmanlarda nasıl uygularsın?"},{id:"iv-b087",role:"fabric",cat:"Senaryo",q:"Şirket 30 Power BI raporu, beş şirket içi veri kaynağı ve birkaç Dataflow Gen1 ile Fabric’e geçmek istiyor. Geçişi nasıl planlarsın?",weak:"Hepsini bir hafta sonunda Fabric’e taşırım, sonra sorunları çözeriz.",strong:"Önce envanter: hangi rapor hangi modele, hangi model hangi kaynağa ve ağ geçidine bağlı, kim kullanıyor, ne sıklıkla yenileniyor? Kullanılmayan raporları geçişten önce emekliye ayırırım. Sonra hedefi netleştiririm: Power BI içeriği Fabric kapasitesindeki bir çalışma alanında olduğu gibi çalışmaya devam eder; asıl iş veri katmanındadır. Şirket içi kaynaklar için ağ geçidi gerekmeye devam eder; veriyi işlem hatlarıyla ya da desteklenen kaynaklarda aynalama ile bronz lakehouse’a alırım. Dataflow Gen1’leri Gen2’ye taşırım. Pilot olarak tek bir alanı (ör. satış) uçtan uca taşır, Direct Lake modelini mevcut Import modelle aynı DAX sorgularıyla karşılaştırarak rakamların birebir tuttuğunu doğrularım. Başarı ölçütlerini (yenileme, sorgu süresi, kapasite tüketimi) önceden yazarım. Sonra dalgalar hâlinde ilerler, her dalgadan sonra kullanıcı eğitimi ve geri bildirim alırım.",why:"Envanterle başlıyor, neyin değişip neyin değişmediğini doğru ayırıyor, pilot ve sayısal doğrulamayla riski azaltıyor ve aşamalı ilerliyor.",follow:"Pilotta Direct Lake modeli bir ölçüde Import modelden farklı sonuç verirse ilk neye bakarsın?"},{id:"iv-b088",role:"fabric",cat:"SQL",q:"Lakehouse’un SQL analiz uç noktasında bir tablo oluşturmaya çalıştın ve hata aldın. Neden? Aynı işi Fabric’te nerede, nasıl yaparsın?",weak:"Yetkim yoktur, yöneticiden yazma izni isterim.",strong:"Lakehouse’un SQL analiz uç noktası tablolar için salt okunurdur; tablolar Spark ya da diğer lakehouse araçlarıyla yazılır, uç nokta bunları T-SQL ile sorgulamaya açar. Uç noktada görünüm, fonksiyon ve güvenlik nesneleri oluşturabilirim ama `CREATE TABLE` ya da `INSERT` çalışmaz. T-SQL ile tablo oluşturup yazmak istiyorsam ambarı (warehouse) kullanırım: ambar tam işlem desteği olan bir T-SQL ortamıdır ve `CREATE TABLE AS SELECT` (CTAS) ile bir sorgunun sonucundan tablo üretmek mümkündür, örneğin günlük satış özetini ambarda bir tabloya yazmak. Aynı çalışma alanındaki lakehouse tablolarını ambardan üç parçalı adla (`lakehouse.dbo.tablo`) sorgulayabilirim; böylece veri kopyalamadan birleştirme yapılır. Ekip SQL ağırlıklıysa altın katmanı ambarda, Spark ağırlıklıysa lakehouse’ta tutmak mantıklıdır.",why:"Uç noktanın salt okunur doğasını ve neyin yapılabildiğini doğru açıklıyor, ambarı ve CTAS’i doğru alternatif olarak gösteriyor ve çapraz sorgu imkânını biliyor.",follow:"Ambarda oluşturduğun özet tablo ile lakehouse’taki ham tablo arasında tutarlılığı nasıl kontrol edersin?"},{id:"iv-b089",role:"hepsi",cat:"Senaryo",q:"Analizin, yöneticinin toplantıda savunduğu bir fikrin tersini gösteriyor. Sonucu nasıl paylaşırsın?",weak:"Rakamlar ne diyorsa onu toplantıda doğrudan söylerim.",strong:"Önce kendi analizimi sınarım: tanımlar doğru mu, dönem seçimi adil mi, başka bir kırılımda sonuç değişiyor mu? Yanılmadığımdan emin olunca yöneticiyle toplantıdan önce bire bir konuşurum; kimseyi kalabalık önünde şaşırtmam. Bulguyu bir saldırı gibi değil, ortak hedefe katkı olarak sunarım: “Bu kampanyanın satışları artırması bekleniyordu; veride bu görünmüyor, şu üç olası sebep var.” Varsayımlarımı ve sınırlarımı açıkça yazarım, yöneticinin bildiği ama veride olmayan bir bağlam olabilir. Kararı ona bırakırım ama rakamı değiştirmem. Sonra birlikte bir sonraki adımı konuşuruz: ek veri, daha uzun gözlem süresi ya da küçük bir test. Böylece güven kaybetmeden doğruyu söylemiş olurum.",why:"Önce kendini sınıyor, zamanlama ve ortamı doğru seçiyor, bulguyu ortak hedefe bağlıyor ve rakamın bütünlüğünü koruyor.",follow:"Yönetici “Bu analizi sunma” derse ne yaparsın?"},{id:"iv-b090",role:"hepsi",cat:"Senaryo",q:"Önemli bir teslimden iki gün önce kaynak verinin bir kısmının eksik geldiğini fark ettin. Ne yaparsın?",weak:"Teslim tarihini kaçırmamak için mevcut veriyle teslim ederim, sonra düzeltirim.",strong:"Önce etkinin büyüklüğünü ölçerim: hangi dönem, hangi tablolar, toplamın yüzde kaçı? Örneğin bir haftalık satış eksikse ana KPI’lar ne kadar değişir? Sonra kaynağın sahibine hemen ulaşır, düzeltmenin ne zaman mümkün olduğunu öğrenirim. Aynı gün paydaşa durumu ve seçenekleri yazarım: (1) eksik dönemi açıkça işaretleyerek zamanında teslim etmek, (2) kaynak düzeldikten sonra kısa bir gecikmeyle tam veriyle teslim etmek, (3) etkilenmeyen bölümleri şimdi, kalanı sonra teslim etmek. Her seçeneğin riskini bir cümleyle belirtir, kararı karar vericiye bırakırım. Eksik veriyi sessizce teslim etmek, sonradan fark edildiğinde tüm çalışmanın güvenilirliğini yok eder. Sonrası için yükleme sürecine satır sayısı ve tarih aralığı kontrolü eklerim ki eksiklik iki gün önce değil aynı gün fark edilsin.",why:"Etkiyi ölçüyor, sahibine hızla ulaşıyor, paydaşa şeffaf seçenekler sunuyor ve tekrarını önleyecek bir kontrol ekliyor.",follow:"Paydaş “eksik olduğunu yazma, kimse fark etmez” derse ne yaparsın?"},{id:"iv-b091",role:"hepsi",cat:"Senaryo",q:"Senden kıdemli bir meslektaşın yazdığı ve yıllardır kullanılan bir ölçüde hata buldun. Nasıl ele alırsın?",weak:"Hatayı düzeltir, ekibe e-postayla bildiririm.",strong:"Önce hatanın gerçekten hata olduğundan emin olurum: belki bilinçli bir tanım tercihidir ve belgelenmemiştir. Bunu anlamak için ölçüyü küçük bir örnekle, kaynakla karşılaştırarak test eder, farkın nerede çıktığını gösteren bir DAX sorgusu hazırlarım. Sonra meslektaşla bire bir konuşurum, kanıtı gösterir ve “Ben bunu böyle okudum, bir şeyi kaçırıyor muyum?” diye sorarım; suçlayıcı değil merak eden bir dil kullanırım. Gerçekten hataysa düzeltmeyi birlikte planlarız: etkilenen raporlar, geçmiş kararlara etkisi, kullanıcılara nasıl duyurulacağı. Düzeltmeyi kendi başıma üretime almam; ölçünün sahibiyle ve değişiklik süreciyle ilerlerim. Kredi ve sorumluluk konusunda da cömert olurum; amaç kimin hata yaptığı değil, rakamın doğru olmasıdır.",why:"Önce doğruluyor, kanıtla ama saygılı bir dille yaklaşıyor, etkiyi birlikte yönetiyor ve değişiklik sürecine uyuyor.",follow:"Meslektaş hatayı kabul etmez ve sen haklı olduğundan eminsen bir sonraki adımın ne olur?"},{id:"iv-b092",role:"hepsi",cat:"Senaryo",q:"Paylaşılan anlam modelini kullanmaya başlayacak 20 iş kullanıcısına eğitim vermen isteniyor. Eğitimi nasıl kurgularsın?",weak:"Power BI’ın tüm özelliklerini anlatan iki saatlik bir sunum hazırlarım.",strong:"Eğitimi araçtan değil kullanıcıların işinden başlatırım. Önce iki üç kullanıcıyla konuşup en sık sordukları üç soruyu öğrenirim, örneğin “bu ay hangi kategoride hedefin altındayız?”. Eğitimi bu soruları kendi verileriyle cevaplayan kısa, uygulamalı oturumlara bölerim: 45 dakika, en fazla üç yeni kavram. İlk oturumda modelin yapısını basit bir resimle anlatırım: hangi ölçüyü kullanmalılar (`[Net Satış]`, ham `Tutar` değil), hangi alanla kırılım yapmalılar (`Kategoriler[Kategori]`). Herkesin aynı alıştırmayı kendi bilgisayarında yaptığı bir bölüm eklerim. Sonrasında bir sayfalık kısa bir başvuru kılavuzu, sık sorulan sorular ve bir soru kanalı bırakırım. İki hafta sonra kullanım ölçümlerine ve gelen sorulara bakarak ikinci oturumun içeriğini belirlerim. Ekipten bir iki istekli kişiyi yetkin kullanıcı (champion) olarak destekler, ilk soruların onlara gitmesini sağlarım.",why:"Eğitimi kullanıcının sorularına göre kurguluyor, kısa ve uygulamalı tutuyor, modelin doğru kullanımını öğretiyor ve eğitim sonrası destek ve ölçümü planlıyor.",follow:"Katılımcıların bilgi düzeyi çok farklıysa oturumu nasıl yönetirsin?"},{id:"iv-b093",role:"hepsi",cat:"Senaryo",q:"Bir yönetici rapordaki Copilot’a soru sormuş ve senin panondaki rakamdan farklı bir cevap almış. Ne yaparsın?",weak:"Copilot yanlış cevap vermiştir, yöneticiye kullanmamasını söylerim.",strong:"Önce yöneticinin sorusunu ve aldığı cevabı tam olarak alırım; farkın çoğu sorunun yorumlanmasından gelir. Copilot hangi ölçüyü, hangi filtreyi ve hangi dönemi kullanmış? Örneğin “satış” dendiğinde `[Net Satış]` yerine `Satislar[Tutar]` toplamını almışsa iptaller dahil olmuştur. Sonra modeli yapay zekâya hazırlarım: “Yapay zekâ için verileri hazırla” (Prep data for AI) bölümünde yapay zekânın görebileceği alanları sınırlar (AI veri şeması), ham sütunları dışarıda bırakırım; “satış”ın `[Net Satış]` anlamına geldiğini, mali yılın ne zaman başladığını yapay zekâ talimatlarına yazarım; sık sorulan sorular için doğrulanmış yanıtlar (verified answers) tanımlarım. Ölçülere ve tablolara açık açıklamalar eklemek de cevapların kalitesini artırır. Yöneticiye de cevabın hangi tanıma dayandığını kontrol etmesini, kritik kararlarda onaylı panodaki rakamı esas almasını öneririm.",why:"Farkın kaynağını soru yorumunda arıyor, modeli yapay zekâ için hazırlamanın somut araçlarını biliyor ve kullanıcıya doğru bir kontrol alışkanlığı öneriyor.",follow:"Doğrulanmış yanıtları kim tanımlamalı ve ne sıklıkla gözden geçirilmeli?"},{id:"iv-b094",role:"hepsi",cat:"Kavram",q:"Bir analiz, indirimli siparişlerin daha çok iade edildiğini gösteriyor ve biri “indirim iadeye yol açıyor” diyor. Bu yorumu nasıl değerlendirirsin?",weak:"Veri bunu gösteriyorsa doğrudur. İndirimleri azaltmayı öneririm.",strong:"İlişki nedensellik değildir. Önce ilişkinin gerçekten var olup olmadığını kontrol ederim: `Satislar[IndirimBandi]` kırılımında `[İade Oranı %]`e bakar, her bantta yeterli sipariş olup olmadığını görürüm; küçük bantlarda oran tesadüfen yüksek çıkabilir. Sonra üçüncü bir etkeni ararım: indirimler belirli kategorilerde ya da kanallarda yoğunsa ve o kategorilerin iadesi zaten yüksekse (ör. giyimde beden değişimi), ilişkiyi kategori değil indirim yaratıyor gibi görünür. Bunu kategori ve kanal içinde indirimli ile indirimsizi karşılaştırarak test ederim. Zaman sırasını da düşünürüm: iade edilen ürünlerin tekrar satışa indirimle çıkması ters yönde bir ilişki doğurabilir. Kesin nedensellik için kontrollü bir test (ör. bazı ürünlerde indirimi rastgele değiştirmek) gerekir. Sonucu “ilişkili, ama sebep olduğu henüz gösterilmedi” diye raporlarım.",why:"Örneklem büyüklüğü, karıştırıcı değişken ve ters nedensellik gibi temel tuzakları modeldeki alanlarla test ediyor ve dürüst bir sonuç cümlesi kuruyor.",follow:"Kategori içinde de ilişki sürüyorsa bir sonraki adımın ne olur?"},{id:"iv-b095",role:"hepsi",cat:"Kavram",q:"Müşteri hizmetlerinde “ortalama çözüm süresi” KPI’ı var. Ortalama yerine medyanı ne zaman önerirsin?",weak:"Ortalama her zaman yeterlidir, medyan daha karmaşık.",strong:"Dağılım çarpık olduğunda ve birkaç uç değer ortalamayı yukarı çektiğinde. Çözüm süresi tipik olarak böyledir: taleplerin çoğu birkaç saatte çözülür, birkaçı günler sürer. Bu modelde 2024 için `[Ortalama Çözüm (saat)]` yaklaşık 22,0 saat, `MEDIAN(Talepler[CozumSaat])` ise yaklaşık 14,4 saattir; yani tipik bir müşteri ortalamanın söylediğinden çok daha hızlı cevap alıyor. Yalnızca ortalamaya bakan bir ekip, birkaç uzun talebi çözünce “büyük iyileşme” görebilir. Ben ikisini birlikte gösteririm: medyan tipik deneyimi, yüksek bir yüzdelik (ör. 90. yüzdelik, `PERCENTILE.INC`) ise en kötü deneyimi anlatır. Ortalama, toplam iş yükünü planlarken (toplam saat ve kapasite hesabı) hâlâ doğru ölçüdür. Hangi istatistiğin hangi soruya cevap verdiğini KPI tanımına yazarım.",why:"Çarpık dağılımı modelden hesaplanmış sayılarla gösteriyor, medyan ve yüzdeliği farklı sorulara eşliyor ve ortalamanın hâlâ doğru olduğu durumu da söylüyor.",follow:"Medyanı aylık bir trend grafiğinde gösterirken talep sayısı çok az olan aylarda nelere dikkat edersin?"},{id:"iv-b096",role:"hepsi",cat:"Kavram",q:"Bir sunumda “Hediye kategorisi geçen yıl %184 büyüdü” yazıyor. Bu cümleyi nasıl değerlendirirsin?",weak:"Büyük bir başarı. Hediye kategorisine yatırımı artırmayı öneririm.",strong:"Yüzde değişim küçük bir tabanda yanıltıcıdır. Bu modelde Hediye’nin net satışı 2022’de 2.000 ₺, 2023’te 5.670 ₺; büyüme gerçekten yaklaşık %184 ama 2023’te yalnızca 13 sipariş var. Tutar olarak artış 3.670 ₺, yani Elektronik gibi bir kategoride tek bir haftanın dalgalanmasından bile küçük. Ayrıca 2022 yalnızca yarım yıl olduğu için karşılaştırma zaten adil değildir. Ben böyle bir cümleyi üç şekilde düzeltirim: yüzdeyi mutlak tutarla birlikte vermek (“+3.670 ₺, +%184”), toplam içindeki payı göstermek ve sipariş sayısı çok düşükse yorumun güvenilmez olduğunu belirtmek. Karşılaştırma dönemi eksikse tam yılları ya da aynı ayları karşılaştırırım. Görselde de küçük kategorilerin büyüme oranlarını büyüklere göre sıralamak, en küçüğü en üste taşıyıp yanlış öncelik yaratır.",why:"Taban etkisini, örneklem büyüklüğünü ve eksik dönem sorununu modelden hesaplanmış sayılarla gösteriyor ve sunumda nasıl doğru ifade edileceğini anlatıyor.",follow:"Büyüme oranlarını sıralayan bir grafikte küçük kategorilerin yanıltıcı biçimde öne çıkmasını nasıl önlersin?"},{id:"iv-b097",role:"hepsi",cat:"Güvenlik ve yönetişim",q:"Bir rapor talebinde müşteri adı, telefonu ve adresi de isteniyor. Kişisel verilerin korunması açısından nasıl yaklaşırsın?",weak:"Talep eden kişi yetkiliyse tüm alanları eklerim.",strong:"İlk sorum amaçtır: bu alanlar raporun cevap vereceği karar için gerekli mi? Çoğu analiz (segment performansı, şehir bazında satış, kohort) kişiyi tanımlamadan yapılabilir; `Musteriler[Segment]`, `Sehir`, `YasGrubu` yeterlidir. Kişi düzeyi bir liste gerçekten gerekiyorsa (ör. müşteri temsilcisinin arama listesi), yalnızca o işi yapanların göreceği ayrı bir rapor ya da sayfa yapar, RLS ile her temsilciye yalnızca kendi müşterilerini gösteririm. Telefon ve adres gibi alanları genel modelden çıkarır, gerekiyorsa ayrı ve dar yetkili bir modelde tutarım. Hassasiyet etiketi uygular, dışa aktarmayı bu rapor için kısıtlamayı değerlendiririm. Kararı tek başıma vermem; veri sahibine ve gerekiyorsa kişisel veri sorumlusuna danışır, gerekçeyi kayda geçiririm. “Belki lazım olur” diye kişisel veri taşımak en sık yapılan hatadır.",why:"Amaçla sınırlama ve en aza indirme ilkelerini uyguluyor, gerçek ihtiyaç için dar ve güvenli bir çözüm kuruyor ve kararı doğru kişilerle veriyor.",follow:"Küçük bir şehirde yalnızca üç müşteri varsa, ad göstermeyen bir rapor yine de kişiyi tanımlanabilir kılar mı?"},{id:"iv-b098",role:"hepsi",cat:"Güvenlik ve yönetişim",q:"Denetim ekibi, gizli bir raporu son üç ayda kimlerin açtığını ve dışa aktardığını soruyor. Bu bilgiye nasıl ulaşırsın?",weak:"Raporun kullanım ölçümlerinde herkesin adı görünür, oradan bakarım.",strong:"Kullanım ölçümleri raporu, görüntüleme eğilimlerini gösterir ama denetim amacı için yeterli ayrıntıyı ve saklama süresini her zaman sağlamaz. Asıl kaynak etkinlik ve denetim günlükleridir: Power BI ve Fabric işlemleri (rapor görüntüleme, dışa aktarma, paylaşım, izin değişikliği) Microsoft Purview denetim günlüğüne kaydedilir; yetkili bir yönetici kullanıcı, tarih aralığı ve işlem türüne göre arama yapabilir. Yöneticiler için etkinlik olaylarını getiren API’ler de vardır; bunlar düzenli çekilip kendi saklama alanında tutulursa uzun dönem analiz mümkün olur. Ayrıca kiracı yöneticileri için sunulan yönetici izleme çalışma alanı hazır raporlar içerir. Ben bu işi kendim çekmem; yetkili yöneticiyle birlikte yaparım, çünkü denetim günlüğü de hassas veridir. Sonrası için gizli raporlar için etkinlik günlüğünü düzenli toplayan bir süreç ve dışa aktarma için hassasiyet etiketi kuralları öneririm.",why:"Kullanım ölçümleri ile denetim günlüğünün farkını biliyor, doğru kaynakları ve saklama sorununu açıklıyor ve yetki sınırına saygı gösteriyor.",follow:"Dışa aktarılan bir dosyanın daha sonra kime gönderildiğini izlemek mümkün mü? Hangi koşulda?"},{id:"iv-b099",role:"hepsi",cat:"Rapor ve görselleştirme",q:"Yönetim kurulu sunumu için hazırlanan bir rapor ile analistlerin kullandığı keşif raporu arasında tasarım farkı ne olmalı?",weak:"İkisi de aynı olabilir. Yönetim kuruluna sadece daha az sayfa gösteririm.",strong:"Keşif raporu soruyu kullanıcının sormasına izin verir: çok sayıda dilimleyici, detaylandırma, tablolar, esnek kırılımlar. Yönetim kurulu raporu ise bir sonucu iletir; okuyucu soruyu değil cevabı bekler. Bu yüzden yönetim kurulu sayfasında her görselin başlığı bir bulgudur (“2024’te hedefin %2,1 altında kaldık, açığın çoğu Ç2’de”), soru değil. Az sayıda, karşılaştırmalı KPI ve bir ana görsel olur; dilimleyiciler sabitlenir ya da kaldırılır, çünkü sunumda rakamın değişmesi istenmez. Vurgu rengi yalnızca ana mesaja verilir, diğer her şey nötr kalır. Notlar ve kaynak açıklaması küçük ama görünür yazılır. Keşif raporunda ise tutarlı adlandırma, hızlı filtreleme ve ayrıntıya erişim önceliklidir. İkisi aynı modeli kullanır ki sunulan rakam ile analistin bulduğu rakam aynı olsun.",why:"İki raporun amacını (keşif ve iletişim) ayırıyor, buna göre başlık, etkileşim, renk ve içerik farklarını somut veriyor ve tek model ilkesini koruyor.",follow:"Yönetim kurulu üyeleri sunumdan sonra raporu kendileri açıp filtrelemek isterse ne yaparsın?"},{id:"iv-b100",role:"hepsi",cat:"Rapor ve görselleştirme",q:"Bir meslektaşın grafiğinde aylık satış artışı çok dramatik görünüyor, ama rakamlara bakınca küçük bir değişim. Hangi görsel tercihler yanıltıcı olabilir?",weak:"Grafik doğru veriyi gösteriyorsa yanıltıcı değildir.",strong:"Veri doğru olsa bile sunum yanıltabilir. En sık sebep, sütun ya da çubuk grafiğinde değer ekseninin sıfırdan başlamamasıdır; %3’lük bir fark üç kat gibi görünür. Çubuklarda eksen sıfırdan başlamalıdır, çünkü göz uzunluğu karşılaştırır; çizgi grafikte ise eğilime odaklanıldığı için eksen daraltılabilir ama bu açıkça belirtilmelidir. Diğer tuzaklar: farklı ölçekte iki ekseni aynı grafikte üst üste bindirip sahte bir ilişki göstermek; eksik bir son ayı tam ay gibi göstermek (son ayın düşüşü aslında yarım ay); kümülatif bir seriyi büyüme gibi sunmak; birimleri (bin, milyon) başlıkta yazmamak; yüzdeyi ve yüzde puanı karıştırmak. Meslektaşıma bunu bir kural listesi olarak değil, aynı veriyi iki farklı eksenle yan yana göstererek anlatırım; fark kendini gösterir. Ekip temasına “değer ekseni sıfırdan başlar” gibi kuralları ekleriz.",why:"Eksen, çift eksen, eksik dönem ve birim gibi yaygın yanıltma yollarını sayıyor, grafik türüne göre doğru kuralı veriyor ve ikna edici bir geri bildirim yöntemi öneriyor.",follow:"Ayın ortasında yayımlanan bir raporda son ayın “düşüş” gibi görünmesini nasıl önlersin?"}),W.PBI_IV_STAR.push({id:"st-9",q:"Çok kısa sürede çözmen gereken bir “yanlış rakam” kriziyle karşılaştığın bir zamanı anlatır mısın?",aim:"Baskı altında sakin kalma, sorunu hızla daraltma, karar vericiye net bir durum bilgisi verme.",S:"Çeyrek kapanış toplantısına üç saat kala finans direktörü, sunumdaki faaliyet giderinin muhasebe kapanışından yaklaşık %6 yüksek olduğunu bildirdi; sunum CEO’ya gidecekti.",T:"Farkın kaynağını bulmak ve toplantıya hangi rakamla girileceği konusunda direktöre güvenilir bir öneri sunmak benim sorumluluğumdaydı, çünkü gider modelini ben kurmuştum.",A:"Önce farkı gider türü ve ay kırılımında iki tarafın rakamını yan yana koyan bir tablo hazırladım; on beş dakikada farkın tamamının tek bir gider türünde ve son ayda olduğunu gördüm. Kaynak dosyayı incelediğimde son ayın kira tahakkukunun hem tahmini hem kesin kayıt olarak iki kez yüklendiğini buldum. Modelde mükerrer kaydı dışarıda bırakan geçici bir filtre ekledim, sonucu muhasebe rakamıyla kuruşu kuruşuna eşleştirdim ve direktöre farkın sebebini, düzeltilmiş rakamı ve geçici çözümün ne olduğunu iki paragrafta yazdım. Toplantıdan sonra kaynak ekibiyle mükerrer yüklemeyi kaynağında düzelttik ve geçici filtreyi kaldırdım.",R:"Sunum doğru rakamla, zamanında yapıldı. Yükleme sürecine “aynı belge numarası iki kez gelirse uyar” kontrolünü ekledik; sonraki dört kapanışta benzer bir fark çıkmadı.",tip:"Krizde ne kadar hızlı çalıştığını değil, sorunu nasıl daralttığını ve karar vericiye ne kadar net bilgi verdiğini anlat. Geçici çözümü kalıcı çözümden ayırdığını mutlaka belirt."},{id:"st-10",q:"Verdiğin bir teslim tarihini kaçırdığın bir zamanı anlatır mısın?",aim:"Gecikmeyi dürüstçe sahiplenme, erken haber verme, etkiyi azaltma ve tahmin etme becerisini geliştirme.",S:"Satış ekibi için yeni bir müşteri kârlılık raporunu iki haftada teslim edeceğimi söylemiştim; ikinci haftanın başında maliyet verisinin müşteri düzeyinde değil yalnızca ürün düzeyinde geldiğini fark ettim.",T:"Söz verdiğim tarihin gerçekçi olmadığını kabul etmem, paydaşı zamanında bilgilendirmem ve gecikmenin etkisini en aza indirmem gerekiyordu.",A:"Sorunu fark ettiğim gün satış müdürüne yazdım: neyin eksik olduğunu, bunun neden kârlılığı müşteri bazında hesaplamayı zorlaştırdığını ve üç seçeneği açıkladım. Seçenekler, ürün düzeyinde maliyetle yaklaşık bir müşteri kârlılığını tarihinde teslim etmek, finansla dağıtım anahtarını belirleyip bir hafta geç teslim etmek ya da ikisini aşamalı yapmaktı. Müdür aşamalı yolu seçti. İlk aşamayı tarihinde, rapora “yaklaşık maliyet” notuyla teslim ettim; ikinci aşama için finansla dağıtım kuralını yazılı hâle getirdik ve raporu bir hafta sonra güncelledim.",R:"Satış ekibi ilk aşamayla haftalık toplantısını yapabildi; tam rapor söz verdiğim yeni tarihte teslim edildi. Bu deneyimden sonra tahmin yaparken veri kaynaklarını ilk iki gün içinde doğrulamayı ve ilk tahmine bir tampon eklemeyi kural hâline getirdim.",tip:"Gecikmeyi başkasına yükleme; neyi geç fark ettiğini ve bundan ne öğrendiğini söyle. Hikâyenin ağırlığı erken iletişimde ve sunduğun seçeneklerde olsun."},{id:"st-11",q:"Proje ortasında gereksinimlerin değiştiği bir zamanı anlatır mısın?",aim:"Kapsam değişikliğini yönetme, etkiyi görünür kılma ve değişikliği kontrollü biçimde kabul etme.",S:"Bir bölge performans panosunun geliştirmesinin yarısındayken iş birimi, bölgelerin yeniden düzenlendiğini ve raporun hem eski hem yeni bölge yapısına göre çalışması gerektiğini söyledi.",T:"Değişikliğin teslim tarihine ve modele etkisini ortaya koymam, iş birimiyle neyin şimdi neyin sonra yapılacağını belirlemem gerekiyordu.",A:"Önce değişikliğin teknik etkisini çıkardım: müşteri tablosunda tarih aralıklı bir bölge eşleme tablosu gerekiyordu ve bu, mevcut ölçülerin bir kısmını etkiliyordu. İş birimine bir sayfalık bir not hazırladım: değişikliğin ek iş süresi, teslim tarihine etkisi ve iki seçenek (eski yapıyla zamanında teslim, ardından yeni yapı; ya da her ikisiyle bir hafta geç). Ayrıca “hangi raporda hangi bölge yapısı kullanılacak” sorusunu karar olarak yazdırdım. İş birimi ilk seçeneği seçti. Eski yapıyla teslim ettim, ardından eşleme tablosunu ekleyip kullanıcıya iki yapı arasında seçim yapabileceği bir dilimleyici sundum.",R:"İlk teslim tarihinde yapıldı, yeni yapı on gün sonra devreye girdi ve yeniden düzenleme toplantılarında iki yapı yan yana karşılaştırılabildi. Ekip, kapsam değişikliklerini bu tek sayfalık etki notuyla değerlendirmeyi standart hâline getirdi.",tip:"Değişikliğe direndiğini değil, etkisini görünür kılıp kararı iş tarafına bıraktığını anlat. Yazılı karar ve sonraki süreç iyileştirmesi hikâyeyi güçlendirir."},{id:"st-12",q:"Kritik bir dönemde yaşanan bir performans ya da yenileme kriziyle nasıl başa çıktığını anlatır mısın?",aim:"Üretim sorununda önceliklendirme, geçici ve kalıcı çözümü ayırma, kök neden analizi.",S:"Ay sonu kapanış haftasında finans modelinin sabah yenilemesi bellek hatasıyla iki gün üst üste başarısız oldu; kapanış raporları bir önceki günün verisini gösteriyordu ve finans ekibi her sabah bu rakamlarla çalışıyordu.",T:"Kapanış sürerken raporları güncel tutmanın bir yolunu bulmam ve sorunun tekrarlamamasını sağlamam gerekiyordu.",A:"Önce finans ekibine durumu ve raporlardaki veri tarihini bildirdim; rapora görünür bir “veri tarihi” kartı ekledim. Geçici çözüm olarak modeli tablo tablo yenileyen bir betik çalıştırdım; tam yenilemenin aynı anda istediği belleği böylece böldüm ve aynı sabah güncel veriye ulaştık. Kök nedeni ararken bir kaynak tablonun son ayda iki katına çıktığını ve bir hesaplanmış sütunun yüksek kardinaliteli bir metin ürettiğini gördüm. Sütunu kaynağa taşıdım, büyük olgu tablosu için artımlı yenileme kurdum ve aynı saatte çalışan iki başka yenilemenin saatini kaydırdım.",R:"Kapanış haftasının geri kalanında yenileme her sabah başarılı oldu; model boyutu belirgin şekilde küçüldü ve yenileme süresi kısaldı. Kapasite ölçümleri için haftalık bir kontrol listesi oluşturduk.",tip:"Önce kullanıcıyı korumak için ne yaptığını, sonra kök nedeni nasıl bulduğunu anlat. Geçici çözümün neden geçici olduğunu ve kalıcı çözümün ne getirdiğini ayırt et."},{id:"st-13",q:"Bir ekibe ya da kişiye teknik bir konuyu öğrettiğin bir zamanı anlatır mısın?",aim:"Bilgiyi aktarma, dinleyiciye göre uyarlama ve öğrenmenin kalıcı olmasını sağlama.",S:"Pazarlama ekibinden altı kişi paylaşılan satış modelini kullanmaya başlamıştı ama sürekli ham tutar sütununu toplayıp iptalleri de içeren rakamlar üretiyor, bunlar yönetim toplantılarında tartışma yaratıyordu.",T:"Ekibin modeli doğru kullanmasını sağlamam ve bana gelen soru sayısını azaltmam gerekiyordu.",A:"Genel bir Power BI eğitimi yerine ekibin en sık sorduğu üç soruyu topladım ve her biri için kırk beş dakikalık uygulamalı bir oturum hazırladım. İlk oturumda yalnızca iki kavramı anlattım: hangi ölçüyü kullanmalılar ve hangi alanla kırılım yapmalılar. Herkes kendi bilgisayarında aynı soruyu cevapladı. Modelde ham sütunları gizledim, ölçülere açıklama ekledim ve bir sayfalık bir başvuru kılavuzu hazırladım. Ekipten istekli bir kişiyi yetkin kullanıcı olarak seçip ona biraz daha derin bir oturum verdim ki ilk sorular ona gitsin.",R:"Bir ay içinde bana gelen soru sayısı yarıdan fazla azaldı ve yönetim toplantılarında pazarlama rakamlarıyla ilgili tanım tartışması bitti. Yetkin kullanıcı daha sonra kendi ekibine yeni gelenlerin eğitimini üstlendi.",tip:"Ne kadar çok konu anlattığını değil, öğrenmenin kalıcı olması için neyi değiştirdiğini (model, kılavuz, yetkin kullanıcı) anlat. Sonucu ölçülebilir bir değişimle bitir."},{id:"st-14",q:"Yeni talepler ile teknik borcu azaltmak arasında öncelik kurmak zorunda kaldığın bir zamanı anlatır mısın?",aim:"Görünmeyen işin değerini iş diline çevirme, yöneticiyi ikna etme ve dengeli bir plan kurma.",S:"Ekip sürekli yeni rapor talepleriyle meşguldü; bu arada ana satış modeli çok büyümüş, yenilemesi uzamış ve her yeni ölçü eklemek giderek riskli hâle gelmişti. Yöneticim yeni taleplere öncelik veriyordu.",T:"Model düzenlemesinin neden gerekli olduğunu yöneticime anlatmam ve yeni talepleri durdurmadan bunun için zaman ayırmam gerekiyordu.",A:"Sorunu teknik terimlerle değil sonuçlarıyla anlattım: son üç ayda yenileme süresinin nasıl uzadığını, iki yenileme hatasının kaç kullanıcıyı etkilediğini ve son beş ölçü değişikliğinden ikisinin başka raporları bozduğunu bir tabloyla gösterdim. Düzenlemeyi tek seferlik büyük bir proje yerine her sprintte kapasitenin yaklaşık beşte birini ayıracağımız küçük adımlara böldüm ve her adımın ölçülebilir hedefini yazdım (kullanılmayan sütunları kaldırmak, ölçü açıklamaları, test sorguları). Yöneticim bu planı onayladı; yeni talepleri de iş etkisine göre sıralayan bir liste oluşturduk.",R:"Üç ay içinde yenileme süresi belirgin şekilde kısaldı, model boyutu azaldı ve bu süreçte hiçbir ölçü değişikliği başka bir raporu bozmadı. Yeni talepler de durmadı, yalnızca daha öngörülebilir bir sırayla ilerledi.",tip:"Teknik borcu yöneticinin önemsediği sonuçlarla (kesinti, risk, hız) anlat. Her şeyi durdurmak yerine dengeli ve ölçülebilir bir plan önerdiğini göster."},{id:"st-15",q:"Verdiğin bir teknik kararın ya da önerinin yanlış çıktığı bir zamanı anlatır mısın?",aim:"Hatayı kabul etme, kararı veriye dayanarak geri çevirme ve karar alma sürecini iyileştirme.",S:"Stok raporu için “verinin her zaman güncel olması” isteniyordu ve ben modelin DirectQuery ile kurulmasını önermiştim. Canlıya çıktıktan sonra sayfalar on beş yirmi saniyede açılmaya başladı ve depo ekibi raporu kullanmayı bıraktı.",T:"Önerimin sonuçlarını sahiplenmem, doğru çözümü bulmam ve ekibin güvenini geri kazanmam gerekiyordu.",A:"Depo ekibine sorunun benim tasarım tercihimden kaynaklandığını açıkça söyledim. Ardından “güncel” ihtiyacını yeniden konuştum; ekibin aslında saatlik güncellemenin yeterli olduğunu, saniyelik gecikmeye ihtiyaç duymadığını öğrendim. Ben ilk görüşmede bunu sormamıştım. Modeli Import’a çevirip saatlik yenileme kurdum, yalnızca anlık sevkiyat sayısı gereken tek bir sayfa için küçük bir DirectQuery tablosu bıraktım. Değişiklikten önce ve sonra sayfa sürelerini ölçüp ekiple paylaştım.",R:"Sayfalar iki üç saniyede açılmaya başladı ve rapor iki hafta içinde yeniden günlük kullanıma girdi. O günden beri gereksinim görüşmelerinde “güncel” kelimesini her zaman dakika ya da saat olarak yazılı hâle getiriyorum.",tip:"Hatayı küçümseme; neyi sormadığını ya da neyi varsaydığını açıkça söyle. Düzeltmeyi ölçümle göster ve bir alışkanlık değişikliğiyle bitir."},{id:"st-16",q:"Ekip içinde teknik bir konuda yaşadığın bir anlaşmazlığı anlatır mısın?",aim:"Farklı görüşleri dinleme, kararı ölçütlere bağlama ve ilişkiyi koruyarak ilerleme.",S:"Bir veri mühendisi meslektaşım, satış ve stok raporları için iki ayrı anlam modeli kurmayı öneriyordu; ben ise tek bir ortak model istiyordum. Tartışma iki toplantı boyunca sürdü ve ekip lideri karar vermemizi bekliyordu.",T:"Kişisel tercih tartışmasını bitirip ekip için doğru tasarım kararına ulaşmamız gerekiyordu.",A:"Meslektaşımla bire bir oturup önce onun gerekçelerini sonuna kadar dinledim: iki modelin bağımsız yenilenmesi ve stok tarafındaki büyük tablonun satış raporlarını yavaşlatmaması. Bunların haklı kaygılar olduğunu söyledim. Sonra kararı kişiler yerine ölçütlere bağlamayı önerdim: yenileme süresi, sorgu süresi, tanım tutarlılığı ve bakım maliyeti. İki yaklaşımı küçük bir prototiple ölçtük. Sonuçta ortak boyutları paylaşan ama iki ayrı model içeren bir yapıda birleştik; ortak ölçüleri tek bir yerde tanımlayıp iki modele dağıtan bir süreç kurduk.",R:"Karar bir hafta içinde verildi ve ekip lideri tarafından onaylandı. İki model bağımsız yenilenebildi, ortak ölçüler de iki modelde aynı sonucu verdi. Meslektaşımla daha sonra da birçok tasarımı aynı ölçüt tablosuyla değerlendirdik.",tip:"Kimin haklı çıktığını anlatma; karşı görüşün güçlü yanlarını kabul ettiğini ve kararı ölçütlere bağladığını göster. İlişkinin sonrasında nasıl sürdüğünü de ekle."}),W.PBI_IV_ASK.push({q:"İki departman aynı KPI için farklı rakam gösterdiğinde son kararı kim veriyor?",why:"Veri sahipliğinin net olup olmadığını ve rakam tartışmalarında kimin desteğine güveneceğini gösterir."},{q:"Ölçü ve model değişiklikleri üretime çıkmadan önce kim inceliyor? Kod incelemesi yapılıyor mu?",why:"Kalite güvencesi kültürünü ve bir hatanın üretime ne kolaylıkla sızabileceğini anlamanı sağlar."},{q:"Raporların ne kadarı merkezi ekipten, ne kadarı iş birimlerinin self-servis çalışmasından çıkıyor?",why:"Rolünün geliştirme mi, destek ve yönetişim mi ağırlıklı olacağını ve gölge BI’ın boyutunu gösterir."},{q:"Kapasite ve lisans kararlarını kim veriyor? Ekip maliyet kısıtlarını nasıl hissediyor?",why:"Teknik seçimlerinde (Import, Direct Lake, yenileme sıklığı) ne kadar özgür olacağını ve bütçe baskısını anlamanı sağlar."},{q:"Copilot ya da başka yapay zekâ araçlarının kullanımına dair bir politika var mı? Modeller yapay zekâ için hazırlanıyor mu?",why:"Kurumun yapay zekâya bakışını ve bu alanda üstleneceğin sorumluluğu (model hazırlığı, doğrulama) öğrenirsin."},{q:"Ay sonu ve çeyrek kapanışlarında ekibin iş yükü ve nöbet düzeni nasıl?",why:"Yoğun dönemlerin gerçekçi bir resmini verir; iş ve özel hayat dengesini önceden değerlendirmeni sağlar."}),Object.assign(W.PBI_IV_TAKEHOME,{tedarik:{title:"Ev ödevi: 2024 tedarikçi karnesi ve tedarik gecikmeleri",brief:"Aynı perakende şirketinin satın alma ekibi için BI analisti adayısın. Satın alma müdürü yıllık tedarikçi değerlendirme toplantısına hazırlanıyor ve hangi tedarikçilerle sözleşme koşullarını yeniden konuşacağına karar vermek istiyor. Veri, bu uygulamanın örnek modelidir: `SatinAlmalar` (sipariş satırları; Adet, BirimFiyat, Tutar, TeslimGun, Zamaninda, Kusurlu), `Tedarikciler` (Ulke, SozGun: sözleşmedeki teslim süresi), `Urunler`, `Kategoriler` ve `Tarih`. Modeldeki `[Satın Alma Tutarı]`, `[Ortalama Tedarik Süresi]`, `[Tedarikte Zamanında %]` ve `[Kusur Oranı %]` ölçülerini kullanabilirsin. Müdür üç soruya cevap arıyor: Hangi tedarikçiler gecikiyor ve gecikmeler ne kadar uzun? Kalite sorunu hangi tedarikçilerde yoğunlaşıyor ve bize maliyeti ne? Yurt içi ve yurt dışı tedarik arasında belirgin bir fark var mı? Senden 5–7 yeni ölçü, tek sayfalık bir tedarikçi karnesi taslağı ve en fazla beş maddelik bir bulgu özeti bekleniyor. Süre: 4 saat. Puanlama formülünü ve ağırlıklarını kendin belirle ve gerekçesini yaz; mülakatta 10 dakikada sunacaksın.",tasks:[{t:"Gecikme ölçüleri",detail:"Geciken siparişlerin oranı ve geciken siparişlerde sözleşme süresinin ortalama kaç gün aşıldığı. Sözleşme süresi `Tedarikciler` tablosunda; satır düzeyinde `RELATED` gerekecek."},{t:"Tedarik süresi",detail:"Basit ortalama tedarik süresinin yanında tutara göre ağırlıklandırılmış bir süre. İkisinin neden farklı çıktığını bir cümleyle açıkla."},{t:"Kalite ve maliyeti",detail:"Kusurlu ürünlerin tutar karşılığı. Kusur oranını satır oranlarının ortalaması olarak değil, toplam kusurlu adedin toplam adede oranı olarak yorumla."},{t:"Tedarikçi puanı",detail:"Zamanında teslim ve kalite oranlarını birleştiren 0–100 arası bir puan. Tedarikçi satırında anlamlı olmalı; satın alması olmayan satırlarda BLANK dönmeli."},{t:"Yurt içi payı",detail:"Türkiye’deki tedarikçilerin satın alma tutarındaki payı. Ülke kırılımında Çin satırında %100’ün üzerinde bir değer görmemelisin."},{t:"Karne ve bulgular",detail:"Tedarikçi başına tek satırlık bir karne tablosu (sıralı), bir dağılım grafiği (zamanında % ve kusur %) ve en fazla beş madde. Son madde hangi tedarikçiyle ne konuşulacağına dair somut bir öneri olmalı."}],rubric:[{c:"Ölçülerin doğruluğu",w:30,good:"Ölçüler tedarikçi, ülke ve kategori kırılımında doğru çalışır; `RELATED` ve satır bağlamı doğru kullanılır; oranlar toplamlardan hesaplanır, BLANK durumları yönetilir."},{c:"Model ve bağlam anlayışı",w:20,good:"`SatinAlmalar` ile `Satislar` arasında tedarikçi üzerinden bir ilişki olmadığını, ülke payında `KEEPFILTERS` gerektiğini ve tablo üretirken bağlam geçişinin nerede gerektiğini fark eder."},{c:"Puanlama yaklaşımı",w:15,good:"Puan formülü basit ve açıklanabilirdir; ağırlıklar iş gerekçesiyle savunulur; az siparişi olan tedarikçilerin puanının daha az güvenilir olduğu belirtilir."},{c:"Bulguların kalitesi",w:20,good:"Her bulgu bir sayı ve bir karşılaştırma içerir (geçen yıla, ortalamaya ya da sözleşmeye göre); gecikme oranı ile gecikme süresi ayrı yorumlanır; somut bir öneriyle biter."},{c:"Rapor tasarımı ve iletişim",w:15,good:"Karne tek bakışta okunur, renk yalnızca eşik aşımlarında kullanılır, varsayımlar (sözleşme süresi tanımı, puan ağırlıkları) yazılıdır ve sunum 10 dakikaya sığar."}],solution:{measures:[["Geciken Sipariş Oranı %",'DIVIDE(CALCULATE(COUNTROWS(SatinAlmalar), SatinAlmalar[Zamaninda] = "Hayır"), COUNTROWS(SatinAlmalar))'],["Ortalama Aşım Günü",`AVERAGEX(
  FILTER(SatinAlmalar, SatinAlmalar[TeslimGun] > RELATED(Tedarikciler[SozGun])),
  SatinAlmalar[TeslimGun] - RELATED(Tedarikciler[SozGun])
)`],["Tutar Ağırlıklı Tedarik Süresi","DIVIDE(SUMX(SatinAlmalar, SatinAlmalar[TeslimGun] * SatinAlmalar[Tutar]), [Satın Alma Tutarı])"],["Kusurlu Ürün Tutarı","SUMX(SatinAlmalar, SatinAlmalar[Kusurlu] * SatinAlmalar[BirimFiyat])"],["Tedarikçi Puanı",`IF(
  NOT ISBLANK([Satın Alma Tutarı]),
  100 * (0.6 * [Tedarikte Zamanında %] + 0.4 * (1 - [Kusur Oranı %]))
)`],["Yerli Tedarik Payı %",'DIVIDE(CALCULATE([Satın Alma Tutarı], KEEPFILTERS(Tedarikciler[Ulke] = "Türkiye")), [Satın Alma Tutarı])'],["Satın Alma Büyümesi %",`VAR GY = CALCULATE([Satın Alma Tutarı], SAMEPERIODLASTYEAR(Tarih[Tarih]))
RETURN IF(NOT ISBLANK(GY), DIVIDE([Satın Alma Tutarı] - GY, GY))`]],story:`• Hacim: 2024’te 138 satın alma siparişiyle 478.455 ₺ alım yapıldı; 2023’e göre +%56,1.
• Gecikme: Siparişlerin %28,3’ü sözleşme süresinden geç geldi (2023’te %27,5). En kötü Lumière Kozmetik (%47,1) ve Shenzhen Link Co. (%40,0), en iyi Anka Yayın Dağıtım (%10,7). Ancak gecikmeler kısa: geciken siparişlerde sözleşme süresi ortalama 1,3 gün aşılıyor. Sorun büyük gecikmeler değil, sık ve küçük gecikmeler.
• Süre: Tutara göre ağırlıklı tedarik süresi 7,7 gün, basit ortalama 7,3 gün; pahalı siparişler daha uzun sürede geliyor. Shenzhen’de ortalama süre 19,8 gün, Lumière’de 14,1 gün.
• Kalite: Toplam kusur oranı %3,8; Shenzhen’de %11,8, Atlas Spor’da %8,3. Kusurlu ürünlerin tutar karşılığı 21.950 ₺; en büyük kalemler Shenzhen (4.764 ₺) ve Marmara Ev Gereçleri (4.292 ₺).
• Karne ve öneri: Puan (0,6 × zamanında + 0,4 × kalite) en yüksek Anka’da (93,0), en düşük Lumière (70,7) ve Shenzhen’de (71,3). Shenzhen hem gecikme hem kalitede zayıf ve alımların %9,4’ünü oluşturuyor; öncelikli görüşme konusu kabul kontrolü ve kusur iadesi koşulları olmalı. Lumière’de kalite iyi (%2,7) ama gecikme yüksek; sözleşme süresinin gerçekçi olup olmadığı birlikte gözden geçirilmeli. Yerli tedarik payı %78,3 (2023’te %80,0).`},pitfalls:['Karne tablosunu `ADDCOLUMNS(VALUES(Tedarikciler[Tedarikci]), "N", COUNTROWS(SatinAlmalar))` ile kurmak: `COUNTROWS` bağlam geçişi olmadan çalıştığı için her tedarikçide 2024’ün toplamı (138) görünür. Ölçü ya da `CALCULATE(COUNTROWS(SatinAlmalar))` kullanılmalı.',"Yerli payı `KEEPFILTERS` olmadan yazmak: ülke kırılımında Türkiye filtresi Çin satırının filtresini ezer ve Çin satırında %836, Fransa satırında %636 gibi anlamsız oranlar çıkar.","Tedarikçi kırılımında alımı `[Net Maliyet]` ile oranlamak: `Satislar` tedarikçiye bağlı olmadığı için payda her satırda şirket toplamıdır ve oran tedarikçi bazında anlamsızlaşır.","Zamanında teslim oranını tedarikçi oranlarının basit ortalaması olarak sunmak: sekiz tedarikçinin ortalaması %70,6, sipariş bazında gerçek oran %71,7; az siparişi olan tedarikçi (Hediyelik Atölye, 4 sipariş) ortalamayı orantısız etkiler.","Kusur oranını satır başına oranların ortalaması (`AVERAGEX(SatinAlmalar, DIVIDE(Kusurlu, Adet))`) olarak hesaplamak: 2024 için %4,2 çıkar, adet ağırlıklı doğru oran %3,8’dir."]},butce:{title:"Ev ödevi: 2024 gider bütçesi sapma analizi",brief:"Aynı şirketin finans ekibi (FP&A) için BI analisti adayısın. Finans direktörü 2025 bütçe görüşmelerinden önce 2024 giderlerinin bütçeye göre nasıl gerçekleştiğini ve faaliyet kârlılığının nasıl değiştiğini görmek istiyor. Veri, bu uygulamanın örnek modelidir: `Giderler` (ay, gider türü ve departman düzeyinde gerçekleşen gider), `GiderButce` (ay ve gider türü düzeyinde bütçe; departman sütunu yok), `GiderTurleri` (Grup ve sorumlu DepartmanNo), `Departmanlar`, `Tarih` ve satış tarafı için `Satislar`. Modeldeki `[Gider]`, `[Gider Bütçe]`, `[Gider Sapma %]`, `[Faaliyet Kârı]` ve `[Faaliyet Kâr Marjı %]` ölçülerini kullanabilirsin. Direktör üç soruya cevap arıyor: Bütçeyi aştık mı, aştıysak hangi gider türleri ve hangi aylar yüzünden? Hangi departmanlar kendi sorumlu oldukları bütçeyi aştı? Gider yapısı ve faaliyet kâr marjı geçen yıla göre nasıl değişti? Senden 5–7 yeni ölçü, tek sayfalık bir sapma raporu taslağı ve en fazla beş maddelik bir bulgu özeti bekleniyor. Süre: 4 saat. Bütçenin departmana nasıl bağlandığına dair varsayımını yazılı olarak belirt.",tasks:[{t:"Bütçe sapması",detail:"Yılbaşından bugüne gerçekleşen gider ile bütçe farkı ve dönem içinde bütçenin aşıldığı ay sayısı. Ay kırılımında da çalışmalı."},{t:"Departman bütçesi",detail:"`GiderButce` tablosunda departman yok. Her gider türünün sorumlu departmanını kullanarak departman kırılımında anlamlı bir bütçe ve sapma üret; ilişki eklemeden çöz."},{t:"Gider yapısı",detail:"Her gider türünün toplam gider içindeki payı ve personel giderinin net satışa oranı."},{t:"Kârlılık değişimi",detail:"Faaliyet kâr marjının geçen yıla göre kaç puan değiştiği. Yüzde değişim ile puan farkını karıştırma."},{t:"Sapma raporu taslağı",detail:"Üstte gider, bütçe ve sapma kartları; ortada aylık gider ve bütçe (ya da kümülatif sapma) grafiği; altta gider türü ve departman sapma tablosu. Bir şelale grafiği kullanacaksan neyi gösterdiğini bir cümleyle açıkla."},{t:"Bulgu özeti ve öneri",detail:"En fazla beş madde; her madde bir tutar, bir oran ve bir “bu yüzden” içermeli. Son madde 2025 bütçesi için somut bir öneri olmalı."}],rubric:[{c:"Ölçülerin doğruluğu",w:30,good:"Ölçüler ay, gider türü ve departman kırılımında doğru çalışır; YTD ölçüleri ay düzeyinde birikir; oranlar ve puan farkları doğru hesaplanır."},{c:"Model ve ayrıntı düzeyi",w:25,good:"Bütçenin departman düzeyinde olmadığını fark eder, `TREATAS` ile sorumlu departmana bağlar, bunun bir varsayım olduğunu yazar ve gider türü kırılımında `[Faaliyet Kârı]`nın anlamsızlaştığını görür."},{c:"Bulguların kalitesi",w:20,good:"Sapmanın kaynağını tür, departman ve zaman boyutunda ayrıştırır; küçük toplam sapmanın içinde büyük bir kalem sapması olduğunu gösterir; somut bir öneriyle biter."},{c:"Rapor tasarımı",w:10,good:"Sapmalar işaretiyle tutarlı renklendirilir (aşım ve tasarruf ayrımı), eksenler ve birimler açıktır, sayfa yukarıdan aşağıya okunur."},{c:"Varsayımlar ve iletişim",w:15,good:"Departman bütçesi varsayımı, 2022’nin yarım yıl olması ve puan ile yüzde farkı yazılıdır; sunum 10 dakikaya sığar."}],solution:{measures:[["Gider YTD Sapma","TOTALYTD([Gider], Tarih[Tarih]) - TOTALYTD([Gider Bütçe], Tarih[Tarih])"],["Bütçe Aşan Ay","COUNTROWS(FILTER(VALUES(Tarih[YilAy]), [Gider] > [Gider Bütçe]))"],["Sorumlu Departman Bütçesi","CALCULATE([Gider Bütçe], TREATAS(VALUES(Departmanlar[DepartmanNo]), GiderTurleri[DepartmanNo]))"],["Departman Sapması","[Gider] - CALCULATE([Gider Bütçe], TREATAS(VALUES(Departmanlar[DepartmanNo]), GiderTurleri[DepartmanNo]))"],["Gider Türü Payı %","DIVIDE([Gider], CALCULATE([Gider], ALL(GiderTurleri)))"],["Personel Gideri / Satış %",'DIVIDE(CALCULATE([Gider], GiderTurleri[Grup] = "Personel"), [Net Satış])'],["Faaliyet Marjı Değişimi (puan)",`VAR GY = CALCULATE([Faaliyet Kâr Marjı %], SAMEPERIODLASTYEAR(Tarih[Tarih]))
RETURN IF(NOT ISBLANK(GY), [Faaliyet Kâr Marjı %] - GY)`]],story:`• Toplam: 2024 gideri 171.559 ₺ ile bütçeyi (169.027 ₺) 2.532 ₺ (%1,5) aştı; 2023’te aşım %2,8 idi. Toplam sapma küçük görünse de tek bir kalemde yoğunlaşıyor.
• Gider türü: Aşımın tamamından fazlası Pazarlama ve reklamdan geliyor (+3.906 ₺, +%8,8). Diğer türler bütçede ya da altında: Personel −795 ₺ (−%1,0), Genel yönetim −476 ₺ (−%5,3), Teknoloji −129 ₺ (−%1,3), Lojistik +26 ₺, Kira tam bütçede.
• Zamanlama: 12 ayın 7’sinde bütçe aşıldı. Kümülatif sapma Eylül sonunda 628 ₺ iken yıl sonunda 2.532 ₺’ye çıktı; aşımın büyük kısmı Kasım (+745 ₺) ve Aralık’ta (+1.415 ₺) oluştu.
• Departman (gider türünün sorumlu departmanına göre): Pazarlama +3.906 ₺ aştı; Satış −769 ₺, Genel Müdürlük −476 ₺, Yazılım −129 ₺ bütçenin altında kaldı.
• Kârlılık ve öneri: Giderin net satışa oranı %30,4’ten %23,0’a indi; faaliyet kâr marjı %1,5’ten %15,7’ye çıktı (+14,2 puan). Personel gideri / satış %13,7’den %10,4’e geriledi. 2025 için pazarlama bütçesi kampanya takvimine göre aylara dağıtılmalı ve Ç4 harcamaları ayrı bir onay eşiğine bağlanmalı; aksi hâlde yıl sonu aşımı tekrarlanır.`},pitfalls:["Departman kırılımında `[Gider Bütçe]`yi doğrudan kullanmak: `GiderButce` departmana bağlı olmadığı için her departman satırında toplam bütçe (169.027 ₺) görünür ve tüm departmanlar bütçenin çok altında görünür.","`[Faaliyet Kârı]`nı gider türü kırılımında göstermek: brüt kâr gider türüne göre filtrelenmez, her satırda tüm brüt kârdan yalnızca o türün gideri düşülür ve 211.059 ₺ ile 282.746 ₺ arasında anlamsız değerler çıkar.","Faaliyet kârındaki değişimi yüzde olarak sunmak: 2023’ün faaliyet kârı çok küçük (5.941 ₺) olduğu için değişim %1.870 gibi bir sayı verir; marjın puan farkı (+14,2 puan) çok daha anlamlıdır.","Aylık `[Gider Sapma %]` değerlerinin ortalamasını yıllık sapma diye sunmak: aylar eşit ağırlık alır; yıllık sapma toplamlardan hesaplanmalıdır (%1,5).","Departman bütçesi için `GiderTurleri` ile `Departmanlar` arasında fiziksel ilişki kurmak: `Giderler` zaten `Departmanlar`a bağlı olduğu için model iki yollu ve belirsiz hâle gelir; `TREATAS` filtreyi yalnızca ölçü içinde aktarır."]},destek:{title:"Ev ödevi: Müşteri hizmetleri yük ve memnuniyet değerlendirmesi",brief:"Aynı şirketin müşteri hizmetleri birimi için BI analisti adayısın. Birim müdürü 2025’te ek personel ve kanal yatırımı talep etmeden önce 2024’ün tablosunu görmek istiyor. Veri, bu uygulamanın örnek modelidir: `Talepler` (Tarih, MusteriNo, Kanal, Konu, Oncelik, IlkYanitDk, CozumSaat, Cozuldu, Memnuniyet 1–5; anket her talepte doldurulmamış), `Musteriler` (Segment), `Tarih` ve sipariş tarafı için `Satislar`. Modeldeki `[Talep Sayısı]`, `[Çözüm Oranı %]`, `[Ortalama İlk Yanıt (dk)]`, `[Ortalama Çözüm (saat)]`, `[CSAT %]` ve `[SLA Uyum %]` (ilk yanıt 60 dakika içinde) ölçülerini kullanabilirsin. Müdür üç soruya cevap arıyor: Talep yükü satışlarla orantılı mı artıyor? Hangi kanal ve konular SLA’yı ve memnuniyeti aşağı çekiyor? Teslimatla ilgili talepler toplam yükün ne kadarı? Senden 5–7 yeni ölçü, tek sayfalık bir operasyon raporu taslağı ve en fazla beş maddelik bir bulgu özeti bekleniyor. Süre: 4 saat. Memnuniyet anketine yanıt vermeyen talepleri nasıl ele aldığını yaz.",tasks:[{t:"Yük ve orantı",detail:"Sipariş başına talep sayısı ve çözülmeyen talep sayısı. Geçen yılla karşılaştır; talep artışını sipariş artışıyla birlikte yorumla."},{t:"Anket kapsamı",detail:"Memnuniyet anketinin doldurulma oranı. CSAT yorumunu bu oranla birlikte ver; boş anketleri 0 ya da düşük puan sayma."},{t:"Konu kırılımı",detail:"Kargo gecikmesi ve hasarlı ürün taleplerinin toplam içindeki payı. Konu kırılımında da anlamlı sonuç vermeli; diğer konularda %100 görmemelisin."},{t:"Öncelik ve hız",detail:"Yüksek öncelikli taleplerin SLA uyumu ve çözüm süresinin medyanı. Ortalama ile medyanın neden farklı çıktığını bir cümleyle açıkla."},{t:"Operasyon raporu taslağı",detail:"Üstte yük, hız ve memnuniyet kartları; ortada kanal bazında SLA ve CSAT karşılaştırması; altta konu bazında hacim ve çözüm süresi. Görsel seçimini bir cümleyle gerekçelendir."},{t:"Bulgu özeti ve öneri",detail:"En fazla beş madde; her madde bir sayı, bir karşılaştırma ve bir “bu yüzden” içermeli. Son madde yatırım talebine dair somut bir öneri olmalı."}],rubric:[{c:"Ölçülerin doğruluğu",w:30,good:"Ölçüler kanal, konu, öncelik ve segment kırılımında doğru çalışır; CSAT paydası yanıtlanmış anketlerdir; `KEEPFILTERS` gereken yerde kullanılır."},{c:"Model ve bağlam anlayışı",w:15,good:"`Talepler`in `Satislar` ile yalnızca `Musteriler` ve `Tarih` üzerinden bağlı olduğunu, ürün ya da kategori kırılımında talep ölçülerinin değişmediğini fark eder."},{c:"İstatistiksel yorum",w:20,good:"Ortalama ile medyanı ayırt eder, anket yanıt oranını yoruma katar, az talep olan kırılımlarda (ör. sosyal medya, hasarlı ürün) oranların oynak olduğunu belirtir."},{c:"Bulguların kalitesi",w:20,good:"SLA sorununun kanala özgü olduğunu sayıyla gösterir, yükü siparişle oranlar ve personel talebini veriye bağlayan somut bir öneri sunar."},{c:"Rapor tasarımı ve iletişim",w:15,good:"Kanal karşılaştırması tek bakışta okunur, SLA eşiği görselde çizgi olarak durur, varsayımlar yazılıdır ve sunum 10 dakikaya sığar."}],solution:{measures:[["Talep / Sipariş Oranı","DIVIDE([Talep Sayısı], [Sipariş Sayısı])"],["Çözülmeyen Talep",'CALCULATE([Talep Sayısı], Talepler[Cozuldu] = "Hayır")'],["Anket Yanıt Oranı %","DIVIDE(COUNT(Talepler[Memnuniyet]), [Talep Sayısı])"],["Teslimat Kaynaklı Talep %",`DIVIDE(
  CALCULATE([Talep Sayısı], KEEPFILTERS(Talepler[Konu] IN {"Kargo gecikmesi", "Hasarlı ürün"})),
  [Talep Sayısı]
)`],["Yüksek Öncelik SLA %",'CALCULATE([SLA Uyum %], KEEPFILTERS(Talepler[Oncelik] = "Yüksek"))'],["Medyan Çözüm (saat)","MEDIAN(Talepler[CozumSaat])"],["Talep Açan Müşteri %","DIVIDE(DISTINCTCOUNT(Talepler[MusteriNo]), COUNTROWS(Musteriler))"]],story:`• Yük: 2024’te 165 talep geldi (2023’te 105, +%57,1). Sipariş başına talep 0,37’den 0,33’e indi; yani talepler siparişlerden daha yavaş arttı. Kayıtlı 150 müşterinin 82’si (%54,7) en az bir talep açtı. Çözülmeyen talep 11 (2023’te 6); çözüm oranı %93,3.
• Hız ve SLA: Ortalama ilk yanıt 97,5 dakikadan 67,2 dakikaya indi, SLA uyumu %61,0’dan %65,5’e çıktı. Ama sorun kanala özgü: telefon ve canlı destekte SLA %100, e-postada %4,2 (ortalama ilk yanıt 184,6 dk), sosyal medyada %31,3. Yüksek öncelikli taleplerde SLA %72,7.
• Çözüm süresi: Ortalama 22,0 saat, medyan 14,4 saat; birkaç uzun talep ortalamayı yukarı çekiyor. En uzun konu İade ve değişim (ortalama 44,0 saat); aynı zamanda en kalabalık konu (46 talep) ve CSAT’ı en düşük konu (%64,3).
• Memnuniyet ve teslimat: CSAT %68,9’dan %75,8’e çıktı; anket yanıt oranı %60,0. Kurumsal segmentte CSAT %65,4 ile en düşük. Kargo gecikmesi ve hasarlı ürün talepleri yükün %28,5’i (2023’te %34,3).
• Öneri: Genel ek personelden önce e-posta kanalı için bir ilk yanıt hedefi ve otomatik ilk yanıt kurulmalı; SLA açığının neredeyse tamamı buradan geliyor. İade ve değişim süreci ayrı bir iyileştirme konusu olarak ele alınmalı; Kurumsal müşteriler için ayrıca bir memnuniyet incelemesi yapılmalı.`},pitfalls:["CSAT paydasında tüm talepleri kullanmak (`COUNTROWS(Talepler)`): anketi doldurulmamış talepler memnuniyetsiz sayılır ve 2024 CSAT’ı %75,8 yerine %45,5 çıkar.","SLA’yı ortalama ilk yanıta bakarak yorumlamak: toplam ortalama (67,2 dk) eşiğe yakın görünür, ama telefonda ortalama 5,5 dakika, e-postada 184,6 dakikadır; sorun dağılımda, ortalamada değil.","Konu payını `KEEPFILTERS` olmadan yazmak: konu kırılımında “Ödeme” gibi bir satırda filtre ezilir ve teslimat taleplerinin sayısı o konunun talebine bölünür.","Talep ölçülerini ürün ya da kategori kırılımında göstermek: `Talepler` ürüne bağlı olmadığı için her satırda aynı değer görünür; ürün düzeyinde analiz için talep konusunu ve müşteri bağlantısını kullanmak gerekir.","Power Query’de boş memnuniyet değerlerini 0 ile doldurmak: ortalama memnuniyet puanı ve CSAT anlamsız biçimde düşer; boş değer “yanıt yok” anlamında kalmalıdır."]}}),(function(){const G=(t,c)=>({t,c}),KAT=G("Kategoriler","Kategori"),YIL=G("Tarih","Yil"),AY=G("Tarih","YilAy"),CEYREK=G("Tarih","YilCeyrek"),SEG=G("Musteriler","Segment"),KANAL=G("Satislar","Kanal"),TED=G("Tedarikciler","Tedarikci"),TKANAL=G("Talepler","Kanal"),DEP=G("Departmanlar","Departman"),GTUR=G("GiderTurleri","GiderTuru"),d=(id,L,name,q,sol,o)=>Object.assign({id,L,t:"dax",name,q,sol},o||{});W.PBI_INTERVIEW.push(d("m-9","A","Geciken Satın Alma",'<b>Geciken Satın Alma</b>: zamanında teslim edilmeyen (<code>Zamaninda = "Hayır"</code>) satın alma siparişi satırlarının sayısı.','CALCULATE(COUNTROWS(SatinAlmalar), SatinAlmalar[Zamaninda] = "Hayır")',{grid:[TED,YIL,KAT],follow:"Takip: Bu sayıyı tedarikçiler arasında karşılaştırmak neden yanıltıcı olabilir? (Cevap: sipariş hacimleri farklı; oran olarak, yani toplam siparişe bölerek karşılaştırmak gerekir.)"}),d("m-10","A","Yüksek Öncelikli Talep",'<b>Yüksek Öncelikli Talep</b>: önceliği "Yüksek" olan müşteri hizmetleri talebi sayısı. Hazır <code>[Talep Sayısı]</code> ölçüsünü kullan.','CALCULATE([Talep Sayısı], Talepler[Oncelik] = "Yüksek")',{grid:[YIL,TKANAL],follow:"Takip: Bu ölçüyü bir öncelik dilimleyicisiyle birlikte kullanınca “Düşük” seçildiğinde ne görünür ve bunu nasıl değiştirirsin? (Cevap: filtre ezildiği için yine yüksek öncelikli talepler görünür; KEEPFILTERS ile seçim korunur ve sonuç boş olur.)"}),d("m-11","B","Bütçeyi Aşan Gider Türü","<b>Bütçeyi Aşan Gider Türü</b>: görünen dönemde gideri (<code>[Gider]</code>) bütçesinden (<code>[Gider Bütçe]</code>) büyük olan gider türü sayısı.","COUNTROWS(FILTER(VALUES(GiderTurleri[GiderTuru]), [Gider] > [Gider Bütçe]))",{grid:[YIL,CEYREK],follow:"Takip: Yıl satırındaki sayı neden çeyrek satırlarındaki sayıların toplamı değildir? (Cevap: her bağlamda türler o dönemin toplamına göre yeniden değerlendirilir; bir tür bir çeyrekte aşıp diğerinde altında kalabilir.)"}),d("m-12","B","Sözleşmeye Göre Teslim Farkı","<b>Sözleşmeye Göre Teslim Farkı</b>: satın alma satırlarında gerçekleşen teslim gününün (<code>TeslimGun</code>) tedarikçinin sözleşme gününden (<code>Tedarikciler[SozGun]</code>) farkının ortalaması. Negatif değer erken teslim demektir.","AVERAGEX(SatinAlmalar, SatinAlmalar[TeslimGun] - RELATED(Tedarikciler[SozGun]))",{grid:[TED,YIL],follow:"Takip: Ortalama negatif çıkmasına rağmen siparişlerin dörtte birinden fazlası geç. Bu nasıl mümkün ve hangi ölçüyü yanına koyarsın? (Cevap: erken teslimler geç teslimleri dengeler; geciken sipariş oranı ve yalnızca gecikenlerdeki ortalama aşım ayrıca gösterilmeli.)"}),d("m-13","B","Premium Segment Payı %","<b>Premium Segment Payı %</b>: Premium segmentindeki müşterilerin net satışının görünen net satışa oranı. Segment kırılımında Premium satırı %100, diğer segmentler boş olmalı.",'DIVIDE(CALCULATE([Net Satış], KEEPFILTERS(Musteriler[Segment] = "Premium")), [Net Satış])',{grid:[SEG,YIL,KANAL],follow:"Takip: KEEPFILTERS olmadan Bireysel satırında ne görürdün? (Cevap: segment filtresi ezilir; Premium satışı Bireysel satışına bölünür ve anlamsız bir oran çıkar.)"}),d("m-14","B","Teslim Tarihine Göre Sipariş","<b>Teslim Tarihine Göre Sipariş</b>: <code>[Sipariş Sayısı]</code>nı sipariş tarihine göre değil, teslim tarihine (<code>Satislar[TeslimTarihi]</code>, ilişkisi pasif) göre say.","CALCULATE([Sipariş Sayısı], USERELATIONSHIP(Satislar[TeslimTarihi], Tarih[Tarih]))",{grid:[AY],noTotal:!0,follow:"Takip: Henüz teslim edilmemiş (Kargoda) siparişler bu ölçüde nerede görünür? (Cevap: TeslimTarihi boş olduğu için hiçbir ay satırına düşmez ama tarih filtresi olmayan toplamda sayılır; bu modelde 838 siparişin 6’sı böyledir, ayların toplamı 832 kalır. Bunu raporda ayrıca göstermek gerekir.)"}),d("m-15","B","Kalan Yıllık Gider Bütçesi","<b>Kalan Yıllık Gider Bütçesi</b>: içinde bulunulan yılın tüm yıllık gider bütçesinden, yılbaşından görünen dönemin sonuna kadar gerçekleşen gideri çıkar.","CALCULATE([Gider Bütçe], ALL(Tarih), VALUES(Tarih[Yil])) - TOTALYTD([Gider], Tarih[Tarih])",{grid:[AY],noTotal:!0,follow:"Takip: Birden çok yıl seçili olduğunda (ör. toplam satırı) bu ölçü neden anlamını yitirir ve ne döndürmesini istersin? (Cevap: yıllık bütçe tüm yılların toplamı olur, YTD ise yalnızca son yılı biriktirir; HASONEVALUE(Tarih[Yil]) ile tek yıl yoksa BLANK döndürmek daha doğrudur.)"}),d("m-16","C","Departman Bütçe Sapması","<b>Departman Bütçe Sapması</b>: departmanın gideri ile sorumlu olduğu gider türlerinin bütçesi arasındaki fark. <code>GiderButce</code>’de departman yok; bütçeyi <code>GiderTurleri[DepartmanNo]</code> üzerinden departmana bağla (ilişki eklemeden).",`VAR Butce = CALCULATE([Gider Bütçe], TREATAS(VALUES(Departmanlar[DepartmanNo]), GiderTurleri[DepartmanNo]))
RETURN [Gider] - Butce`,{grid:[DEP,YIL,GTUR],follow:"Takip: Bir gider türünün bütçesi iki departman arasında %70–%30 paylaştırılsaydı modeli nasıl değiştirirdin? (Cevap: tür × departman × pay oranı içeren bir paylaştırma tablosu ve bütçeyi bu oranla çarpan SUMX tabanlı bir ölçü.)"}),d("m-17","C","Tedarikçi Karnesi Puanı","<b>Tedarikçi Karnesi Puanı</b>: her tedarikçi için 0,6 × <code>[Tedarikte Zamanında %]</code> + 0,4 × (1 − <code>[Kusur Oranı %]</code>) puanı; toplam satırında bu puanların tedarikçiler arasındaki basit ortalaması görünmeli.","AVERAGEX(VALUES(Tedarikciler[Tedarikci]), 0.6 * [Tedarikte Zamanında %] + 0.4 * (1 - [Kusur Oranı %]))",{grid:[TED,YIL],follow:"Takip: Toplamda basit ortalama yerine sipariş ağırlıklı bir puan istenirse ne değişir? (Cevap: puanı doğrudan toplam oranlardan hesaplamak ya da AVERAGEX yerine sipariş sayısıyla ağırlıklandırılmış SUMX / toplam sipariş kullanmak.)"}),d("m-18","C","Alıcıların Talep Sayısı","<b>Alıcıların Talep Sayısı</b>: görünen bağlamda (iptal olmayan) alışveriş yapmış müşterilerin açtığı müşteri hizmetleri talebi sayısı. Kategori kırılımında, o kategoriden alışveriş yapan müşterilerin talepleri sayılmalı.",`VAR Alicilar = CALCULATETABLE(VALUES(Satislar[MusteriNo]), Satislar[Durum] <> "İptal")
RETURN CALCULATE([Talep Sayısı], TREATAS(Alicilar, Musteriler[MusteriNo]))`,{grid:[YIL,SEG,KAT],follow:"Takip: Neden `CALCULATE([Talep Sayısı], Alicilar)` yazmak kategori kırılımında işe yaramaz? (Cevap: Alicilar Satislar[MusteriNo] sütununa ait; filtre Satislar’ı keser ama ilişki yönü yüzünden Musteriler’e ve Talepler’e ulaşmaz. TREATAS ile müşteri boyutuna aktarmak gerekir.)"}),d("m-19","C","Hareketli 12 Ay Gider Oranı %","<b>Hareketli 12 Ay Gider Oranı %</b>: görünen dönemin sonundan geriye 12 aylık giderin, aynı 12 aydaki net satışa oranı.",`VAR Donem = DATESINPERIOD(Tarih[Tarih], MAX(Tarih[Tarih]), -12, MONTH)
RETURN DIVIDE(CALCULATE([Gider], Donem), CALCULATE([Net Satış], Donem))`,{grid:[AY],noTotal:!0,follow:"Takip: Verinin ilk 11 ayında bu oran neden yüksek ve oynak çıkar, raporda nasıl ele alırsın? (Cevap: 12 aylık pencere dolmamıştır ve ilk aylarda satış düşüktür; pencerede 12 ay veri yoksa BLANK döndürmek ya da bunu açıkça işaretlemek gerekir.)"}),{id:"m-20",L:"C",t:"query",start:`EVALUATE
`,q:'<b>Tedarikçi karnesi sorgusu</b>: 2024 yılı için her tedarikçinin adını, <code>"Zamanında %"</code> (<code>[Tedarikte Zamanında %]</code>), <code>"Kusur %"</code> (<code>[Kusur Oranı %]</code>) ve <code>"Sipariş"</code> (satın alma satırı sayısı) sütunlarıyla döndür; zamanında oranına göre azalan sırala.',sol:`EVALUATE
CALCULATETABLE(
  ADDCOLUMNS(VALUES(Tedarikciler[Tedarikci]), "Zamanında %", [Tedarikte Zamanında %], "Kusur %", [Kusur Oranı %], "Sipariş", CALCULATE(COUNTROWS(SatinAlmalar))),
  Tarih[Yil] = 2024
)
ORDER BY [Zamanında %] DESC`,follow:'Takip: "Sipariş" sütununda CALCULATE’i kaldırırsan ne görürsün? (Cevap: bağlam geçişi olmadığı için her tedarikçide 2024’ün toplam satır sayısı, 138, görünür.)'})})()})(window),(function(){window.PBI_IV_BANK.push({id:"iv-s01",role:"analist",cat:"Senaryo",q:"Yeni bir raporu 200 kişiye dağıtacaksın. Paylaşım, uygulama ve çalışma alanı rolü arasında nasıl karar verirsin?",weak:"Raporu paylaşırım, herkese bağlantı gönderirim.",strong:"200 kişi ve düzenli kullanım varsa uygulama açarım: okuyucu çalışma alanını görmez, kitleler var, grup yönetimi kolay. Rol yalnız birlikte geliştiren ekibe. Doğrudan paylaşımı birkaç kişilik tek seferlik işte kullanırım. Hangi kitlenin ne göreceğini önce yazar, RLS’i Görüntüleyici gibi sınarım; lisansı da unutmam: kapasite F64 altındaysa herkes Pro ister.",why:"Sayı, sıklık, RLS ve lisansı birlikte düşünüyor.",follow:"Uygulamaya sonradan eklediğin rapor neden kullanıcıya görünmeyebilir?"},{id:"iv-s02",role:"analist",cat:"Senaryo",q:"Yönetici “rapor eski görünüyor” dedi. Yenileme geçmişi yeşil. Ne yaparsın?",weak:"Elle yenilerim, olmazsa destek açarım.",strong:"Önce modeldeki son iş tarihine bakarım, çünkü yeşil yalnız yenilemenin bittiğini söyler. Üst adım geç bitmiş, kaynak dosya gelmemiş ya da OneDrive yenilemesi veri yenilemesi sanılmış olabilir. Sonra zinciri saat yerine olaya bağlar, raporda iş tarihini gösteren bir kart bırakırım. Kullanıcıya hangi sayının ne zamana ait olduğunu açıkça yazarım.",why:"Görünür belirtiden kök nedene gidiyor ve tekrarını önlüyor.",follow:"Zamanlama kendiliğinden kapanmış olsaydı hangi iki kurala bakardın?"},{id:"iv-s03",role:"gelistirici",cat:"Güvenlik ve yönetişim",q:"Bölge müdürleri RLS’e rağmen tüm bölgeleri görüyor. Neye bakarsın?",weak:"DAX filtresini kontrol ederim.",strong:"Önce nasıl geldiklerine bakarım: çalışma alanında Katkıda bulunan ya da üstü iseler RLS uygulanmaz. Sonra rol üyeliği, “Farklı görüntüle” ile sınama, kuralın doğru tablo üzerinde olması ve ilişki yönü. Son kullanıcıyı Görüntüleyici ya da uygulamadan getiririm. Kimin hangi yolla erişeceğini tablo olarak yazarım.",why:"En sık gerçek nedeni, rolü, koda bakmadan önce kontrol ediyor.",follow:"Görüntüleyici Derleme izni alırsa RLS yine çalışır mı?"},{id:"iv-s04",role:"gelistirici",cat:"Senaryo",q:"Şirket içi SQL ile SharePoint’teki hedefleri birleştiren modelin yenilenmesini nasıl kurarsın?",weak:"Ağ geçidi kurarım, olur.",strong:"Sürekli açık sunucuda standart mod ağ geçidi, kritikse iki düğümlü küme kurarım; kurtarma anahtarı kurumsal kasada durur. SQL için bağlantı oluşturup adları .pbix ile aynı yazarım. SharePoint aynı sorguda birleşiyorsa bir model tek ağ geçidi bağlantısı kullandığı için bulut kaynağını da aynı kümede tanımlarım ve gizlilik düzeylerini bağlantıda veririm. Hata bildirimini ekip listesine yönlendirir, ilk yenilemeyi elle yaparım.",why:"Mixed source kuralını, kümeyi ve gizlilik ayrıntısını biliyor.",follow:"Bu birleştirme yüzünden sorgu katlanmazsa ne yaparsın?"},{id:"iv-s05",role:"analist",cat:"Power Query",q:"Birleştirme sonrası yeni sütun boş geldi, hata yok. Teşhisin?",weak:"Birleştirme türünü değiştiririm.",strong:"Merge büyük/küçük harfe ve boşluğa duyarlı, türler de aynı olmalı. Sol karşıt birleştirmeyle eşleşmeyenleri sayar, örnek değerlere bakarım. Sonra iki tarafta da anahtarı kırpar, harf biçimini tekleştiririm. Ters durumda satır sayısı artmışsa sağda yinelenen anahtar var demektir. Birleştirmeden önce ve sonra satır sayısını karşılaştırmak alışkanlığımdır.",why:"Sessiz hatayı ölçüyor ve ters belirtiyi de biliyor.",follow:"Model ilişkisi mi kurarsın, birleştirir misin? Neye göre?"},{id:"iv-s06",role:"hepsi",cat:"Kavram",q:"Pano ile rapor arasındaki farkı anlat. Bugün panoyu ne zaman seçersin?",weak:"İkisi de aynı şey, biri daha özet.",strong:"Pano Service’te tek sayfa, farklı model ve raporlardan kutucuk toplar, dilimleyicisi yoktur, klasik veri uyarısı burada kurulur. Rapor tek modele bağlı, çok sayfalı, etkileşimli. Tek modelde seçim gerekiyorsa rapor; birden çok modelden tek bakış ve uyarı gerekiyorsa pano. Yeni tasarımda Soru-Cevap’a dayanmam, kaldırılıyor.",why:"Tanımı karara bağlıyor ve güncel durumu biliyor.",follow:"Veri uyarısı model günde bir yenileniyorsa ne sıklıkla çalışır?"},{id:"iv-s07",role:"gelistirici",cat:"Performans",q:"Kapasite kısıtlaması görüyorsun. İlk adımın?",weak:"Bir üst SKU’ya geçeriz.",strong:"Capacity Metrics’te Sistem durumu ve İşlem sayfalarından hangi öğenin ne zaman tükettiğini bulurum. Gece yenilemeleri üst üste mi, geliştirme not defteri üretim kapasitesinde mi? Saatleri yayar, ağır işi ayırırım. Rapor yavaş ama kapasite rahatsa sorun modeldedir; Performans Analizi kullanırım. SKU en son karardır ve gerekçesi yazılıdır.",why:"Para harcamadan önce nedeni ölçüyor.",follow:"Kullanım ölçümleri raporu bu soruda ne kadar işe yarar?"},{id:"iv-f11",role:"fabric",cat:"Fabric",q:"Fabric’e veri getirmek için kısayol, yansıtma, Copy job, Dataflow Gen2 ve not defteri arasında nasıl seçersin?",weak:"Genelde işlem hattı kullanırım.",strong:"Dört soru sorarım: kopya gerekli mi, ne kadar taze olmalı, dönüşüm ne kadar karmaşık, ekip ne biliyor? Kopya istemiyorsam kısayol. Operasyonel veritabanını kodsuz yakın gerçek zamanlı için yansıtma, hedefi salt okunurdur. Çok tablolu artımlı taşıma için Copy job. Power Query bilen ekipte temizlik Dataflow Gen2; karmaşık ve büyükse not defteri. İşlem hattı bunları sıralar, kendisi dönüştürmez.",why:"Araç listesi yerine karar ölçütü veriyor.",follow:"Şirket içi kaynak varsa bu tablo nasıl değişir?"},{id:"iv-f12",role:"fabric",cat:"Fabric",q:"Filigranla artımlı işlem hattını anlat. Neler bozulabilir?",weak:"Yalnız yeni satırları alırım.",strong:"Lookup ile eski filigranı, ikinci Lookup ile kaynağın en büyük değerini okurum. Copy aralığı alır, başarıda yordam filigranı günceller. Üst sınırı sabitlemek çalışma sırasında gelen satırı sonraki geceye bırakır. Riskler: yeniden denemede çift satır, silinenlerin görünmemesi, geç gelen satırlar. Hedefi anahtarla birleştirir, silme için CDC ya da karşılaştırma düşünürüm. Basitse Copy job yeterlidir.",why:"Kalıbın yanında kenar durumları ve idempotentliği biliyor.",follow:"Filigran neden kopyadan önce güncellenmez?"},{id:"iv-f13",role:"fabric",cat:"Fabric",q:"Direct Lake on OneLake ile on SQL arasında nasıl seçersin?",weak:"OneLake daha yeni, onu seçerim.",strong:"Tek ölçüt değil. SQL biçimi uç nokta üzerinden izin denetler, görünüm ve SQL RLS varsa DirectQuery’ye düşer; sınır aşılırsa düşme açıksa çalışır. OneLake biçimi düşmez, sınır aşılırsa yenileme başarısız olur, SQL RLS uygulanmaz, birden çok öğe ve Import ile bileşik çalışır. Güvenlik uç noktadaysa ve görünüm şartsa SQL, ama düşmeyi izlerim; tahmin edilebilirlik ve çok kaynak istiyorsam OneLake. Görünümü Delta tabloya çevirmek kalıcı çözümdür.",why:"Güvenlik, düşme ve sınır davranışını birlikte değerlendiriyor.",follow:"Gece hattında otomatik güncellemeyi neden kapatırsın?"},{id:"iv-f14",role:"fabric",cat:"Fabric",q:"OneLake güvenliği ve modeldeki RLS arasındaki fark ne?",weak:"İkisi de satır güvenliği.",strong:"Model RLS’i raporun kapısıdır, Spark’ı ya da uç noktayı durdurmaz. OneLake rolleri gölün kapısıdır, klasör, tablo, satır, sütun tanımlar ve varsayılan reddeder; ama Yönetici, Üye, Katkıda bulunana uygulanmaz. Bu yüzden veri bilimci Üye ise dosyayı okur. Ben erişim yollarını yazar, her yol için kapıyı belirlerim.",why:"Rollerin istisnasını ve erişim yollarını biliyor.",follow:"Devredilen kısayolda kullanıcının kaynak izni aranır mı?"},{id:"iv-f15",role:"fabric",cat:"Fabric",q:"Copilot’u ekibe önerir misin? Ne söylersin?",weak:"Evet, her şeyi yazar, işi hızlandırır.",strong:"Başlangıç iskeleti, açıklama, hata okuma için evet. Şartları söylerim: ücretli F2+ ya da P kapasite, denemede yok, kiracı ayarı, tüketim. Bir özelliğin önizleme olabileceğini ve resmî sayfaya bakmak gerektiğini söylerim. Çıktıyı bilinen sayıyla sınarız, kritik işte kimin onayladığını yazarız. Data Factory’de desteklenmeyen istek sessiz kalabilir; bunu test ederiz.",why:"Faydayı abartmıyor, şart ve doğrulamayı söylüyor.",follow:"Copilot Net Satış’ı yanlış buldu. Nereden başlarsın?"},{id:"iv-f16",role:"fabric",cat:"Fabric",q:"Lakehouse’ta tunç, gümüş, altın düzeni kuruyorsun. Rapor nereden okur, neden?",weak:"En temiz olandan okur.",strong:"Rapor altından okur: ad ve anlam sözleşmesi orada tutulur, gümüşteki içi değişiklik raporu kırmaz. Tunçta ham veri değişmeden durur, hatalı dönüşümde yeniden üretmek için. Gümüşte tür, tekillik, kurallar; altında yıldız şema. Geçişlerde satır ve toplam mutabakatı işlem hattının adımıdır. Düzen tek doğru değil, ekip kuralını yazar.",why:"Katmanların nedenini ve mutabakatı açıklıyor.",follow:"SQL analiz uç noktası bu düzende neyi yapamaz?"}),window.PBI_IV_BANK.push({id:"iv-m01",role:"analist",cat:"Power Query",q:"Power Query’de M kodunu hiç elle düzenledin mi? Ne zaman gerekir?",weak:"Şerit her şeyi yapar, koda bakmam.",strong:"Çoğu adımı şeritten yaparım ama formül çubuğunu hep açık tutarım. Elle yazdığım yerler: dinamik sütun listesi, tek sorguda tekrarlanan iş için fonksiyon, try ile hata sütunu. Yazdıktan sonra adım adlarını okunur yaparım.",why:"Şerit ile kodu rakip değil tamamlayıcı görüyor ve somut örnek veriyor.",follow:"each ne demek, _ nereden geliyor?"},{id:"iv-m02",role:"analist",cat:"Power Query",q:"Unpivot ile Pivot’u hangi durumda seçersin?",weak:"Tabloyu daha güzel gösteren hangisiyse.",strong:"Model için hedef uzun tablodur, ay sütunlu dosyada Unpivot Other Columns kullanırım çünkü yeni ay da içeri girer. Pivot’u anahtar değer çiftinden satır başına tek nesne çıkarırken ya da sunum tablosunda kullanırım; modelin sütunu yenilemede değişmesin diye dikkat ederim.",why:"Kararı model ve yenilemeye bağlıyor.",follow:"Pivot’ta toplama seçmezsen ne olur?"},{id:"iv-m03",role:"gelistirici",cat:"Power Query",q:"Query Folding nedir, bozulduğunu nasıl anlarsın, ne yaparsın?",weak:"Sorgu hızlı çalışınca katlanıyor demektir.",strong:"Adımların tek kaynak sorgusuna çevrilmesidir; DirectQuery için zorunlu, Import’ta yenilemeyi hızlandırır. View Native Query’ye bakarım ama soluk olması kesin kanıt değil; tanılama ya da kaynak izleme ile doğrularım. Bozan adımı bulur, sonrasını öne alır, gerekirse görünüme taşırım.",why:"Kontrol yöntemini ve sınırını biliyor.",follow:"Artımlı yenileme katlanmazsa ne olur?"},{id:"iv-m04",role:"gelistirici",cat:"Power Query",q:"Table.Buffer’ı ne zaman kullanırsın?",weak:"Yavaş sorguları hızlandırmak için her zaman.",strong:"Nadiren. Tüm satırları belleğe alır, sonraki adımların katlanmasını durdurur; Learn de yavaşlatabileceğini söyler. Bir listeyi satır fonksiyonunda defalarca okumayı önlerken List.Buffer, sırayı sabitlemek gerekirse Table.Buffer. Yalnız katlamayı durdurmak için Table.StopFolding. Ölçmeden eklemem.",why:"Efsaneyi düzeltiyor, ölçüm istiyor.",follow:"Buffer’ın sığ olması ne demek?"},{id:"iv-m05",role:"gelistirici",cat:"Power Query",q:"Aynı temizliği 12 dosyada yapman gerekiyor. Nasıl kurarsın?",weak:"Her dosya için ayrı sorgu kopyalarım.",strong:"Klasör bağlayıcısı, uzantı süzgeci, tek dosyayı okuyan fonksiyon, her satırda çağırma, genişletme, en sonda tür. Dosya adı sütununu tutarım ki hatalı satırın kaynağı belli olsun. Dosya yapısını sözleşme gibi görürüm, klasör yolunu parametre yaparım.",why:"Tekrarı fonksiyona indiriyor ve hata izlenebilirliğini düşünüyor.",follow:"Column1 bulunamadı hatası neden çıkar?"},{id:"iv-m06",role:"gelistirici",cat:"Power Query",q:"Value.NativeQuery ne zaman uygun, riskleri ne?",weak:"SQL yazınca her zaman daha hızlıdır.",strong:"Şeritle ifade edilemeyen bir SELECT gerekiyorsa. Parametre kaydıyla geçiririm, metin birleştirmem. Sonraki adımlar çoğu zaman katlanmaz, bu yüzden işi sorguya koyarım. DirectQuery düz SELECT ister, artımlı yenileme tüm satırı çeker. Veri değiştiren ifade de çalışabileceği için salt okunur hesap kullanırım. Çoğu zaman görünüm daha iyidir.",why:"Güvenlik ve yenilemeyi birlikte görüyor.",follow:"Kaynakta görünüm yazma iznin yoksa?"},{id:"iv-m07",role:"analist",cat:"Power Query",q:"Hatalı satırlarla nasıl başa çıkarsın?",weak:"Remove Errors derim, rapor çalışır.",strong:"Önce Keep Errors ile hangi satır olduğunu görürüm. Bilinen işaret varsa türden önce null yaparım; az sayıda bozuk satırda try otherwise ile değer verir, hatalıları ayrı sorguda denetim sayfasına alırım. Satır sayısını kaynakla karşılaştırırım; silmek sessiz yanlıştır.",why:"Sessiz veri kaybını önlüyor.",follow:"try neyi yakalamaz?"},{id:"iv-m08",role:"hepsi",cat:"Power Query",q:"Tableau ya da SSIS biliyorum diye gelen birini ekibe alsan ilk neyi öğretirsin?",weak:"Aynı şeyler, kısa sürede alışır.",strong:"Kavram eşlenir ama düşünme değişir: Tableau’dan gelene model ve filtre bağlamını, SSIS’ten gelene işi kaynağa bırakmayı ve Power Query’nin katlamasını öğretirim. İlk görev: küçük yıldız şema ve üç ölçü.",why:"Farkı biliyor, abartmıyor.",follow:"LOD ifadesi DAX’ta neye denk gelir?"})})();

